        'A1':  2,  'A2':  3,  'A3':  4,  'A4':  5,
        'D2':  8,  'D3': 26,  'D6': 27,  'D9': 28,
        'D11': 7,  'D12': 6,  'D13': 15,
        'TX': 11,  'RX': 12,
