    '205:57': 'STEPPER_RUN_SPEED', '205:58': 'STEPPER_STOP', '205:59': 'STEPPER_SET_POSITION',
    '205:60': 'STEPPER_ENABLE', '205:61': 'STEPPER_SET_LIMITS', '205:62': 'STEPPER_READ',
