// Resolve a decoded frame's command to a readable name (hex fallback).
function frameName(target, cmd) {
    if (cmd === CMD_MESSAGE) return 'MESSAGE';
    if (cmd === CMD_SHARE)   return 'SHARE';
    const key = target < RESERVED_START ? `core:${cmd}` : `${target}:${cmd}`;
    return _FRAME_NAMES[key] || `0x${cmd.toString(16).padStart(2, '0').toUpperCase()}`;
}

// -------------------------------------------------------------------
// Frame encoding
//
// params is a plain JS number array. Integer values encode as int32,
// any value with a decimal part encodes as float32. The TYPE_MASK
// records which params are float so the Arduino can decode correctly.
// -------------------------------------------------------------------
function encodeFrame(cmd, target, params = [], payload = null) {
    if (!Number.isInteger(target) || target < 0 || target > 0xFFFF) {
        throw new RangeError(
            `Pardalote: encodeFrame target must be an integer in [0, 65535], got ${target}`
        );
    }
    let payloadBytes;
    if (payload == null) {
        payloadBytes = null;
    } else if (typeof payload === 'string') {
        payloadBytes = new TextEncoder().encode(payload);
    } else if (payload instanceof ArrayBuffer) {
        payloadBytes = new Uint8Array(payload);
    } else {
        payloadBytes = payload;   // assume Uint8Array
    }
    const payloadLen = payloadBytes ? payloadBytes.length : 0;

    const buf = new ArrayBuffer(8 + params.length * 4 + payloadLen);
    const v   = new DataView(buf);

    let typeMask = 0;
    params.forEach((p, i) => { if (!Number.isInteger(p)) typeMask |= (1 << i); });

    v.setUint8(0,  cmd);
    v.setUint16(1, target,   false);
    v.setUint8(3,  params.length);
    v.setUint16(4, typeMask, false);
    v.setUint16(6, payloadLen, false);

    params.forEach((p, i) => {
        const off = 8 + i * 4;
        Number.isInteger(p)
            ? v.setInt32(off,   p, false)
            : v.setFloat32(off, p, false);
    });

    if (payloadBytes) {
        new Uint8Array(buf, 8 + params.length * 4).set(payloadBytes);
    }

    return buf;
}

// -------------------------------------------------------------------
// Frame decoding — returns null if the buffer is too short.
// -------------------------------------------------------------------
function decodeFrame(buf, pos) {
    if (pos + 8 > buf.byteLength) return null;
    const v = new DataView(buf);

    const cmd        = v.getUint8(pos);
    const target     = v.getUint16(pos + 1, false);
    const nparams    = v.getUint8(pos + 3);
    const typeMask   = v.getUint16(pos + 4, false);
    const payloadLen = v.getUint16(pos + 6, false);
    const totalLen   = 8 + nparams * 4 + payloadLen;

    if (pos + totalLen > buf.byteLength) return null;

    const params = [];
    for (let i = 0; i < nparams; i++) {
        const off = pos + 8 + i * 4;
        params.push((typeMask >> i) & 1
            ? v.getFloat32(off, false)
            : v.getInt32(off,   false));
    }

    const payload = payloadLen > 0
        ? buf.slice(pos + 8 + nparams * 4, pos + totalLen)
        : null;

    return { cmd, target, params, payload, totalLen };
}

// -------------------------------------------------------------------
// Batch multiple encoded frames into a single ArrayBuffer for sending.
// -------------------------------------------------------------------
function encodeBatch(frames) {
    const total = frames.reduce((n, f) => n + f.byteLength, 0);
    const out   = new Uint8Array(total);
    let pos = 0;
    for (const f of frames) { out.set(new Uint8Array(f), pos); pos += f.byteLength; }
    return out.buffer;
}

// -------------------------------------------------------------------
// Encode a CMD_MESSAGE frame. The value type is inferred from the JS
// value (boolean→bool, integer→int, fractional→float, string→text,
// Uint8Array/ArrayBuffer→blob); override with opts.type ('char' is the
// one that can't be inferred — a JS char is just a length-1 string).
//
//   Layout: TARGET = (flags << 8) | type ;  PAYLOAD = [keyLen][key][value?]
//
// Built by hand (not via encodeFrame) so the FLOAT type tag and the
// param's float32 encoding always agree, even for whole-number floats.
// -------------------------------------------------------------------
function encodeMessage(key, value, opts = {}) {
    const t = opts.type;
    let type, param = null, isFloat = false, valueBytes = null;

    if (t === 'char') {
        type  = MSG_TYPE_CHAR;
        param = (typeof value === 'string' ? value.charCodeAt(0) : (value | 0)) & 0xFF;
    } else if (t === 'bool' || (t == null && typeof value === 'boolean')) {
        type = MSG_TYPE_BOOL; param = value ? 1 : 0;
    } else if (t === 'float' || (t == null && typeof value === 'number' && !Number.isInteger(value))) {
        type = MSG_TYPE_FLOAT; param = value; isFloat = true;
    } else if (t === 'int' || (t == null && typeof value === 'number')) {
        type = MSG_TYPE_INT; param = value | 0;
    } else if (t === 'text' || (t == null && typeof value === 'string')) {
        type = MSG_TYPE_TEXT; valueBytes = new TextEncoder().encode(String(value));
    } else if (t === 'blob' || value instanceof Uint8Array || value instanceof ArrayBuffer) {
        type = MSG_TYPE_BLOB;
        valueBytes = value instanceof ArrayBuffer ? new Uint8Array(value) : value;
    } else {
        throw new Error(`Pardalote: cannot send message "${key}" — unsupported value type`);
    }

    const flags  = (opts.retain ? MSG_FLAG_RETAIN : 0) | (opts.broadcast ? MSG_FLAG_BROADCAST : 0);
    const target = ((flags & 0xFF) << 8) | (type & 0xFF);

    let keyBytes = new TextEncoder().encode(String(key));
    if (keyBytes.length > MAX_MESSAGE_KEY) {
        // Silently truncated here; Arduino.send() reports it on the 'warn' channel.
        keyBytes = keyBytes.subarray(0, MAX_MESSAGE_KEY);
    }
    const kl      = keyBytes.length;
    const vlen    = valueBytes ? valueBytes.length : 0;
    const nparams = param === null ? 0 : 1;

    const buf   = new ArrayBuffer(8 + nparams * 4 + 1 + kl + vlen);
    const v     = new DataView(buf);
    v.setUint8(0, CMD_MESSAGE);
    v.setUint16(1, target, false);
    v.setUint8(3, nparams);
    v.setUint16(4, isFloat ? 0x0001 : 0x0000, false);   // TYPE_MASK: bit0 for the float param
    v.setUint16(6, 1 + kl + vlen, false);               // PAYLOAD_LEN
    if (nparams) {
        if (isFloat) v.setFloat32(8, param, false);
        else         v.setInt32(8, param, false);
    }
    const bytes    = new Uint8Array(buf);
    const payStart = 8 + nparams * 4;
    bytes[payStart] = kl;
    bytes.set(keyBytes, payStart + 1);
    if (vlen) bytes.set(valueBytes, payStart + 1 + kl);
    return buf;
}

// Decode a CMD_MESSAGE frame → { key, value, type } (type is a name string).
function decodeMessage(frame) {
    const type = frame.target & 0xFF;
    const p    = frame.payload ? new Uint8Array(frame.payload) : null;
    if (!p || p.length < 1) return null;
    const keyLen = p[0];
    if (1 + keyLen > p.length) return null;
    const key = new TextDecoder().decode(p.subarray(1, 1 + keyLen));

    let value;
    switch (type) {
        case MSG_TYPE_INT:   value = frame.params.length ? (frame.params[0] | 0) : 0; break;
        case MSG_TYPE_BOOL:  value = !!(frame.params.length && frame.params[0]);      break;
        case MSG_TYPE_FLOAT: value = frame.params.length ? frame.params[0] : 0;       break;
        case MSG_TYPE_CHAR:  value = String.fromCharCode((frame.params[0] || 0) & 0xFF); break;
        case MSG_TYPE_TEXT:  value = new TextDecoder().decode(p.subarray(1 + keyLen)); break;
        case MSG_TYPE_BLOB:  value = p.slice(1 + keyLen);                              break;  // Uint8Array
        default: return null;
    }
    return { key, value, type: MSG_TYPE_NAMES[type] || `type${type}` };
}

// ===================================================================
// Serial transport (Web Serial) — the same binary frames, carried over
// USB serial instead of a WebSocket. Chrome/Edge only.
//
// A WebSocket gives the protocol message boundaries and reliability; a
// raw byte stream has neither, so each message travels in an envelope
// (mirrors internal/serial_transport.h on the firmware side):
//
//   0x00  0xA5  COBS( message bytes + CRC8 )  0x00
//
// COBS guarantees no 0x00 inside the body, so the decoder always
// resyncs on the next delimiter — a corrupted byte costs one message,
// never the link. Bytes OUTSIDE envelopes are the sketch's own
// Serial.print output: collected line by line and surfaced as the
// 'log' event, so students see their debug prints in the browser
// without opening the IDE.
// ===================================================================

// CRC8, poly 0x07, init 0x00 — must match the firmware.
function _crc8(bytes) {
    let crc = 0;
    for (let i = 0; i < bytes.length; i++) {
        crc ^= bytes[i];
        for (let b = 0; b < 8; b++)
            crc = (crc & 0x80) ? ((crc << 1) ^ 0x07) & 0xFF : (crc << 1) & 0xFF;
    }
    return crc;
}

// Canonical COBS encode (each block: code byte = run+1, then the run;
// a message ending on a zero or a full 254-run gets a final 0x01 block).
function _cobsEncode(src) {
    const out = [];
    let blockStart = 0, code = 1;
    out.push(0);   // placeholder for the first code byte
    for (let i = 0; i < src.length; i++) {
        if (src[i] === 0) {
            out[blockStart] = code;
            blockStart = out.length; out.push(0); code = 1;
        } else {
            out.push(src[i]); code++;
            if (code === 0xFF) {
                out[blockStart] = code;
                blockStart = out.length; out.push(0); code = 1;
            }
        }
    }
    out[blockStart] = code;
    return Uint8Array.from(out);
}

// COBS decode — null on malformed input.
function _cobsDecode(src) {
    const out = [];
    let i = 0;
    while (i < src.length) {
        const code = src[i++];
        if (code === 0 || i + code - 1 > src.length) return null;
        for (let j = 1; j < code; j++) out.push(src[i++]);
        if (code !== 0xFF && i < src.length) out.push(0);
    }
    return Uint8Array.from(out);
}

// Wrap one outbound message (ArrayBuffer or Uint8Array) in the envelope.
function _serialEnvelope(msg) {
    const bytes = msg instanceof Uint8Array ? msg : new Uint8Array(msg);
    const withCrc = new Uint8Array(bytes.length + 1);
    withCrc.set(bytes);
    withCrc[bytes.length] = _crc8(bytes);
    const body = _cobsEncode(withCrc);
    const out  = new Uint8Array(body.length + 3);
    out[0] = 0x00; out[1] = 0xA5;
    out.set(body, 2);
    out[out.length - 1] = 0x00;
    return out;
}

// -------------------------------------------------------------------
// _SerialLink — wraps a Web Serial port behind the same surface the
// Arduino class uses of a WebSocket: send(buf) / close() and the
// onopen / onclose / onerror / onmessage handler slots (plus onlog for
// the sketch's Serial.print text). Serial has no CONNECTED event on
// the board side, so after opening we probe with a HELLO frame every
// 500 ms until the first valid envelope arrives — the board answers a
// HELLO request with its full HELLO → announce → SYNC_COMPLETE sync
// even if it never noticed the previous page go away.
// -------------------------------------------------------------------
class _SerialLink {
    constructor(port, opts = {}) {
        this.port      = port;
        this.onopen    = null;
        this.onclose   = null;
        this.onerror   = null;
        this.onmessage = null;
        this.onlog     = null;

        // takeover: probe carries the "switch a WiFi board to USB" flag (only
        // when a picker gesture authorised it). key: board-identity key, sent
        // as a CMD_AUTH frame in the probe loop when set.
        this._takeover = !!opts.takeover;
        this._key      = opts.key || null;

        this._writer = null;
        this._reader = null;
        this._closed = false;
        this._probeTimer = null;
        this._noReplyTimer = null;
        this._sawReply = false;

        // Envelope decoder state: 0 = text, 1 = just saw 0x00, 2 = in frame.
        this._state = 0;
        this._frame = [];
        this._text  = [];
    }

    async open() {
        // A predecessor link on this port may still be closing — wait it out.
        if (this.port._pardaloteClosing) {
            await this.port._pardaloteClosing.catch(() => {});
            this.port._pardaloteClosing = null;
        }
        await this.port.open({ baudRate: 115200 });
        this._writer = this.port.writable.getWriter();
        this._readPromise = this._readLoop();   // deliberately not awaited here
        if (this.onopen) this.onopen();
        // Probe until the board answers (it may be rebooting — opening the
        // port toggles DTR, which resets many boards). Each tick sends the key
        // first (if set) then the HELLO probe carrying the takeover flag, so a
        // board that DTR-reset into WiFi-listen mode still sees both after it
        // comes back up.
        this._probeTimer = setInterval(() => this._probe(), 500);
        this._probe();
        // One-time "no response yet" hint if nothing answers within the grace
        // window (keep probing — an ESP32 may still be rebooting).
        this._noReplyTimer = setTimeout(() => {
            if (this._sawReply || this._closed) return;
            if (this.onlog) this.onlog(
                'No response from the board over USB yet — it may still be booting, ' +
                'may not be running a Pardalote sketch, or may be WiFi-only ' +
                '(begin(PARDALOTE_WIFI) boards do not accept USB).');
        }, 4500);
    }

    _probe() {
        try {
            if (this._key) this.send(encodeFrame(CMD_AUTH, 0, [], this._key));
            this.send(encodeFrame(CMD_HELLO, 0, this._takeover ? [1] : []));
        } catch (_) {}
    }

    async _readLoop() {
        try {
            this._reader = this.port.readable.getReader();
            for (;;) {
                const { value, done } = await this._reader.read();
                if (done) break;
                if (value) this._feed(value);
            }
        } catch (_) {
            // device lost mid-read — fall through to the close path
        } finally {
            try { if (this._reader) this._reader.releaseLock(); } catch (_) {}
            this._reader = null;
            if (!this._closed) {
                this._teardown();
                if (this.onclose) this.onclose({ code: 0 });
            }
        }
    }

    _feed(bytes) {
        for (let i = 0; i < bytes.length; i++) {
            const b = bytes[i];
            switch (this._state) {
                case 0:   // text — the sketch's Serial.print output
                    if (b === 0x00)      { this._flushText(); this._state = 1; }
                    else if (b === 0x0A) { this._flushText(); }
                    else if (b !== 0x0D) { this._text.push(b); }
                    break;
                case 1:   // just consumed a delimiter
                    if (b === 0xA5)      { this._state = 2; this._frame.length = 0; }
                    else if (b !== 0x00) {
                        this._state = 0;
                        if (b === 0x0A)      { this._flushText(); }
                        else if (b !== 0x0D) { this._text.push(b); }
                    }
                    break;
                case 2:   // inside an envelope
                    if (b === 0x00) { this._envelopeDone(); this._state = 1; }
                    else            { this._frame.push(b); }
                    break;
            }
        }
    }

    _flushText() {
        if (!this._text.length) return;
        const line = new TextDecoder().decode(Uint8Array.from(this._text));
        this._text.length = 0;
        if (this.onlog && line.trim().length) this.onlog(line);
    }

    _envelopeDone() {
        const decoded = _cobsDecode(Uint8Array.from(this._frame));
        this._frame.length = 0;
        if (!decoded || decoded.length < 1) return;
        const msg = decoded.subarray(0, decoded.length - 1);
        if (_crc8(msg) !== decoded[decoded.length - 1]) return;   // corrupted — drop, stay synced
        this._sawReply = true;
        this._stopProbe();   // the board is talking — stop knocking
        if (this.onmessage && msg.length)
            this.onmessage({ data: msg.slice().buffer });
    }

    _stopProbe() {
        if (this._probeTimer)   { clearInterval(this._probeTimer); this._probeTimer = null; }
        if (this._noReplyTimer) { clearTimeout(this._noReplyTimer); this._noReplyTimer = null; }
    }

    // Restart probing on the SAME open port (no reopen — reopening risks another
    // DTR reset). Used when the board announced a reboot (CMD_REBOOT): resume
    // takeover-probing so a probe lands in the board's boot-watch window and it
    // switches straight back to serial.
    resumeProbe() {
        if (this._closed || this._probeTimer) return;   // gone, or already probing
        this._sawReply = false;
        this._probeTimer = setInterval(() => this._probe(), 500);
        this._probe();
    }

    send(buf) {
        if (!this._writer || this._closed) return;
        this._writer.write(_serialEnvelope(buf)).catch(() => {});
    }

    close() {
        if (this._closed) return;
        this._closed = true;
        this._stopProbe();
        const reader = this._reader, writer = this._writer, port = this.port;
        this._writer = null;
        // Release both locks, then close the port. Stored on the port so
        // the NEXT link (auto-reconnect) can await it before reopening.
        port._pardaloteClosing = (async () => {
            try { if (reader) await reader.cancel().catch(() => {}); } catch (_) {}
            try { if (this._readPromise) await this._readPromise; } catch (_) {}   // read lock released
            try { if (writer) { writer.releaseLock(); } } catch (_) {}
            try { await port.close(); } catch (_) {}
        })();
    }

    _teardown() {
        this._stopProbe();
        try { if (this._writer) this._writer.releaseLock(); } catch (_) {}
        this._writer = null;
        // Best-effort close so a later auto-reconnect can reopen the port.
        try { this.port._pardaloteClosing = this.port.close().catch(() => {}); } catch (_) {}
    }
}

// -------------------------------------------------------------------
// Extension base class
//
// All JS extensions inherit from this. It provides:
//   - on(event, fn) / off(event, fn) — subscribe to extension events
//   - _emit(event, data)             — fire callbacks from handleMessage
//   - _reRegister()                  — override to restore state on reconnect
//   - handleMessage(frame)           — override to handle incoming frames
// -------------------------------------------------------------------
// Registry of extension classes by deviceId — each extension file calls
// registerExtensionType(<Class>) at its bottom. The core uses this to
// materialise browser objects for hardware the SKETCH created (the board
// announces them with CMD_SHARE; see Arduino._onShare).
const _extensionTypes = new Map();
function registerExtensionType(cls) { _extensionTypes.set(cls.deviceId, cls); }

class Extension {
    constructor() {
        this.arduino   = null;   // injected by arduino.add()
        this.logicalId = null;
        this._name     = null;   // binding name (arduino.<name>) — set by add()/share
        this._cbs      = {};

        // True for instances the BOARD created (sketch-side attach, announced
        // via CMD_SHARE). The board owns their lifecycle: the browser never
        // replays their state on reconnect, and they're dropped when
        // connect() switches to a different board.
        this._sharedFromBoard = false;
    }

    on(event, fn)  { (this._cbs[event] ||= []).push(fn); return this; }

    off(event, fn) {
        if (this._cbs[event])
            this._cbs[event] = this._cbs[event].filter(f => f !== fn);
        return this;
    }

    // One-shot listener — fires once, then removes itself.
    once(event, fn) {
        const wrap = (data) => { this.off(event, wrap); fn(data); };
        return this.on(event, wrap);
    }

    _emit(event, data) { (this._cbs[event] || []).forEach(fn => fn(data)); }

    // "Servo 'pan'" / "Ultrasonic 2" — who is speaking, for warn/error events.
    _label() {
        const cls = this.constructor.name;
        return this._name != null ? `${cls} '${this._name}'` : `${cls} ${this.logicalId ?? '?'}`;
    }

    // Report a problem with this device. Warnings route to the core's
    // 'warn' channel (arduino.on('warn', …); console fallback when nobody
    // listens). Errors additionally fire 'error' on THIS instance, so
    // device-level code can react — an instance listener also counts as
    // "handled" and suppresses the console fallback.
    _warn(message) {
        if (this.arduino) this.arduino._notify('warn', this._label(), message);
        else console.warn(`${this._label()}: ${message}`);
        return this;
    }

    _error(message) {
        const local = (this._cbs['error'] || []).length > 0;
        if (local) this._emit('error', { message });
        if (this.arduino) this.arduino._notify('error', this._label(), message, local);
        else if (!local) console.error(`${this._label()}: ${message}`);
        return this;
    }

    _reRegister()       {}
    handleMessage(frame) {}

    // Wipe board-specific state when the user calls arduino.connect() to
    // switch sessions. Preserve user-tuned configuration. Default is a no-op;
    // extensions override as needed.
    _reset() {}
}

// -------------------------------------------------------------------
// Pin — a listening handle for one pin, created via arduino.pin(ref).
//
// Speaks the same grammar as the device extensions:
//   pin.on('change', ({ value, pin }) => …)   input readings past the
//                                             threshold AND output writes
//                                             from any client or the sketch
//   pin.off('change', fn)                     unsubscribe (fn omitted: all)
//   pin.setReadInterval(ms) / setReadThreshold(t)
//   pin.value                                 the mirrored value
//   pin.read()/.write()/.mode()               conveniences over the verbs
//
// `ref` may be a number or an alias string. Alias handles resolve
// LAZILY: pin('A0') created before connect() holds the name and starts
// working when the board's alias table arrives with HELLO — no more
// "call it inside on('ready')" footgun for listeners. Handles persist
// across connect() to a new board (listeners survive, like extensions);
// their polls are re-established on the new board's sync.
// -------------------------------------------------------------------
class Pin {
    constructor(arduino, ref) {
        this.arduino  = arduino;
        this._ref     = ref;
        this._cbs     = {};
        this._pending = null;   // deferred intents while the alias can't resolve
    }

    // Resolved pin number, or null while an alias awaits the board's table.
    get number() {
        try { return this.arduino._resolvePin(this._ref); }
        catch (_) { return null; }
    }

    // Mirrored value: last polled reading, else last known output state, else 0.
    get value() {
        const n = this.number;
        if (n === null) return 0;
        const read = this.arduino._reads.get(n);
        if (read && read.value !== null) return read.value;
        return this.arduino._pinValues.get(n) ?? 0;
    }

    on(event, fn) {
        (this._cbs[event] ||= []).push(fn);
        if (event === 'change') this._ensurePoll();
        return this;
    }

    off(event, fn) {
        const list = this._cbs[event];
        if (!list) return this;
        if (fn) { const i = list.indexOf(fn); if (i >= 0) list.splice(i, 1); }
        else    delete this._cbs[event];
        return this;
    }

    // One-shot listener — fires once, then removes itself.
    once(event, fn) {
        const wrap = (data) => { this.off(event, wrap); fn(data); };
        return this.on(event, wrap);
    }

    _emit(event, data) { (this._cbs[event] || []).forEach(fn => fn(data)); }

    // 'change' on an input pin needs a poll running; outputs get their
    // changes from write broadcasts, and pins something else is already
    // polling (this page, another browser, or the sketch) need nothing.
    // Unresolved or pre-sync handles do nothing here — _onSyncComplete
    // re-runs this for every handle with listeners once the board's alias
    // table AND pin modes are known, so the right read kind is chosen.
    _ensurePoll() {
        const n = this.number;
        if (n === null) return;
        const mode = this.arduino._pinModes.get(n);
        if (mode === OUTPUT) return;
        if (this.arduino._reads.has(n)) return;
        if (mode === ANALOG_INPUT_MODE) this.arduino.analogRead(n);
        else                            this.arduino.digitalRead(n);
    }

    // Per-pin poll config — delegates to the core (which re-registers a
    // live poll immediately); deferred if the alias can't resolve yet.
    setReadInterval(ms) {
        const n = this.number;
        if (n === null) (this._pending ||= {}).interval = ms;
        else this.arduino.setReadInterval(n, ms);
        return this;
    }

    setReadThreshold(t) {
        const n = this.number;
        if (n === null) (this._pending ||= {}).threshold = t;
        else this.arduino.setReadThreshold(n, t);
        return this;
    }

    // Conveniences over the Arduino-mirroring verbs (which remain the
    // documented way to DO things — see pinMode/digitalWrite/…Read).
    mode(m, interval, threshold) { this.arduino.pinMode(this._ref, m, interval, threshold); return this; }
    write(v)                     { this.arduino.digitalWrite(this._ref, v); return this; }
    read(interval, threshold) {
        const n = this.number;
        const mode = n !== null ? this.arduino._pinModes.get(n) : undefined;
        return (mode === ANALOG_INPUT_MODE)
            ? this.arduino.analogRead(this._ref, interval, threshold)
            : this.arduino.digitalRead(this._ref, interval, threshold);
    }

    // Alias table just arrived (HELLO) — flush config deferred while the
    // name couldn't resolve. Still unresolvable = wrong board for this
    // alias; report it on the warn channel and keep waiting.
    // (Deferred poll needs are handled in _onSyncComplete instead, once
    // pin modes are known too.)
    _aliasesReady() {
        if (!this._pending) return;
        if (this.number === null) {
            this.arduino._warn(`unknown pin alias "${this._ref}" for board "${this.arduino.board}"`);
            return;
        }
        const p = this._pending;
        this._pending = null;
        if (p.interval  !== undefined) this.setReadInterval(p.interval);
        if (p.threshold !== undefined) this.setReadThreshold(p.threshold);
    }
}

// -------------------------------------------------------------------
// Arduino class — core connection and protocol
// -------------------------------------------------------------------
class Arduino {
    static version = PARDALOTE_VERSION;

    constructor() {
        this.socket    = null;
        this.connected = false;  // true after HELLO received
        this.deviceIP  = null;

        // Transport: 'ws' (WebSocket, the default) or 'serial' (Web Serial —
        // see connectSerial()). The socket slot holds a WebSocket or a
        // _SerialLink; both expose the same handler surface.
        this._transportKind = 'ws';
        this._serialPort    = null;   // granted Web Serial port, kept for reconnects
        this._serialTakeover = false; // gesture authorised a WiFi→USB switch (one-shot)

        // Connection key — sent as the first frame after a WS socket opens, or
        // in the serial probe loop; see connect(ip, { key }) / connectSerial({ key }).
        this._key = null;

        // Reconnection state
        // Reconnects continue indefinitely (backoff capped at _maxReconnectDelay).
        // disconnect() sets _reconnectDisabled; connect() clears it.
        this._reconnectAttempts = 0;
        this._reconnectDelay    = 1000;    // base delay before first retry
        this._maxReconnectDelay = 30000;   // cap on per-attempt delay
        this._reconnectTimeout  = null;
        this._isReconnecting    = false;
        this._reconnectDisabled = false;

        // Outgoing message queue (ArrayBuffers)
        this._queue    = [];
        this._flushing = false;

        // Active periodic reads:
        // Map<pin, { cmd, interval, threshold, value, origin, passive }>
        // threshold 0 = board default (1 for digital, the ADC noise floor —
        // analogMax >> 8 — for analog). passive = the BOARD polls this pin
        // itself (sketch share() with an interval): we sent no registration
        // and replay none on reconnect.
        this._reads = new Map();

        // Per-pin read config set via setReadInterval()/setReadThreshold(),
        // before or after polling starts: Map<pin, { interval?, threshold? }>.
        // Consulted by digitalRead/analogRead when the args are omitted.
        this._readConfig = new Map();

        // Core pin state — tracked so _onSyncComplete can restore it after Arduino reset,
        // and updated from announce frames so multi-client sync stays correct.
        this._pinModes  = new Map();   // Map<pin, mode>  — set by pinMode() and incoming announce
        this._pinValues = new Map();   // Map<pin, value> — set by digitalWrite() and incoming announce

        // Provenance: who created each pin entry — 'browser' (this page called
        // pinMode/digitalWrite/…Read) or 'board' (the sketch share()d it and we
        // learned of it from an inbound frame). Each side is source of truth
        // for its own creations: on reconnect the browser replays only
        // browser-originated state; board-originated state is refreshed by the
        // board's own announce — and swept if the announce no longer mentions
        // it (new firmware). 'browser' is sticky: once this page expresses
        // intent about a pin, its state is replayed. _reads entries carry
        // their own read.origin (a browser can poll a board-shared pin).
        this._pinOrigins = new Map();  // Map<pin, 'browser'|'board'>
        this._pollOrigin = null;       // set by _maybeStartPollFor while it runs
        this._staleBoardPins = null;   // Set<pin> — board-origin pins awaiting re-announce

        // Board boot id from HELLO (0 = unknown / old firmware). A changed id
        // across a reconnect means the board rebooted — possibly with new
        // firmware — so board-created state (shared pins, sketch-created
        // extensions, retained messages) is dropped before the announce
        // repopulates whatever actually exists now.
        this._bootId = 0;

        // Board identity, alias table, and ADC range — populated from the HELLO handshake
        this.board    = 'unknown';
        this._aliases  = {};
        this.analogMax = 1023;   // safe default; overwritten by HELLO

        // Heartbeat — liveness is judged by the AGE OF THE LAST PONG.
        // A power-cycled board sends no FIN, and send() into a half-open
        // TCP connection doesn't throw (it just buffers), so without this
        // check the browser would sit "connected" until the rebooted
        // board's new TCP stack resets the stale connection.
        this._pingInterval  = null;
        this._lastPong      = 0;
        this._pingMs        = 3000;   // send a ping every 3 s
        this._pongTimeoutMs = 5000;   // declare the link dead if no pong for 5 s

        // Pin handles (see arduino.pin()): Map<number|aliasString, Pin>.
        // Permanent, like extension instances — listeners survive connect().
        this._pinHandles = new Map();

        // True after CMD_SYNC_COMPLETE; false during the announce phase.
        // Guards against write callbacks firing on announce state-sync frames.
        this._synced   = false;

        // Extensions: keyed by name and by deviceId
        this._extensions  = {};
        this._extByDevice = new Map();
        this._available   = new Set();  // deviceIds announced by Arduino
        this._nextId      = 0;

        // Actuator groups, keyed by name (see group())
        this._groups      = {};

        // Message channel: last received value per key, plus per-key watchers.
        // (Watchers are user subscriptions and survive connect(), like on(…);
        // the cached values are board state and are cleared in connect().)
        this.messages  = {};
        this._watchers = new Map();   // key → fn[]

        // Connection-level callbacks
        this._cbs = {};

        this.defaultInterval  = 200;   // min ms between updates (rate limit)
        this.defaultThreshold = 0;     // 0 = board default: 1 for digital,
                                       // the ADC noise floor for analog

        // PWM write throttle — the OUTBOUND counterpart to the read rate
        // limit above. analogWrite() driven from a slider or draw loop can
        // fire dozens of times a second; an unthrottled flood overruns a
        // slow board's inbound buffer (the UNO R4 WiFi's WiFiS3 link can't
        // drain it), so the queue grows, latency climbs, and the socket
        // eventually drops. This caps the send rate per pin: the first
        // write in a burst goes out immediately, further writes inside the
        // window are coalesced into one trailing send carrying the LATEST
        // value, so the resting position is never lost. Mirrors the servo /
        // neopixel throttle. 0 = off (send every value). ESP32 is fast
        // enough that the default is imperceptible; the UNO R4 needs it.
        this.writeThrottle  = 20;      // min ms between PWM sends per pin
        this.writeThreshold = 0;       // min value change worth sending (0 = all)
        this._pwmLastWrite  = new Map(); // Map<pin, ms>      — last send time
        this._pwmLastSent   = new Map(); // Map<pin, value>   — last value sent
        this._pwmPending     = new Map(); // Map<pin, timeoutId> — coalesced trailing send
    }

    // -------------------------------------------------------------------
    // Connection
    //
    //   connect(ip)                    — WebSocket, port 81
    //   connect(ip, 8080)              — WebSocket, custom port
    //   connect(ip, { key: 'k' })      — WebSocket + connection key: sent as
    //                                    the first frame; a board started with
    //                                    Pardalote.begin("k") refuses clients
    //                                    whose key doesn't match ('authFail').
    //   connectSerial(opts?)           — USB serial via Web Serial (Chrome/
    //                                    Edge). Call from a user gesture (a
    //                                    click); the browser shows a port
    //                                    picker. A previously granted port is
    //                                    reused without a picker; pass PROMPT
    //                                    ({ prompt: true }) to force one.
    //                                    A connect from a real user gesture (a
    //                                    click) authorises pulling a board off
    //                                    WiFi onto USB — even one that silently
    //                                    reuses a granted port. An automatic
    //                                    connect (page load, background tab) has
    //                                    no gesture, so a WiFi board answers
    //                                    'usbBusy' instead of switching.
    //                                    opts.key sets a board-identity key
    //                                    (see requireKey() on the board): a
    //                                    wrong key is refused with 'authFail'.
    // -------------------------------------------------------------------
    connect(ip, portOrOpts = 81) {
        const opts = (typeof portOrOpts === 'object' && portOrOpts !== null)
                   ? portOrOpts : { port: portOrOpts };
        this._transportKind = 'ws';
        this._key      = opts.key || null;
        this._serialTakeover = false;      // switching to WiFi ends any serial takeover authority
        this.deviceIP  = `ws://${ip}:${opts.port ?? 81}/`;
        this._reconnectAttempts = 0;
        this._reconnectDisabled = false;   // re-enable after an earlier disconnect()

        this._resetSession();

        // Cleanly detach and close the old socket so its events
        // cannot fire into the new session.
        this._closeSocket();

        this._connectSocket();
    }

    async connectSerial(opts = {}) {
        if (typeof navigator === 'undefined' || !('serial' in navigator)) {
            this._error('Web Serial is not supported in this browser — use Chrome or Edge, or connect over WiFi');
            return this;
        }
        // Takeover authority = the user deliberately asked for this connection,
        // i.e. there is transient user activation (a real click) as connectSerial
        // runs. That gesture is the consent to pull a WiFi board over to USB.
        // We capture it BEFORE any await (an await can expire the activation).
        // NB: it is NOT "did the picker appear" — a click that silently reuses an
        // already-granted port is still a genuine gesture and must authorise the
        // switch. A page-load / background auto-connect has no activation, so it
        // can reconnect a board already on serial but a WiFi-listening board will
        // refuse it (CMD_SERIAL_BUSY → 'usbBusy') rather than switch silently.
        const gesture = (navigator.userActivation)
                      ? navigator.userActivation.isActive
                      : false;
        let port = opts.port || null;
        let usedPicker = false;
        if (!port && !opts.prompt) {
            // Reuse a previously granted port (works without a user gesture,
            // so a returning visit can auto-connect a still-serial board).
            const granted = await navigator.serial.getPorts();
            if (granted.length === 1) port = granted[0];
        }
        if (!port) {
            try {
                port = await navigator.serial.requestPort();
                usedPicker = true;
            } catch (_) {
                this._error('no serial port selected');
                return this;
            }
        }

        this._transportKind = 'serial';
        this._serialPort = port;
        // A picker always implies a gesture; a reused port needs the activation
        // check above. Either way, a deliberate connect authorises the switch.
        this._serialTakeover = usedPicker || gesture;
        this._key      = opts.key || null;   // board-identity key (optional, both transports)
        this.deviceIP  = 'serial';
        this._reconnectAttempts = 0;
        this._reconnectDisabled = false;

        this._resetSession();
        this._closeSocket();
        this._connectSocket();
        return this;
    }

    // Fresh session — drop any pin-keyed state from a previous board.
    // Pin numbers (and the extensions Arduino announced) are board-specific,
    // so replaying them on a new device would target the wrong hardware.
    // Auto-reconnect goes through _connectSocket() directly and is unaffected.
    _resetSession() {
        this._pinModes.clear();
        this._pinValues.clear();
        this._pinOrigins.clear();
        this._staleBoardPins = null;
        this._bootId = 0;
        this._reads.clear();
        this._available.clear();
        this.messages = {};                                     // cached message values are board state
        this._queue = [];                                       // drop frames queued for the old board
        this._pwmCancelPending();                               // drop any coalesced PWM send aimed at the old board

        // Board-created (shared) objects belong to the previous board —
        // remove them entirely. The new board announces its own via
        // CMD_SHARE. Browser-created extensions persist and _reset().
        this._dropBoardCreated();

        Object.values(this._extensions).forEach(ext => ext._reset());

        // Cancel any pending auto-reconnect timer
        if (this._reconnectTimeout) {
            clearTimeout(this._reconnectTimeout);
            this._reconnectTimeout = null;
        }
        this._isReconnecting = false;
    }

    // Remove everything the BOARD created: sketch-created (shared)
    // extensions, and pin state that originated from a sketch share().
    // Called from connect() (switching boards) and from _onHello when the
    // boot id changed (same IP, but the board rebooted — possibly with new
    // firmware, so its old shares may no longer exist). Whatever the new
    // board-run really has comes back via the announce that follows HELLO.
    // Browser-created state is untouched.
    _dropBoardCreated() {
        for (const [name, ext] of Object.entries(this._extensions)) {
            if (!ext._sharedFromBoard) continue;
            ext._reset();
            delete this._extensions[name];
            if (this[name] === ext) delete this[name];
            const list = this._extByDevice.get(ext.constructor.deviceId);
            if (list) {
                const i = list.indexOf(ext);
                if (i >= 0) list.splice(i, 1);
            }
        }

        // Board-originated pin state (sketch share()d pins and their
        // auto-polls). Reads keep their own origin — a poll the browser
        // explicitly asked for on a board-shared pin survives.
        for (const [pin, origin] of [...this._pinOrigins]) {
            if (origin !== 'board') continue;
            this._pinOrigins.delete(pin);
            this._pinModes.delete(pin);
            this._pinValues.delete(pin);
            const read = this._reads.get(pin);
            if (read && read.origin !== 'browser') this._reads.delete(pin);
        }
    }

    _closeSocket() {
        // Stop the current heartbeat FIRST. We null the socket's handlers below
        // (so a late close can't double-fire 'disconnect'), which also means the
        // onclose that normally calls _stopHeartbeat() won't fire — leaving the
        // old transport's heartbeat ticking into the next connection. On a
        // WiFi→USB switch that stale heartbeat fires "no pong" during the board's
        // reboot window and tears down the in-flight serial link (→ reconnect
        // churn). Stopping it here makes a switch clean.
        this._stopHeartbeat();
        if (!this.socket) return;
        const s = this.socket;
        this.socket    = null;
        this.connected = false;
        s.onopen    = null;
        s.onclose   = null;
        s.onerror   = null;
        s.onmessage = null;
        s.onlog     = null;   // _SerialLink only; harmless on a WebSocket
        try { s.close(); } catch (_) {}
    }

    _connectSocket() {
        if (this._isReconnecting) return;
        console.log(`Connecting to ${this.deviceIP}`);

        if (this._transportKind === 'serial') {
            this._connectSerialLink();
            return;
        }

        try {
            const socket = new WebSocket(this.deviceIP);
            this.socket = socket;
            socket.binaryType = 'arraybuffer';

            socket.onopen = () => {
                if (this.socket !== socket) return;   // stale — a newer socket took over
                this._isReconnecting = false;
                this._reconnectDelay = 1000;
                if (this._reconnectTimeout) {
                    clearTimeout(this._reconnectTimeout);
                    this._reconnectTimeout = null;
                }
                // A connection key goes out FIRST — before it checks out, the
                // board sends nothing and drops everything else we say.
                if (this._key)
                    socket.send(encodeFrame(CMD_AUTH, 0, [], this._key));
                console.log('WebSocket open — waiting for HELLO');
                this._emit('connect');
            };

            socket.onclose = (e) => {
                if (this.socket !== socket) return;   // stale — ignore
                this.connected = false;
                this._stopHeartbeat();
                console.log(`WebSocket closed (${e.code})`);
                this._emit('disconnect');
                this._scheduleReconnect();
            };

            socket.onerror = () => {
                if (this.socket !== socket) return;
                this.connected = false;
                this._stopHeartbeat();
            };

            socket.onmessage = (evt) => {
                if (this.socket !== socket) return;
                this._receive(evt.data);
            };

        } catch (e) {
            this._error(`WebSocket error: ${e.message || e}`);
            this._scheduleReconnect();
        }
    }

    // Serial counterpart of the WebSocket branch above — the link mimics
    // the WebSocket handler surface, so everything downstream (HELLO,
    // heartbeat, flush, reconnect backoff) is shared.
    _connectSerialLink() {
        // Takeover authority persists for the whole gesture-initiated session —
        // across auto-reconnects — so a board that reboots (e.g. an ESP32 DTR
        // reset, or a hardware reset while USB-connected) can be switched back to
        // serial without a fresh click. It's set ONLY by a real user gesture
        // (see connectSerial) and cleared on disconnect()/connect(), so a fresh
        // page load or a background tab still starts with no authority — a
        // silent auto-connect can't recapture a WiFi board.
        const takeover = this._serialTakeover;
        const link = new _SerialLink(this._serialPort, { takeover, key: this._key });
        this.socket = link;

        link.onopen = () => {
            if (this.socket !== link) return;   // stale — a newer link took over
            this._isReconnecting = false;
            this._reconnectDelay = 1000;
            if (this._reconnectTimeout) {
                clearTimeout(this._reconnectTimeout);
                this._reconnectTimeout = null;
            }
            console.log('Serial port open — probing for the board');
            this._emit('connect');
        };

        link.onclose = () => {
            if (this.socket !== link) return;
            this.connected = false;
            this._stopHeartbeat();
            console.log('Serial port closed');
            this._emit('disconnect');
            this._scheduleReconnect();
        };

        link.onmessage = (evt) => {
            if (this.socket !== link) return;
            this._receive(evt.data);
        };

        // The sketch's Serial.print output, line by line. With no listener
        // it goes to the console — students see their debug prints in the
        // browser without opening the IDE.
        link.onlog = (line) => {
            if ((this._cbs['log'] || []).length) this._emit('log', line);
            else console.log(`[board] ${line}`);
        };

        link.open().catch(async (e) => {
            if (this.socket !== link) return;
            // The port may have been unplugged and re-granted as a fresh
            // SerialPort object — re-acquire before the next attempt.
            try {
                const granted = await navigator.serial.getPorts();
                if (granted.length === 1) this._serialPort = granted[0];
            } catch (_) {}
            this._error(`serial open failed: ${e.message || e}`);
            this._scheduleReconnect();
        });
    }

    _scheduleReconnect() {
        if (this._isReconnecting || this._reconnectDisabled) return;
        this._isReconnecting = true;
        this._reconnectAttempts++;
        const delay = Math.round(Math.min(
            this._reconnectDelay * Math.pow(1.5, this._reconnectAttempts - 1),
            this._maxReconnectDelay
        ));
        // Log the first few attempts in full; after that go quiet so a long
        // outage doesn't flood the console. User code can subscribe to the
        // 'reconnecting' event for per-attempt updates.
        if (this._reconnectAttempts <= 10) {
            console.log(`Reconnecting in ${delay}ms (attempt ${this._reconnectAttempts})`);
        } else if (this._reconnectAttempts === 11) {
            console.log(`Reconnecting silently — subscribe to 'reconnecting' for per-attempt updates`);
        }
        this._emit('reconnecting', { attempt: this._reconnectAttempts, delay });
        this._reconnectTimeout = setTimeout(() => {
            this._isReconnecting = false;
            this._connectSocket();
        }, delay);
    }

    disconnect() {
        this._reconnectDisabled = true;   // suppress auto-reconnect until connect() is called again
        this._serialTakeover = false;     // a manual disconnect ends the gesture's takeover authority
        if (this._reconnectTimeout) {
            clearTimeout(this._reconnectTimeout);
            this._reconnectTimeout = null;
        }
        this._isReconnecting = false;
        this._closeSocket();
    }

    // -------------------------------------------------------------------
    // Connection-level events: 'connect', 'disconnect', 'ready', 'announce',
    // 'warn', 'error' (see _notify), plus 'reconnecting', 'reboot', 'share',
    // 'message', 'change', 'frame', 'authFail' (board refused this client's
    // key — auto-reconnect stops), 'usbBusy' (serial only: the board is on
    // WiFi and needs a picker gesture to switch to USB — auto-reconnect stops),
    // and 'log' (serial transport only: the sketch's Serial.print output,
    // one line per event).
    // -------------------------------------------------------------------
    on(event, fn)  { (this._cbs[event] ||= []).push(fn); return this; }
    off(event, fn) {
        const list = this._cbs[event];
        if (!list) return this;
        if (fn) { const i = list.indexOf(fn); if (i >= 0) list.splice(i, 1); }
        else    delete this._cbs[event];
        return this;
    }

    // One-shot listener — fires once, then removes itself.
    once(event, fn) {
        const wrap = (data) => { this.off(event, wrap); fn(data); };
        return this.on(event, wrap);
    }

    _emit(event, data) { (this._cbs[event] || []).forEach(fn => fn(data)); }

    // -------------------------------------------------------------------
    // Problem reporting — the 'warn' and 'error' events.
    //
    //   arduino.on('warn',  ({ source, message }) => showBanner(message));
    //   arduino.on('error', ({ source, message }) => showBanner(message));
    //
    // Every warning/error in the library funnels through here (extensions
    // route via Extension._warn/_error with their device as `source`), so
    // a page can surface problems in its UI instead of the console. When
    // NO listener is registered the message falls back to console.warn /
    // console.error — pages that never subscribe behave exactly as before.
    // `handledLocally` suppresses that fallback when an instance-level
    // 'error' listener already received the message.
    // -------------------------------------------------------------------
    _notify(level, source, message, handledLocally = false) {
        const listeners = this._cbs[level];
        if (listeners && listeners.length) {
            this._emit(level, { source, message });
        } else if (!handledLocally) {
            (level === 'error' ? console.error : console.warn)(
                source ? `${source}: ${message}` : message);
        }
        return this;
    }

    _warn(message, source = 'Pardalote')  { return this._notify('warn',  source, message); }
    _error(message, source = 'Pardalote') { return this._notify('error', source, message); }

    // -------------------------------------------------------------------
    // Sending
    // -------------------------------------------------------------------
    // send() has two forms:
    //   send(key, value, opts?) — a message (string key). See the message channel.
    //   send(frameOrArray)      — internal transport of encoded frame(s).
    // A string first arg is never a valid frame, so the two never collide.
    send(frameOrArray, value, opts) {
        if (typeof frameOrArray === 'string') {
            if (new TextEncoder().encode(frameOrArray).length > MAX_MESSAGE_KEY)
                this._warn(`message key "${frameOrArray}" exceeds ${MAX_MESSAGE_KEY} bytes — truncated`);
            this._queueFrame(encodeMessage(frameOrArray, value, opts || {}));
            return this;
        }
        const frames = Array.isArray(frameOrArray) ? frameOrArray : [frameOrArray];
        this._queue.push(...frames);
        if (this.connected && !this._flushing) this._flush();
    }

    _queueFrame(buf) {
        this._queue.push(buf);
        if (this.connected && !this._flushing) this._flush();
    }

    _flush() {
        if (!this.connected || this._flushing || this._queue.length === 0) return;
        this._flushing = true;
        try {
            const frames = this._queue.splice(0);
            if (this._cbs['frame'] && this._cbs['frame'].length) {
                for (const f of frames) {
                    const decoded = decodeFrame(f, 0);
                    if (decoded) this._emitFrame('out', decoded);
                }
            }
            this.socket.send(encodeBatch(frames));
        } catch (e) {
            this._error(`send failed: ${e.message || e}`);
        } finally {
            this._flushing = false;
        }
    }

    // -------------------------------------------------------------------
    // Message channel — user-defined key/value messages.
    //
    //   arduino.send('temp', 22.5);                    // infer type
    //   arduino.send('mode', 'idle', { retain: true, broadcast: true });
    //   arduino.watch('temp', (value, key, type) => …);
    //   arduino.on('message', ({ key, value, type }) => …);
    //   arduino.messages['mode'];                        // last received value
    // -------------------------------------------------------------------
    watch(key, fn) {
        if (!this._watchers.has(key)) this._watchers.set(key, []);
        this._watchers.get(key).push(fn);
        return this;
    }

    unwatch(key, fn) {
        const list = this._watchers.get(key);
        if (!list) return this;
        if (fn) { const i = list.indexOf(fn); if (i >= 0) list.splice(i, 1); }
        else    this._watchers.delete(key);
        return this;
    }

    // Frame monitor — fires for every frame in and out (decoded). Alias for
    // on('frame', fn); costs nothing until a listener is registered.
    monitor(fn) { return this.on('frame', fn); }

    _onMessage(frame) {
        const msg = decodeMessage(frame);
        if (!msg) return;
        this.messages[msg.key] = msg.value;
        const list = this._watchers.get(msg.key);
        if (list) list.forEach(fn => fn(msg.value, msg.key, msg.type));
        this._emit('message', msg);
    }

    _emitFrame(dir, frame) {
        const listeners = this._cbs['frame'];
        if (!listeners || !listeners.length) return;
        listeners.forEach(fn => fn({
            dir,
            cmd:     frame.cmd,
            cmdName: frameName(frame.target, frame.cmd),
            target:  frame.target,
            params:  frame.params,
            payload: frame.payload ? new Uint8Array(frame.payload) : null,
        }));
    }

    // -------------------------------------------------------------------
    // Receiving
    // -------------------------------------------------------------------
    _receive(buf) {
        let pos = 0;
        while (pos < buf.byteLength) {
            const frame = decodeFrame(buf, pos);
            if (!frame) break;
            this._dispatch(frame);
            pos += frame.totalLen;
        }
    }

    _dispatch(frame) {
        // Frame monitor — sees every inbound frame (guarded: no-op unless a
        // listener is registered).
        this._emitFrame('in', frame);

        // These are checked first — they carry no pin/device context.
        if (frame.cmd === CMD_HELLO)    { this._onHello(frame);    return; }
        if (frame.cmd === CMD_ANNOUNCE) { this._onAnnounce(frame); return; }
        if (frame.cmd === CMD_PONG)     { this._onPong();          return; }
        if (frame.cmd === CMD_AUTH)     { this._onAuthFail(frame); return; }
        if (frame.cmd === CMD_SERIAL_BUSY) { this._onUsbBusy();    return; }
        if (frame.cmd === CMD_REBOOT)   { this._onReboot();        return; }

        // Message channel — routed by cmd (the flags in the target high byte
        // can push it past RESERVED_START, so the range check would misroute).
        if (frame.cmd === CMD_MESSAGE)  { this._onMessage(frame);  return; }

        // Extension frames — routed by device ID.
        if (frame.target >= RESERVED_START) {
            this._routeExtension(frame);
            return;
        }

        // Core frames (target < RESERVED_START = pin number or 0).
        const pin = frame.target;

        // Sync-complete signal — all announce frames have arrived; fire 'ready'.
        if (frame.cmd === CMD_SYNC_COMPLETE) { this._onSyncComplete(); return; }

        // Incoming pin-state frames — from Arduino announce on connect, or
        // from Arduino sketches calling Pardalote.share(pin, mode). For input
        // modes we auto-start a default-interval poll so the browser starts
        // receiving values without a separate digitalRead/analogRead call.
        if (frame.cmd === CMD_PIN_MODE) {
            const mode = frame.params[0];
            this._pinModes.set(pin, mode);
            // Provenance: an inbound mode is board-originated — unless this
            // page already claimed the pin ('browser' is sticky; the announce
            // echoes back modes we set ourselves).
            if (!this._pinOrigins.has(pin)) this._pinOrigins.set(pin, 'board');
            this._staleBoardPins?.delete(pin);   // re-announced — not stale

            // [mode, interval, threshold]: the BOARD polls
            // this pin itself (sketch share() with an interval). Register a
            // passive entry — values arrive without us sending a READ, and
            // we replay nothing on reconnect (the board's poll outlives us).
            const boardInterval = frame.params.length > 1 ? frame.params[1] : 0;
            if (boardInterval > 0) {
                const cmd = (mode === ANALOG_INPUT_MODE) ? CMD_ANALOG_READ : CMD_DIGITAL_READ;
                const existing = this._reads.get(pin);
                if (!existing || existing.origin !== 'browser') {
                    this._reads.set(pin, {
                        cmd, interval: boardInterval,
                        threshold: frame.params[2] ?? 0,
                        value:     existing?.value ?? null,
                        origin: 'board', passive: true,
                    });
                }
            } else {
                this._maybeStartPollFor(pin, mode, undefined, 'board');
            }
            return;
        }
        if (frame.cmd === CMD_DIGITAL_WRITE) {
            this._pinValues.set(pin, frame.params[0]);
            // Post-announce: fire change events so all browsers stay in sync
            // (announce-phase state sync stays silent).
            if (this._synced) this._emitPinChange(pin, frame.params[0]);
            return;
        }

        // Core read response (CMD_DIGITAL_READ or CMD_ANALOG_READ).
        const value = frame.params[0];
        const read  = this._reads.get(pin);

        if (read) {
            const prev = read.value;
            read.value = value;
            // Announce-phase values (board seeding a new/reconnected client)
            // update the mirror silently — same rule as write callbacks.
            // _forceCallback (set in _onSyncComplete) makes the first
            // post-sync reading fire even if the value didn't change, so
            // callbacks re-sync with actual state after a reconnect.
            if (prev === null || value !== prev || read._forceCallback) {
                if (this._synced) {
                    read._forceCallback = false;
                    this._emitPinChange(pin, value);
                }
            }
        } else {
            // A reading for a poll we never registered (another client asked
            // for it, or a board seed) — cache it, but mark it
            // board-originated so we never replay or retain a poll this
            // page didn't request.
            this._reads.set(pin, { cmd: frame.cmd, interval: 0, threshold: 0,
                                   value, origin: 'board', passive: false });
        }
    }

    // Each tick: first judge liveness by how stale the last pong is,
    // then send the next ping. Detection worst case is roughly
    // _pongTimeoutMs + _pingMs (~8 s) after the board dies.
    _startHeartbeat() {
        this._stopHeartbeat();
        this._lastPong = Date.now();   // HELLO just arrived — link demonstrably alive
        this._pingInterval = setInterval(() => {
            if (Date.now() - this._lastPong > this._pongTimeoutMs) {
                this._warn(`connection lost — no pong for ${this._pongTimeoutMs} ms; reconnecting`);
                this._stopHeartbeat();
                this._closeSocket();   // detach + null the socket so a late
                                       // close event can't double-fire 'disconnect'
                this._emit('disconnect');
                this._scheduleReconnect();
                return;
            }
            try { this.socket.send(encodeFrame(CMD_PING, 0, [])); } catch (_) {}
        }, this._pingMs);
    }

    _stopHeartbeat() {
        clearInterval(this._pingInterval);
        this._pingInterval = null;
    }

    _onPong() {
        this._lastPong = Date.now();
    }

    // The board announced (over serial) that it just (re)booted — e.g. a reset
    // while USB-connected. The port is still open, so rather than wait for the
    // heartbeat to time out (which would reopen the port and DTR-reset the board
    // again), we resume takeover-probing on the same link. The board is opening
    // its boot-watch window; our probe lands in it and it switches straight back
    // to serial. Give the link a fresh liveness window so the heartbeat doesn't
    // fire mid-recovery; the HELLO that follows the switch restarts everything.
    _onReboot() {
        if (this._transportKind !== 'serial') return;
        this._lastPong = Date.now();
        if (this.socket && typeof this.socket.resumeProbe === 'function') this.socket.resumeProbe();
    }

    // A WiFi-active board that we probed over USB without a picker gesture:
    // it won't switch off WiFi for a silent (getPorts) connect. Tell the user
    // to reconnect with a gesture, and stop probing (no churn) — one click on
    // Connect raises the picker and authorises the switch.
    _onUsbBusy() {
        const message = 'this board is on WiFi — click Connect (which raises the ' +
                        'port picker) to switch it to USB';
        this._emit('usbBusy', { message });
        this._error(message);
        this.disconnect();   // sets _reconnectDisabled until the next connect()
    }

    // The board refused this client: CMD_AUTH [reason] arrives just before
    // it closes the socket. Reconnecting would only be refused again, so
    // auto-reconnect stops — the student gets one clear error, not a
    // silent retry loop that looks like a dead board.
    _onAuthFail(frame) {
        const reason  = frame.params[0] ?? 0;
        const message = reason === 2
            ? 'connection refused — wrong key for this board'
            : 'connection refused — this board requires a key: connectSerial({ key: "…" }) or connect(ip, { key: "…" })';
        this._emit('authFail', { reason, message });
        this._error(message);
        this.disconnect();   // sets _reconnectDisabled until the next connect()
    }

    _onHello(frame) {
        const major   = frame.params[0];
        const minor   = frame.params[1];

        // Version handshake — a protocol MAJOR mismatch means the two
        // sides cannot talk. Report it and stop before misinterpreting
        // frames; a MINOR difference is backward-compatible by definition.
        if (major !== PROTOCOL_MAJOR_SUPPORTED) {
            this._error(`firmware speaks protocol v${major}.${minor}; this pardalote.js ` +
                        `speaks v${PROTOCOL_MAJOR_SUPPORTED}.x — update ` +
                        (major > PROTOCOL_MAJOR_SUPPORTED ? 'pardalote.js' : 'the firmware'));
            this.disconnect();
            return;
        }
        const adcBits = frame.params[2] ?? 10;   // default 10 for firmware that omits it
        const bootId  = frame.params[3] ?? 0;    // 0 = firmware predates boot ids
        this.board    = frame.payload ? new TextDecoder().decode(frame.payload) : 'unknown';
        this._aliases  = BOARD_ALIASES[this.board] || {};
        this.analogMax = (1 << adcBits) - 1;

        // Alias table is now known — pin handles created with alias strings
        // before connect can resolve and flush their deferred config/polls.
        this._pinHandles.forEach(h => h._aliasesReady());

        // Boot-id check: a changed id means the board REBOOTED since we last
        // spoke to it (new firmware upload, reset button, power cycle) — its
        // old shares/objects may not exist any more, so drop everything
        // board-created before the announce repopulates the real state.
        // Same id = pure network reconnect: keep everything.
        const rebooted = this._bootId !== 0 && bootId !== 0 && bootId !== this._bootId;
        if (rebooted) {
            console.log('Pardalote: board rebooted (boot id changed) — dropping board-created state');
            this._dropBoardCreated();
            this.messages = {};        // retained messages died with the old run
            this._available.clear();   // re-populated by the announce
        }
        this._bootId = bootId;

        // Announce sweep (also covers firmware without boot ids): any pin we
        // believe is board-originated must be re-announced before
        // SYNC_COMPLETE, or it belonged to a previous board-run and is swept
        // in _onSyncComplete. The inbound CMD_PIN_MODE handler removes pins
        // from this set as their announce arrives.
        this._staleBoardPins = new Set();
        this._pinOrigins.forEach((origin, pin) => {
            if (origin === 'board') this._staleBoardPins.add(pin);
        });

        this.connected          = true;
        this._synced            = false;  // re-entering announce phase
        this._reconnectAttempts = 0;  // genuine connection established
        this._startHeartbeat();
        console.log(`Pardalote: connected to ${this.board}, protocol v${major}.${minor}, analogMax=${this.analogMax}`);
        if (rebooted) this._emit('reboot', { bootId });

        // Open the send queue so announce frames from extensions can be
        // received while we wait for CMD_SYNC_COMPLETE.
        // 'ready' is deferred until _onSyncComplete() — after all announce
        // frames have updated the local state maps.
        this._flush();
    }

    // Called when CMD_SYNC_COMPLETE arrives — all Arduino announce frames
    // have been received and local state maps are fully synced.
    // Now replay state to the Arduino (handles the Arduino-reset case) and
    // signal 'ready' to user code.
    _onSyncComplete() {
        // Sweep: board-originated pins the announce did NOT re-mention belong
        // to a previous board-run (firmware swapped, or a reboot on old
        // firmware without boot ids) — forget them, and stop their polls.
        // A running board re-announces its shares on every reconnect, and a
        // rebooted board re-runs setup() and re-shares, so anything missing
        // here really is gone.
        if (this._staleBoardPins) {
            this._staleBoardPins.forEach(pin => {
                this._pinOrigins.delete(pin);
                this._pinModes.delete(pin);
                this._pinValues.delete(pin);
                const read = this._reads.get(pin);
                if (read && read.origin !== 'browser') this._reads.delete(pin);
            });
            this._staleBoardPins = null;
        }

        // Replay BROWSER-originated pin configuration so Arduino has the
        // correct state if it just reset (announce would have sent nothing
        // for these in that case). If the Arduino was already running, the
        // frames are redundant but idempotent. Board-originated entries are
        // skipped — the board is source of truth for its own shares (the
        // announce we just processed IS that truth), and replaying them
        // would push a previous firmware's pin config onto a new one.
        this._pinModes.forEach((mode, pin) => {
            if (this._pinOrigins.get(pin) === 'board') return;
            this.send(encodeFrame(CMD_PIN_MODE, pin, [mode]));
        });
        this._pinValues.forEach((value, pin) => {
            if (this._pinOrigins.get(pin) === 'board') return;
            this.send(encodeFrame(CMD_DIGITAL_WRITE, pin, [value]));
        });

        // Re-register our periodic reads. The Arduino clears THIS CLIENT's
        // registrations on disconnect (per-client), so
        // they always need re-sending; only JS knows the interval/threshold,
        // and the announce path deliberately doesn't re-send a poll for an
        // entry that already exists (analogRead/digitalRead early-return on
        // a cached read). Passive entries are skipped — the BOARD owns those
        // polls (share() with an interval) and they survive on their own;
        // the announce re-created them above. Stale board polls were swept,
        // so nothing here targets a pin the current firmware doesn't share.
        // The mirror keeps its seeded value; _forceCallback makes the first
        // post-sync reading fire callbacks even if the value is unchanged,
        // keeping the UI in sync with actual state.
        this._reads.forEach((read, pin) => {
            read._forceCallback = true;
            if (!read.passive && read.interval > 0)
                this.send(encodeFrame(read.cmd, pin, [read.interval, read.threshold ?? 0]));
        });

        // Pin handles with 'change' listeners need a poll on this board —
        // alias table and pin modes are both known now, so the right read
        // kind is chosen; _ensurePoll is a no-op when a poll (ours, another
        // client's, or the board's own) already covers the pin.
        this._pinHandles.forEach(h => {
            if (!(h._cbs['change'] || []).length) return;
            if (h.number === null)
                this._warn(`pin handle "${h._ref}" — unknown alias for board "${this.board}"`);
            else h._ensurePoll();
        });

        // Let extensions restore their state.
        // Each extension's _reRegister() checks whether the Arduino announced
        // its state (running) or not (reset) and acts accordingly.
        // Board-created (shared) objects are skipped: the SKETCH owns their
        // lifecycle — after a board reset it recreates them itself, and the
        // announce we just processed re-synced any that survived.
        Object.values(this._extensions).forEach(ext => {
            if (!ext._sharedFromBoard) ext._reRegister();
        });

        this._synced = true;  // announce phase complete — write broadcasts now fire callbacks
        this._flush();
        this._emit('ready');
        console.log('Pardalote: ready');
    }

    _onAnnounce(frame) {
        this._available.add(frame.target);
        this._emit('announce', { deviceId: frame.target });
    }

    _routeExtension(frame) {
        // A sketch-created object — materialise it before instance routing.
        // CMD_SHARE's value is reserved across every extension device ID.
        if (frame.cmd === CMD_SHARE) { this._onShare(frame); return; }

        const exts = this._extByDevice.get(frame.target);
        if (!exts) {
            this._warn(`no extension registered for deviceId ${frame.target}`);
            return;
        }
        const instanceId = frame.params[0];
        const ext = exts.find(e => e.logicalId === instanceId);
        if (ext) {
            ext.handleMessage(frame);
        } else {
            this._warn(`no instance ${instanceId} for deviceId ${frame.target}`);
        }
    }

    // -------------------------------------------------------------------
    // CMD_SHARE — the sketch created a hardware object (e.g.
    // PardaloteServo.attach("pan", 9)). Materialise a browser instance of
    // the registered class for that deviceId and bind it as arduino.<name>,
    // exactly as arduino.add(name, new <Class>()) would have. The board
    // follows with the normal announce/state frames (ATTACH, WRITE, …),
    // which sync the new instance through the existing machinery — so the
    // result is indistinguishable from a browser-created object, and it
    // exists before 'ready' fires.
    //
    // Frame: [logicalId] + payload: UTF-8 name. The logical id is board-
    // assigned (from the top of the range down; add() assigns from 0 up).
    // -------------------------------------------------------------------
    _onShare(frame) {
        const deviceId = frame.target;
        const id       = frame.params[0];
        const name     = frame.payload ? new TextDecoder().decode(frame.payload) : '';
        if (!name) return;

        // Reconnect to a running board: the instance already exists —
        // reuse it (state re-syncs from the announce frames that follow).
        const exts     = this._extByDevice.get(deviceId);
        const existing = exts ? exts.find(e => e.logicalId === id) : null;
        if (existing) {
            existing._name = name;
            if (!existing._sharedFromBoard) {
                // A browser-created extension already holds this id — the two
                // allocation directions (browser 0-up, board top-down) have
                // met, i.e. the id space for this device is exhausted.
                this._warn(`the board created '${name}' with id ${id}, but a ` +
                           `browser-created extension already uses that id — too many ` +
                           `instances for deviceId ${deviceId}`);
                return;
            }
            if (this._extensions[name] !== existing) {
                this._extensions[name] = existing;
                this[name] = existing;
            }
            return;
        }

        const cls = _extensionTypes.get(deviceId);
        if (!cls) {
            this._warn(`the board created '${name}' (deviceId ${deviceId}), ` +
                       `but no extension file for that device is loaded — include it ` +
                       `(e.g. <script src="servo.js">) to use arduino.${name}`);
            return;
        }

        // Refuse names that would clobber the Arduino API itself
        // (e.g. a servo named "connect"). Extension re-binds are allowed —
        // last one wins, with a warning, same as add() overwriting.
        if ((name in this) && !this._extensions[name]) {
            this._warn(`the board created '${name}', but arduino.${name} ` +
                       `is part of the core API — rename it in the sketch`);
            return;
        }
        if (this._extensions[name]) {
            this._warn(`the board created '${name}' — replacing the existing arduino.${name}`);
        }

        const ext = new cls();
        ext.arduino          = this;
        ext.logicalId        = id;
        ext._name            = name;
        ext._sharedFromBoard = true;
        this._extensions[name] = ext;
        this[name] = ext;
        if (!this._extByDevice.has(deviceId)) this._extByDevice.set(deviceId, []);
        this._extByDevice.get(deviceId).push(ext);

        this._emit('share', { name, extension: ext });
    }

    // -------------------------------------------------------------------
    // Extension registration
    // -------------------------------------------------------------------
    add(name, extension) {
        extension.arduino  = this;
        // Skip ids already held by board-created objects (they allocate from
        // the top of the range down; add() from 0 up — this guard only
        // matters once the two meet).
        const taken = new Set();
        this._extByDevice.forEach(list => list.forEach(e => {
            if (e._sharedFromBoard) taken.add(e.logicalId);
        }));
        while (taken.has(this._nextId)) this._nextId++;
        extension.logicalId = this._nextId++;
        extension._name = name;
        this._extensions[name] = extension;
        this[name] = extension;  // shorthand: arduino.servo

        const deviceId = extension.constructor.deviceId;
        if (!this._extByDevice.has(deviceId)) this._extByDevice.set(deviceId, []);
        this._extByDevice.get(deviceId).push(extension);

        return this;
    }

    // -------------------------------------------------------------------
    // group(name, members)
    // Create a named group of actuators for coordinated control. `members`
    // maps channel names to extension instances:
    //   arduino.group('arm', { shoulder: arduino.s1, elbow: arduino.s2 });
    // group.write({...}) writes every member in ONE batched WebSocket message
    // so they move together; group.writeTimed({...}, ms) makes them arrive
    // together. Returns the Group (also at arduino[name]).
    // -------------------------------------------------------------------
    group(name, members) {
        const g = new Group(this, name, members);
        this._groups[name] = g;
        this[name] = g;   // shorthand: arduino.arm
        return g;
    }

    // -------------------------------------------------------------------
    // Core API — mirrors Arduino's own function names where possible
    // -------------------------------------------------------------------

    // Resolve a pin reference to its Arduino pin number for THIS board.
    //   • number → passes through unchanged.
    //   • string alias ('A0', 'SDA', … — including the bare globals D13/A0/…,
    //     which are just strings equal to their name; see installPinGlobals)
    //     → looked up in this instance's alias table, so the same global D13
    //     maps to the right physical pin on each board / each Arduino()
    //     instance. A numeric string ('14') falls through to numeric parse.
    // Throws RangeError for unresolvable input so the call site fails
    // loudly instead of silently writing to pin 0.
    _resolvePin(pin) {
        if (typeof pin === 'number') return pin;
        if (pin in this._aliases) return this._aliases[pin];
        const n = parseInt(pin, 10);
        if (!isNaN(n)) return n;
        throw new RangeError(
            `Pardalote: unknown pin alias "${pin}" for board "${this.board}". ` +
            `Pin aliases are populated when the 'ready' event fires — call from inside arduino.on('ready', …) ` +
            `or pass a numeric pin instead.`
        );
    }

    pinMode(pin, mode, interval, threshold) {
        pin = this._resolvePin(pin);
        this._pinModes.set(pin, mode);   // stored for announce sync and _onSyncComplete replay
        this._pinOrigins.set(pin, 'browser');   // this page claims the pin — replayed on reconnect
        this.end(pin);                   // cancel any active periodic read before changing mode
        this.send(encodeFrame(CMD_PIN_MODE, pin, [mode]));
        // For input modes, auto-start polling. If `interval` / `threshold`
        // are given use them, otherwise the underlying digitalRead /
        // analogRead falls back to setReadInterval()/setReadThreshold()
        // values, then to defaultInterval (200 ms) / defaultThreshold
        // (0 = board default). OUTPUT modes never auto-poll.
        this._maybeStartPollFor(pin, mode, interval, 'browser', threshold);
        return this;
    }

    // Shared helper used by pinMode() and by the incoming CMD_PIN_MODE handler.
    // For input-type modes, kick off a periodic read at the given interval
    // (or defaultInterval if undefined). No-op for OUTPUT or unknown modes.
    // `origin` tags any read entry this creates ('board' when called from the
    // inbound handler — a sketch share()'s auto-poll — else 'browser'), via
    // _pollOrigin, which digitalRead/analogRead consult while it's set.
    _maybeStartPollFor(pin, mode, interval, origin = 'browser', threshold) {
        this._pollOrigin = origin;
        try {
            if (mode === ANALOG_INPUT_MODE) {
                this.analogRead(pin, interval, threshold);
            } else if (mode === INPUT || mode === INPUT_PULLUP || mode === INPUT_PULLDOWN) {
                this.digitalRead(pin, interval, threshold);
            }
        } finally {
            this._pollOrigin = null;
        }
    }

    digitalWrite(pin, value) {
        pin = this._resolvePin(pin);
        // Accept HIGH/LOW (1/0) or a boolean (true/false) — normalise to an
        // integer 0/1 so the frame carries an int param. A raw boolean would
        // otherwise be encoded as a float (encodeFrame keys off
        // Number.isInteger) and the board would misread the pin state.
        value = value ? 1 : 0;
        this._pinValues.set(pin, value);  // stored for announce sync and _onSyncComplete replay
        this._pinOrigins.set(pin, 'browser');   // this page claims the pin — replayed on reconnect
        this.send(encodeFrame(CMD_DIGITAL_WRITE, pin, [value]));
        return this;
    }

    // analogWrite(pin, value) — write a PWM duty (0–255).
    // Rate-limited per pin by writeThrottle (see the constructor): the first
    // write in a burst is sent immediately, rapid follow-ups (a slider drag,
    // a draw loop) are coalesced into a single trailing send that carries the
    // final value. Tune with setWriteThrottle()/setWriteThreshold(); set the
    // throttle to 0 to send every value (the old behaviour).
    analogWrite(pin, value) {
        pin = this._resolvePin(pin);
        this._pwmScheduleWrite(pin, Math.round(value));
        return this;
    }

    // Leading-edge-immediate, trailing-edge-coalesced scheduler. Keeps the
    // documented "individual writes flush immediately" feel for a single
    // write while capping a fast stream. The latest value always wins the
    // trailing slot, so the resting position is never dropped.
    _pwmScheduleWrite(pin, value) {
        if (this.writeThrottle <= 0) { this._pwmSend(pin, value); return; }
        const now  = Date.now();
        const wait = this.writeThrottle - (now - (this._pwmLastWrite.get(pin) || 0));
        if (wait > 0) {
            const t = this._pwmPending.get(pin);
            if (t) clearTimeout(t);
            this._pwmPending.set(pin, setTimeout(() => {
                this._pwmPending.delete(pin);
                this._pwmSend(pin, value);
            }, wait));
        } else {
            this._pwmSend(pin, value);
        }
    }

    _pwmSend(pin, value) {
        if (this.writeThreshold > 0 && this._pwmLastSent.has(pin) &&
            Math.abs(value - this._pwmLastSent.get(pin)) < this.writeThreshold) {
            return;
        }
        this.send(encodeFrame(CMD_ANALOG_WRITE, pin, [value]));
        this._pwmLastWrite.set(pin, Date.now());
        this._pwmLastSent.set(pin, value);
    }

    // Cancel every coalesced trailing send and forget the per-pin history.
    // Called on (re)connect so a value queued for the old board never lands
    // on the new one.
    _pwmCancelPending() {
        for (const t of this._pwmPending.values()) clearTimeout(t);
        this._pwmPending.clear();
        this._pwmLastWrite.clear();
        this._pwmLastSent.clear();
    }

    // setWriteThrottle(ms) — minimum ms between PWM sends on a pin (0 = off,
    //   send every value). Applies to all analogWrite() pins. Default 20.
    // setWriteThreshold(v) — minimum duty change worth sending (0 = send all).
    // Both chainable. Useful when driving analogWrite() from mouse movement
    // or a draw loop, especially on the UNO R4 WiFi.
    setWriteThrottle(ms)  { this.writeThrottle  = Math.max(0, ms); return this; }
    setWriteThreshold(v)  { this.writeThreshold = Math.max(0, v);  return this; }

    // digitalRead(pin, interval, threshold) — start/update a board-side watch.
    // digitalRead(pin)      — return cached value; no network traffic.
    // digitalRead(pin, END) — stop this browser's watch.
    // interval: minimum ms between updates to this browser (default:
    //   setReadInterval() value, else defaultInterval, 200 ms). Digital
    //   edges transmit immediately regardless — the interval never delays
    //   a button press; analog pins are sampled every 10 ms on the board
    //   and rate-limited per browser by the interval.
    // threshold: minimum change worth transmitting (default:
    //   setReadThreshold() value, else defaultThreshold; 0 = board default —
    //   1 for digital, the ADC noise floor for analog). Per-browser: other
    //   pages polling the same pin keep their own interval and threshold.
    // Calling again with the same settings just returns the cached value.
    // If the pin was previously registered as analogRead, that read is cancelled first.
    digitalRead(pin, interval, threshold) {
        return this._read(CMD_DIGITAL_READ, pin, interval, threshold);
    }

    // analogRead(pin, interval, threshold) — same contract as digitalRead().
    analogRead(pin, interval, threshold) {
        return this._read(CMD_ANALOG_READ, pin, interval, threshold);
    }

    // Shared implementation of digitalRead / analogRead.
    _read(cmd, pin, interval, threshold) {
        pin = this._resolvePin(pin);
        if (interval === END) { this.end(pin); return 0; }
        let read = this._reads.get(pin);
        if (read && read.cmd !== cmd) { this.end(pin); read = null; }
        // Fast path — nothing new requested: return the mirror.
        if (read && (interval  === undefined || read.interval  === interval)
                 && (threshold === undefined || read.threshold === threshold))
            return read.value ?? 0;
        const cfg = this._readConfig.get(pin);
        interval  ??= cfg?.interval  ?? this.defaultInterval;
        threshold ??= cfg?.threshold ?? this.defaultThreshold;
        if (!read) {
            read = { cmd, interval, threshold, value: null,
                     origin: this._pollOrigin ?? 'browser', passive: false };
            this._reads.set(pin, read);
        } else {
            read.interval  = interval;
            read.threshold = threshold;
            read.passive   = false;   // we now hold our own registration
            if (!this._pollOrigin) read.origin = 'browser';   // explicit user call claims the poll
        }
        this.send(encodeFrame(cmd, pin, [interval, threshold]));
        return read.value ?? 0;
    }

    // setReadInterval(pin, ms) / setReadThreshold(pin, t)
    // Set a pin's poll interval / change threshold directly — before polling
    // starts (stored, applied when the read registers) or while it runs
    // (re-registers immediately). threshold 0 = board default. Chainable.
    setReadInterval(pin, ms)  { return this._setReadConfig(pin, 'interval',  ms); }
    setReadThreshold(pin, t)  { return this._setReadConfig(pin, 'threshold', t);  }

    _setReadConfig(pin, key, value) {
        pin = this._resolvePin(pin);
        const cfg = this._readConfig.get(pin) || {};
        cfg[key] = value;
        this._readConfig.set(pin, cfg);
        const read = this._reads.get(pin);
        if (read) {
            // Live poll (ours or one we're passively following): register
            // our own settings with the board. Per-client on the board, so
            // this never disturbs another browser's poll.
            read[key] = value;
            if (!read.interval) read.interval = this.defaultInterval;   // was a passive cache entry
            read.threshold ??= this.defaultThreshold;
            read.passive = false;
            read.origin  = 'browser';
            this.send(encodeFrame(read.cmd, pin, [read.interval, read.threshold]));
        }
        return this;
    }

    // -------------------------------------------------------------------
    // pin(ref) — the handle for LISTENING to a pin. Same grammar as the
    // device extensions: on/off with object payloads, setRead* config.
    // The Arduino-mirroring verbs (digitalRead, digitalWrite, pinMode)
    // remain the way you DO things; the handle carries the invented
    // surface — events and per-pin configuration.
    //
    //   const knob = arduino.pin('A0');
    //   knob.on('change', ({ value }) => circle(value));
    //   knob.setReadInterval(25).setReadThreshold(4);
    //
    // Handles are cached (pin(9) twice → same object) and permanent:
    // listeners survive connect() to a new board, like device extensions.
    // Alias handles resolve lazily — arduino.pin('A0') works before
    // 'ready', even though the board's alias table hasn't arrived yet.
    // -------------------------------------------------------------------
    pin(ref) {
        let key;
        try { key = this._resolvePin(ref); }      // pin('A0') and pin(14) share a handle…
        catch (_) { key = String(ref); }          // …unresolvable alias: keyed by name for now
        let p = this._pinHandles.get(key);
        if (!p) { p = new Pin(this, ref); this._pinHandles.set(key, p); }
        return p;
    }

    // Deliver a pin-state change (input reading past threshold, or an
    // output write from any client/the sketch) to the 'change' event and
    // to every matching pin handle.
    _emitPinChange(pin, value) {
        this._emit('change', { pin, value });
        this._pinHandles.forEach(h => {
            if (h.number === pin) h._emit('change', { value, pin });
        });
    }

    // Stop periodic reads for a pin.
    end(pin) {
        pin = this._resolvePin(pin);
        this._reads.delete(pin);
        this.send(encodeFrame(CMD_END, pin, []));
        return this;
    }

    // Stop all active periodic reads — call this before switching boards.
    endAll() {
        this._reads.forEach((_, pin) => {
            this.send(encodeFrame(CMD_END, pin, []));
        });
        this._reads.clear();
        return this;
    }

    getStatus() {
        return {
            connected:         this.connected,
            isReconnecting:    this._isReconnecting,
            reconnectAttempts: this._reconnectAttempts,
            deviceIP:          this.deviceIP,
            availableExtensions: [...this._available]
        };
    }
}

// =====================================================================
// Group — a named collection of actuators for coordinated control.
//
// Naming mirrors the single actuators: write() = immediate, writeTimed() =
// arrive together in ~duration ms, whenDone() = awaitable completion.
//
// Layer 1: write() sends every member's value in a SINGLE batched WebSocket
// message (frames coalesced via arduino.send([...])). On the board they are
// parsed and applied back-to-back within one receive, so the members move
// together. read() polls/reports every member.
//
// Members must implement the group member adapter (_memberWrite + the
// memberValue getter) — currently Servo, BusServo and Stepper. Anything
// else raises a clear error at construction.
// =====================================================================
class Group {
    constructor(arduino, name, members) {
        this.arduino = arduino;
        this.name    = name;
        this.members = {};

        // Last-commanded value per member — the assumed "current" position for
        // writeTimed() distance/speed matching. Seeded from memberValue on first use.
        this._commanded = {};

        // Members involved in the most recent write()/writeTimed(), and that
        // move's duration — consumed by whenDone().
        this._lastMoved    = [];
        this._lastDuration = 0;

        if (!members || typeof members !== 'object' || Array.isArray(members)) {
            throw new TypeError(
                `Group '${name}': members must be an object like ` +
                `{ shoulder: arduino.s1, elbow: arduino.s2 }`);
        }
        for (const [key, m] of Object.entries(members)) {
            if (!m || typeof m._memberWrite !== 'function' || !('memberValue' in m)) {
                throw new TypeError(
                    `Group '${name}': member '${key}' is not a groupable actuator ` +
                    `(supported: Servo, BusServo, Stepper).`);
            }
            this.members[key] = m;
        }
    }

    // write({ name: value, ... }) — write all named members in ONE message.
    // The group counterpart of servo.write() / stepper.moveTo(): immediate,
    // each member at its own configured/default speed.
    //
    // Members that expose a hardware sync key (_memberSyncKey) and share it
    // with another member in the same call are coalesced into a single sync
    // frame (e.g. bus servos of one series → one Feetech SyncWrite packet, so
    // they latch together). Everything else uses _memberWrite. All resulting
    // frames still go out in one batched WebSocket message.
    write(values) {
        if (!values || typeof values !== 'object') return this;
        this._lastMoved    = [];
        this._lastDuration = 0;

        const buckets = new Map();   // syncKey → [[member, value], ...]
        const loose   = [];          // [[member, value], ...]
        for (const [key, v] of Object.entries(values)) {
            const m = this.members[key];
            if (!m) { this.arduino._notify('warn', `Group '${this.name}'`, `no member '${key}'`); continue; }
            if (typeof v === 'number') this._commanded[key] = Math.round(v);
            this._lastMoved.push(m);
            const sk = (typeof m._memberSyncKey === 'function') ? m._memberSyncKey() : null;
            if (sk) {
                if (!buckets.has(sk)) buckets.set(sk, []);
                buckets.get(sk).push([m, v]);
            } else {
                loose.push([m, v]);
            }
        }

        const frames = [];
        for (const entries of buckets.values()) {
            if (entries.length >= 2 && typeof entries[0][0]._memberSetEncode === 'function') {
                frames.push(...entries[0][0]._memberSetEncode(entries));   // one sync packet
            } else {
                for (const [m, v] of entries) frames.push(...m._memberWrite(v));
            }
        }
        for (const [m, v] of loose) frames.push(...m._memberWrite(v));

        if (frames.length) this.arduino.send(frames);   // single batched WebSocket message
        return this;
    }

    // writeTimed({ name: target, ... }, duration)
    // Coordinated move where all members ARRIVE together after ~`duration` ms.
    // The group counterpart of servo.writeTimed() / stepper.moveToTimed() —
    // same shape: targets first, duration in ms second.
    // Each actuator type does this its own way, via _memberMoveEncode():
    //   - bus servos: one SyncWrite with matched per-servo speeds;
    //   - PWM servos: one on-board interpolated SYNC_TIMED (shared duration);
    //   - steppers:  one SYNC_MOVE with board-computed matched speeds;
    // all coalesced into a single batched message.
    //
    // "Current" position is the last commanded value (seeded from memberValue).
    // For an accurate first move from an unknown pose, poll read() first or move
    // from a known start (center()/write()).
    //
    // Members without a timed-move hook move immediately.
    writeTimed(targets, duration = 1000) {
        if (!targets || typeof targets !== 'object') return this;
        this._lastMoved    = [];
        this._lastDuration = Math.max(0, duration);

        const buckets = new Map();   // syncKey → [[m, target, current], ...]
        const loose   = [];          // [[m, target], ...]
        for (const [key, raw] of Object.entries(targets)) {
            const m = this.members[key];
            if (!m) { this.arduino._notify('warn', `Group '${this.name}'`, `no member '${key}'`); continue; }
            const target  = Math.round(raw);
            const current = (this._commanded[key] !== undefined) ? this._commanded[key] : (m.memberValue || 0);
            this._commanded[key] = target;
            this._lastMoved.push(m);
            const sk = (typeof m._memberSyncKey === 'function') ? m._memberSyncKey() : null;
            if (sk && typeof m._memberMoveEncode === 'function') {
                if (!buckets.has(sk)) buckets.set(sk, []);
                buckets.get(sk).push([m, target, current]);
            } else {
                loose.push([m, target]);
            }
        }

        const frames = [];
        for (const entries of buckets.values()) {
            frames.push(...entries[0][0]._memberMoveEncode(entries, duration));   // per-type timing
        }
        for (const [m, target] of loose) frames.push(...m._memberWrite(target));

        if (frames.length) this.arduino.send(frames);
        return this;
    }

    // gesture({ name: segments, ... }, opts?)
    // Coordinated expressive motion — each named member plays its own SEGMENT
    // SCHEDULE (see the per-actuator gesture()), all pushed in ONE batched
    // message and played on the board's own clock. Lanes are per-member, so a
    // member's segments overlap its neighbours' → coordination and follow-
    // through. Uneven lanes are padded with a trailing hold so every member
    // still ARRIVES TOGETHER (the group counterpart of writeTimed()).
    //
    //   arm.gesture({
    //       shoulder: [{ by: 300, dur: 400, curve: 'easeOut'   },
    //                  { by:-300, dur: 600, curve: 'easeInOut' }],   // 1000 ms
    //       wrist:    [{ by:  20, dur: 250, curve: 'back'       }],   // 250 ms → padded to 1000
    //   });
    //   await arm.gesture({ ... }).whenDone();
    //
    // Each lane is relative by default (infers absolute from `to`, or opts.absolute).
    // Members without gesture support, and empty/unknown lanes, are skipped with a warn.
    gesture(lanes, opts = {}) {
        if (!lanes || typeof lanes !== 'object') return this;
        this._lastMoved = [];

        // 1. Resolve lanes → per-member items; infer reference frame + total duration.
        const items = [];
        for (const [key, segs] of Object.entries(lanes)) {
            const m = this.members[key];
            if (!m) { this.arduino._notify('warn', `Group '${this.name}'`, `no member '${key}'`); continue; }
            if (typeof m._memberGestureEncode !== 'function' || typeof m._gestureBlock !== 'function') {
                this.arduino._notify('warn', `Group '${this.name}'`, `member '${key}' doesn't support gesture()`); continue;
            }
            if (!Array.isArray(segs) || segs.length === 0) {
                this.arduino._notify('warn', `Group '${this.name}'`, `lane '${key}' needs a non-empty array of segments`); continue;
            }
            const absolute = (opts.absolute !== undefined) ? !!opts.absolute : segs.some(s => s.to !== undefined);
            const total    = segs.reduce((n, s) => n + Math.max(1, Math.round(s.dur ?? 0)), 0);
            items.push({ m, segments: segs.slice(), total, absolute });
        }
        if (!items.length) return this;

        // 2. Pad short lanes with a trailing hold so all arrive together. Hold in
        //    place: relative → zero delta; absolute → the lane's last target.
        const maxTotal = items.reduce((mx, it) => Math.max(mx, it.total), 0);
        for (const it of items) {
            const padMs = maxTotal - it.total;
            if (padMs <= 0) continue;
            const last = it.segments[it.segments.length - 1];
            it.segments = it.segments.concat([ it.absolute
                ? { to: (last.to ?? it.m.memberValue ?? 0), dur: padMs, curve: 'linear' }
                : { by: 0, dur: padMs, curve: 'linear' } ]);
        }

        // 3. Bucket by actuator TYPE — one CMD_*_GESTURE frame per type, each
        //    carrying every member's channel block, all in one batched message.
        const buckets = new Map();   // deviceId → [[member, segments], ...]
        for (const it of items) {
            const dev = it.m.constructor.deviceId;
            if (!buckets.has(dev)) buckets.set(dev, []);
            buckets.get(dev).push([it.m, it.segments]);
            this._lastMoved.push(it.m);
        }

        const frames = [];
        for (const entries of buckets.values())
            frames.push(...entries[0][0]._memberGestureEncode(entries));
        if (frames.length) this.arduino.send(frames);   // single batched message
        this._lastDuration = maxTotal;
        return this;
    }

    // whenDone({ timeout }?) — Promise for the group's most recent
    // write()/writeTimed(). Resolves `true` when EVERY moved member reports it
    // actually ARRIVED (each actuator's 'done' — feedback-confirmed, not a
    // timer), or `false` on the safety timeout (dead servo / lost link).
    // Members arm their completion promise inside the move itself, so calling
    // whenDone() late is safe — already-finished members resolve immediately.
    //
    //   await arm.writeTimed({ shoulder: 45, elbow: 120 }, 1500).whenDone();
    //
    // timeout: ms before giving up (default max(duration × 2, 10000); 0 = wait
    // forever). Also accepts a bare number: whenDone(5000).
    whenDone(opts = {}) {
        const t = (typeof opts === 'number') ? opts : opts.timeout;
        const timeout = t ?? Math.max(this._lastDuration * 2, 10000);
        const waits = this._lastMoved.map(m => m._movePromise).filter(Boolean);
        if (!waits.length) return Promise.resolve(true);
        const done = Promise.all(waits).then(() => true);
        if (!timeout) return done;
        return Promise.race([
            done,
            new Promise(res => setTimeout(() => res(false), timeout)),
        ]);
    }

    // read()         — snapshot of each member's current value (from cache).
    // read(interval) — start polling every member at interval, return snapshot.
    // read(END)      — stop polling every member.
    read(interval) {
        if (interval !== undefined) {
            Object.values(this.members).forEach(m => m.read(interval));
        }
        return this.values();
    }

    // Current cached value of every member, keyed by channel name.
    values() {
        const out = {};
        for (const [key, m] of Object.entries(this.members)) out[key] = m.memberValue;
        return out;
    }

    // Halt every member's motion — the group counterpart of member.stop().
    // (To stop polling, use read(END), same as a single actuator.)
    stop() {
        Object.values(this.members).forEach(m => { if (typeof m.stop === 'function') m.stop(); });
        return this;
    }

    // home(duration?) — send every member home. Servos and bus servos move
    // to their stored home (timed if `duration` is given); steppers run
    // their homing routine (a routine has no duration — the number is
    // ignored by stepper.home()). NOT arrive-together: each member homes
    // at its own pace. whenDone() resolves when every member settles —
    // homing can be slow, so raise the timeout:
    //   await rig.home(1500).whenDone({ timeout: 30000 });
    home(duration) {
        this._lastMoved    = [];
        this._lastDuration = Math.max(0, duration || 0);
        for (const m of Object.values(this.members)) {
            if (typeof m.home !== 'function') continue;
            m.home(duration);
            this._lastMoved.push(m);
        }
        return this;
    }

    getState() {
        const out = {};
        for (const [key, m] of Object.entries(this.members)) {
            out[key] = (typeof m.getState === 'function') ? m.getState() : m.memberValue;
        }
        return { name: this.name, members: out };
    }
}

// ----- pardalote-servo.js ------------------------------------
// ==============================================================
// servo.js
// Pardalote Servo Extension
// Part of Pardalote — version in package.json
// by Scott Mitchell
// GPL-3.0-or-later License
//
// Mirrors the Arduino Servo library API where possible.
//
// Usage:
//   const arduino = new Arduino();
//   arduino.add('servo', new Servo());
//   arduino.connect('192.168.1.42');
//
//   arduino.on('ready', () => {
//       arduino.servo.attach(D9);
//       arduino.servo.write(90);
//   });
//
// Servos created BY THE SKETCH (PardaloteServo.attach("pan", 9)) appear
// automatically as arduino.pan — a full Servo instance like any other.
// It exists by the time 'ready' fires; no arduino.add() needed.
// ==============================================================

const DEVICE_SERVO = 201;

const CMD_SERVO_ATTACH             = 0x14;
const CMD_SERVO_DETACH             = 0x15;
const CMD_SERVO_WRITE              = 0x16;
const CMD_SERVO_WRITE_MICROSECONDS = 0x17;
const CMD_SERVO_READ               = 0x18;
const CMD_SERVO_ATTACHED           = 0x19;
const CMD_SERVO_WRITE_TIMED        = 0x1A;
const CMD_SERVO_SYNC_TIMED         = 0x1B;
const CMD_SERVO_STOP               = 0x1C;
const CMD_SERVO_DONE               = 0x1D;
const CMD_SERVO_SET_LIMITS         = 0x54;  // [id, min, max, enabled] — board-clamped soft angle limits
                                            // (numbered after the stepper switch block; 0x14–0x1D was full)
const CMD_SERVO_GESTURE            = 0x58;  // global: payload = servo channel blocks (segment schedules).
                                            // See pardalote.js CURVE_IDS / GESTURE_FLAG_* and defs.h.

// Board-side cap (PardaloteServo.h MAX_SERVO_SEGMENTS) — mirrored so the JS
// side can warn instead of silently overrunning. Extra segments are dropped.
const MAX_SERVO_SEGMENTS = 16;

class Servo extends Extension {
    static deviceId = DEVICE_SERVO;

    constructor() {
        super();

        // Hardware state
        this.pin        = -1;
        this.isAttached = false;
        this.angle      = 90;
        this.micros     = 1500;
        this.minPulse   = 544;
        this.maxPulse   = 2400;

        // Soft angle limits (safety) — enforced on the board; mirrored here
        // so cached state matches what the board actually applied.
        this.limitMin     = 0;
        this.limitMax     = 180;
        this.limitEnabled = false;

        // Home angle — where home() goes. Default: centre. JS-side only
        // (a PWM servo's angle is command-equals-state; nothing to re-zero).
        this.homeAngle = 90;

        // Write throttling
        this.writeThrottle  = 20;   // min ms between sends
        this._lastWriteTime = 0;
        this._pendingWrite  = null;

        // Write threshold — skip sends below this many degrees of change.
        // First send after attach always goes through (_lastSentAngle starts null)
        // so the servo physically moves to its initial position.
        this.writeThreshold = 1;
        this._lastSentAngle = null;

        // Periodic read registration (board-side).
        // _readThreshold is in degrees; 0 = board default (1 degree).
        // Survives _reset() — it's user-tuned configuration.
        this._readInterval  = 0;
        this._readThreshold = 0;

        // Sweep cancellation
        this._sweepAbort = false;

        // Pending _whenDone() resolvers, drained on the 'done' event
        this._doneResolvers = [];

        // Pending attached() resolvers — entries { resolve, timer }.
        this._attachedResolvers = [];

        // Promise for the most recent move, consumed by whenDone(). Armed by
        // moves that will produce a 'done' (writeTimed, group timed moves);
        // cleared (null) by moves that won't (plain write). _moveDuration is
        // the last timed move's ms, used for whenDone's default timeout.
        this._movePromise  = null;
        this._moveDuration = 0;

        // Set to true when the Arduino announces this servo's attach state
        // on connect. _reRegister() uses this to skip re-sending CMD_SERVO_ATTACH
        // when the Arduino is already in sync — only replay when it has reset.
        this._announcedByArduino = false;
    }

    // -------------------------------------------------------------------
    // Board switch — called by Arduino.connect() to wipe per-board state
    // while preserving user-tuned configuration (throttle, threshold).
    // -------------------------------------------------------------------
    _reset() {
        if (this._pendingWrite) { clearTimeout(this._pendingWrite); this._pendingWrite = null; }
        this._readInterval = 0;  // registration died with the old board — send nothing
        this._resolveDone();     // don't leave awaiters hanging on a board switch
        this._resolveAttached(false);
        this._movePromise        = null;
        this._moveDuration       = 0;
        this._sweepAbort         = true;
        this.pin                 = -1;
        this.isAttached          = false;
        this.angle               = 90;
        this.micros              = 1500;
        this.minPulse            = 544;
        this.maxPulse            = 2400;
        this._lastSentAngle      = null;
        this._lastWriteTime      = 0;
        this.limitMin            = 0;
        this.limitMax            = 180;
        this.limitEnabled        = false;
        this.homeAngle           = 90;
        this._announcedByArduino = false;
    }

    // Clamp an angle to 0–180 and, if set, the soft limits — mirrors the
    // board's clampAngle() so cached state never disagrees with hardware.
    _clampAngle(angle) {
        angle = Math.max(0, Math.min(180, Math.round(angle)));
        if (this.limitEnabled) angle = Math.max(this.limitMin, Math.min(this.limitMax, angle));
        return angle;
    }

    // -------------------------------------------------------------------
    // Reconnection — called by Arduino core after CMD_SYNC_COMPLETE.
    //
    // Two cases:
    //   Arduino reset  (_announcedByArduino = false):
    //     Arduino has no record of this servo. Replay attach + last angle.
    //   Arduino running (_announcedByArduino = true):
    //     announce() already synced our state from the Arduino — skip the
    //     replay (avoids the duplicate detach/attach cycle and Serial noise).
    // -------------------------------------------------------------------
    _reRegister() {
        if (this.isAttached && !this._announcedByArduino) {
            this._sendAttach();
            if (this.limitEnabled) {
                this.arduino.send(encodeFrame(CMD_SERVO_SET_LIMITS, DEVICE_SERVO,
                    [this.logicalId, this.limitMin, this.limitMax, 1]));
            }
            this.arduino.send(encodeFrame(CMD_SERVO_WRITE, DEVICE_SERVO,
                [this.logicalId, this.angle]));  // raw send — no event, no throttle update
        }
        // Periodic read registrations are per-WS-client on the Arduino
        // (cleared on disconnect), so always re-register if active.
        if (this.isAttached && this._readInterval > 0) this._sendRead();
        // Reset for next disconnect/reconnect cycle.
        this._announcedByArduino = false;
    }

    // -------------------------------------------------------------------
    // attach(pin, min?, max?)
    // Attach this servo to a pin. Optionally override pulse range.
    // -------------------------------------------------------------------
    attach(pin, min = 544, max = 2400) {
        this.pin      = this.arduino._resolvePin(pin);
        this.minPulse = min;
        this.maxPulse = max;
        this._lastSentAngle = null;   // first write after (re-)attach always sends
        this._sendAttach();
        this.isAttached = true;
        return this;
    }

    _sendAttach() {
        this.arduino.send(encodeFrame(
            CMD_SERVO_ATTACH, DEVICE_SERVO,
            [this.logicalId, this.pin, this.minPulse, this.maxPulse]
        ));
    }

    // -------------------------------------------------------------------
    // detach()
    // Release the servo pin.
    // -------------------------------------------------------------------
    detach() {
        this._stopRead();
        this.arduino.send(encodeFrame(
            CMD_SERVO_DETACH, DEVICE_SERVO,
            [this.logicalId]
        ));
        this.isAttached     = false;
        this.pin            = -1;
        this._lastSentAngle = null;
        return this;
    }

    // -------------------------------------------------------------------
    // write(angle)
    // Move servo to angle (0–180°). Respects throttle.
    // Any call to write() cancels an in-progress sweep.
    // -------------------------------------------------------------------
    write(angle) {
        this._sweepAbort   = true;
        this._movePromise  = null;   // instant move — nothing to await
        this._moveDuration = 0;
        if (!this.isAttached) {
            this._warn('not attached');
            return this;
        }

        angle = this._clampAngle(angle);

        const now = Date.now();
        const wait = this.writeThrottle - (now - this._lastWriteTime);

        if (wait > 0) {
            if (this._pendingWrite) clearTimeout(this._pendingWrite);
            this._pendingWrite = setTimeout(() => {
                this._sendAngle(angle);
                this._pendingWrite = null;
            }, wait);
        } else {
            this._sendAngle(angle);
        }
        return this;
    }

    _sendAngle(angle) {
        angle = this._clampAngle(angle);
        if (this._lastSentAngle !== null &&
            Math.abs(angle - this._lastSentAngle) < this.writeThreshold) {
            return;
        }
        this.arduino.send(encodeFrame(
            CMD_SERVO_WRITE, DEVICE_SERVO,
            [this.logicalId, angle]
        ));
        this.angle          = angle;
        this.micros         = this._angleToMicros(angle);
        this._lastWriteTime = Date.now();
        this._lastSentAngle = angle;
        this._emit('write', { angle });
    }

    // -------------------------------------------------------------------
    // writeMicroseconds(us)
    // Fine-grained control via pulse width (544–2400µs).
    // -------------------------------------------------------------------
    writeMicroseconds(us) {
        this._sweepAbort   = true;
        this._movePromise  = null;   // instant move — nothing to await
        this._moveDuration = 0;
        if (!this.isAttached) return this;

        us = Math.max(this.minPulse, Math.min(this.maxPulse, Math.round(us)));
        if (this.limitEnabled) {
            // Translate the angle limits into the pulse domain (mirrors the board).
            const span = this.maxPulse - this.minPulse;
            const usMin = this.minPulse + this.limitMin / 180 * span;
            const usMax = this.minPulse + this.limitMax / 180 * span;
            us = Math.round(Math.max(usMin, Math.min(usMax, us)));
        }

        this.arduino.send(encodeFrame(
            CMD_SERVO_WRITE_MICROSECONDS, DEVICE_SERVO,
            [this.logicalId, us]
        ));
        this.micros = us;
        this.angle  = this._microsToAngle(us);
        this._emit('write', { angle: this.angle, micros: us });
        return this;
    }

    // -------------------------------------------------------------------
    // writeTimed(angle, duration)
    // Move to `angle` over `duration` ms — the Arduino interpolates on-board
    // (smooth, no WiFi streaming). Fires 'done' when it arrives.
    // -------------------------------------------------------------------
    writeTimed(angle, duration = 1000) {
        this._sweepAbort = true;
        if (!this.isAttached) { this._warn('not attached'); return this; }
        angle = this._clampAngle(angle);
        this._armDone(duration);
        this.arduino.send(encodeFrame(CMD_SERVO_WRITE_TIMED, DEVICE_SERVO,
            [this.logicalId, angle, Math.max(0, Math.round(duration))]));
        this.angle          = angle;
        this.micros         = this._angleToMicros(angle);
        this._lastSentAngle = angle;
        this._emit('write', { angle });
        return this;
    }

    // -------------------------------------------------------------------
    // gesture(segments, opts?) — play an authored SEGMENT SCHEDULE on-board.
    //
    // A gesture generalises writeTimed(): instead of one eased move it plays
    // an ordered list of eased segments back-to-back, on the board's own
    // clock (no WiFi streaming). Each segment is { dur, curve, and either
    // `by` (relative delta) or `to` (absolute angle) }:
    //
    //   pan.gesture([                       // a nod with follow-through
    //       { by:  25, dur: 250, curve: 'easeOut' },
    //       { by: -25, dur: 400, curve: 'easeInOut' },
    //       { by:   6, dur: 180, curve: 'back' },   // small overshoot settle
    //   ]);
    //   await pan.gesture([...]).whenDone();
    //
    // Reference frame (per gesture): relative by default — the portable
    // primitive, needing no absolute truth (`from` is captured on-board at
    // each segment). Use `to`, or opts.absolute, for absolute targets;
    // servos are absolute-capable so both are allowed. Fires 'done' (and
    // resolves whenDone()) when the last segment lands.
    // -------------------------------------------------------------------
    gesture(segments, opts = {}) {
        const blk = this._gestureBlock(segments, opts);
        if (!blk) return this;
        this.arduino.send(encodeFrame(CMD_SERVO_GESTURE, DEVICE_SERVO, [], blk.bytes));
        return this;
    }

    // Encode ONE gesture channel block — shared by gesture() (wrap + send) and
    // the group adapter _memberGestureEncode() (batched, no send). Arms
    // whenDone(), updates cached angle, emits 'gesture'. Returns { bytes, total }
    // or null when there's nothing to play.
    _gestureBlock(segments, opts = {}) {
        this._sweepAbort = true;
        if (!this.isAttached) { this._warn('not attached (gesture)'); return null; }
        if (!Array.isArray(segments) || segments.length === 0) {
            this._warn('gesture: needs a non-empty array of segments');
            return null;
        }

        const usesTo = segments.some(s => s.to !== undefined);
        const usesBy = segments.some(s => s.by !== undefined || s.value !== undefined);
        const absolute = (opts.absolute !== undefined) ? !!opts.absolute : usesTo;
        if (usesTo && usesBy)
            this._warn(`gesture: mixes 'to' (absolute) and 'by' (relative) — treating whole gesture as ${absolute ? 'absolute' : 'relative'}`);

        if (segments.length > MAX_SERVO_SEGMENTS)
            this._warn(`gesture: ${segments.length} segments exceeds board max ${MAX_SERVO_SEGMENTS} — extra segments dropped`);
        const count = Math.min(segments.length, MAX_SERVO_SEGMENTS);

        const flags = absolute ? GESTURE_FLAG_ABSOLUTE : 0;

        // Encode: [logicalId u8, flags u8, count u8] + count × {curve u8, dur u16, value i32}.
        const bytes = new Uint8Array(3 + count * 7);
        const dv    = new DataView(bytes.buffer);
        dv.setUint8(0, this.logicalId & 0xFF);
        dv.setUint8(1, flags & 0xFF);
        dv.setUint8(2, count & 0xFF);
        let total = 0, rest = this.angle;
        for (let i = 0; i < count; i++) {
            const s   = segments[i];
            const off = 3 + i * 7;
            const dur = Math.max(1, Math.round(s.dur ?? 0));
            // Wire value: absolute → clamped target; relative → raw delta (board clamps the result).
            const val = absolute ? this._clampAngle(Math.round(s.to ?? this.angle))
                                 : Math.round(s.by ?? s.value ?? 0);
            dv.setUint8(off, curveId(s.curve));
            dv.setUint16(off + 1, dur & 0xFFFF, false);
            dv.setInt32(off + 3, val, false);
            total += dur;
            // Predict the resting angle so cached state / memberValue track the gesture.
            rest = absolute ? this._clampAngle(Math.round(s.to ?? rest))
                            : this._clampAngle(rest + Math.round(s.by ?? s.value ?? 0));
        }

        this._armDone(total);
        this.angle          = rest;
        this.micros         = this._angleToMicros(rest);
        this._lastSentAngle = rest;
        this._emit('gesture', { segments: count, absolute, duration: total });
        return { bytes, total };
    }

    // Group adapter (group.gesture()). entries: [[member, segments], ...], all
    // Servos → one CMD_SERVO_GESTURE frame carrying every member's channel
    // block; the board plays them phase-locked on its own clock. Returns
    // frame(s) WITHOUT sending, so the group batches all types into one message.
    _memberGestureEncode(entries) {
        const blocks = [];
        for (const [m, segs] of entries) { const b = m._gestureBlock(segs); if (b) blocks.push(b.bytes); }
        if (!blocks.length) return [];
        const payload = new Uint8Array(blocks.reduce((n, b) => n + b.length, 0));
        let off = 0;
        for (const b of blocks) { payload.set(b, off); off += b.length; }
        return [encodeFrame(CMD_SERVO_GESTURE, DEVICE_SERVO, [], payload)];
    }

    // -------------------------------------------------------------------
    // Soft angle limits (safety) — same shape as stepper.setLimits().
    // Enforced ON THE BOARD (browser and sketch writes alike) and mirrored
    // here, so an LLM or a buggy sketch can't push a joint past the range.
    // -------------------------------------------------------------------
    setLimits(min, max) {
        min = Math.max(0, Math.min(180, Math.round(min)));
        max = Math.max(0, Math.min(180, Math.round(max)));
        this.limitMin     = Math.min(min, max);
        this.limitMax     = Math.max(min, max);
        this.limitEnabled = true;
        if (this.isAttached) {
            this.arduino.send(encodeFrame(CMD_SERVO_SET_LIMITS, DEVICE_SERVO,
                [this.logicalId, this.limitMin, this.limitMax, 1]));
        }
        return this;
    }

    clearLimits() {
        this.limitEnabled = false;
        if (this.isAttached) {
            this.arduino.send(encodeFrame(CMD_SERVO_SET_LIMITS, DEVICE_SERVO,
                [this.logicalId, this.limitMin, this.limitMax, 0]));
        }
        return this;
    }

    // -------------------------------------------------------------------
    // Home — setHome() declares the home angle (no-arg: "here is home");
    // home() goes there, home(duration) goes there smoothly. Same pair as
    // the stepper and bus servo.
    //   arduino.pan.setHome(45);
    //   await arduino.pan.home(1000).whenDone();
    // -------------------------------------------------------------------
    setHome(angle) {
        this.homeAngle = Math.max(0, Math.min(180,
            Math.round(angle === undefined ? this.angle : angle)));
        return this;
    }

    home(duration) {
        return (duration > 0) ? this.writeTimed(this.homeAngle, duration)
                              : this.write(this.homeAngle);
    }

    // stop() — cancel an in-progress timed move, hold the current angle.
    // The board just halts interpolation (no 'done' frame), so settle any
    // whenDone() awaiter locally.
    stop() {
        this._sweepAbort = true;
        if (this.isAttached) this.arduino.send(encodeFrame(CMD_SERVO_STOP, DEVICE_SERVO, [this.logicalId]));
        this._resolveDone();
        return this;
    }

    // -------------------------------------------------------------------
    // read(interval?, threshold?)
    // read()             — return cached angle; no network traffic.
    // read(interval)     — board-side periodic poll (ms); 'change' fires
    //                      when the angle moved by threshold+ degrees.
    // read(interval, 2)  — only report changes of 2+ degrees.
    // read(END)          — stop this browser's periodic read.
    // The board runs the poll and gates per browser ;
    // threshold 0 = board default (1 degree). Calling again with the same
    // settings just returns the cached value.
    // -------------------------------------------------------------------
    read(interval, threshold) {
        if (interval === END) {
            this._stopRead();
            return this.angle;
        }
        if (this._readInterval > 0
            && (interval  === undefined || interval  === this._readInterval)
            && (threshold === undefined || threshold === this._readThreshold)) {
            return this.angle;
        }
        this._readInterval = interval ?? this.arduino.defaultInterval;
        if (threshold !== undefined) this._readThreshold = threshold;
        this._sendRead();
        return this.angle;
    }

    // setReadInterval(ms) / setReadThreshold(degrees) — set poll settings
    // directly; applied immediately if polling, stored for read() otherwise.
    setReadInterval(ms) {
        this._readInterval = ms;
        if (this.isAttached && ms > 0) this._sendRead();
        return this;
    }

    setReadThreshold(degrees) {
        this._readThreshold = degrees;
        if (this.isAttached && this._readInterval > 0) this._sendRead();
        return this;
    }

    // Register (or update) this browser's poll with the board.
    _sendRead() {
        this.arduino.send(encodeFrame(CMD_SERVO_READ, DEVICE_SERVO,
            [this.logicalId, this._readInterval,
             Math.max(0, Math.round(this._readThreshold))]));
    }

    _stopRead() {
        if (this._readInterval > 0) {
            this.arduino.send(encodeFrame(CMD_SERVO_READ, DEVICE_SERVO,
                [this.logicalId, END]));   // END = unregister
        }
        this._readInterval = 0;
    }

    // -------------------------------------------------------------------
    // attached() — ask the BOARD whether this servo is attached; resolves
    // true/false (false on timeout — dead link or unresponsive board).
    // Query → promise, like busServo.ping(); for the cached mirror, read
    // servo.isAttached.
    //
    //   if (await arduino.pan.attached()) { beginSequence(); }
    // -------------------------------------------------------------------
    attached(timeout = 2000) {
        this.arduino.send(encodeFrame(
            CMD_SERVO_ATTACHED, DEVICE_SERVO,
            [this.logicalId]
        ));
        return new Promise(resolve => {
            const entry = { resolve, timer: setTimeout(() => {
                const i = this._attachedResolvers.indexOf(entry);
                if (i >= 0) this._attachedResolvers.splice(i, 1);
                resolve(false);
            }, timeout) };
            this._attachedResolvers.push(entry);
        });
    }

    // Drain pending attached() promises with the board's answer.
    _resolveAttached(value) {
        this._attachedResolvers.splice(0).forEach(({ resolve, timer }) => {
            clearTimeout(timer);
            resolve(value);
        });
    }

    // -------------------------------------------------------------------
    // Convenience positions
    // -------------------------------------------------------------------
    center() { this._sweepAbort = true; return this.write(90); }
    min()    { this._sweepAbort = true; return this.write(0); }
    max()    { this._sweepAbort = true; return this.write(180); }

    // -------------------------------------------------------------------
    // sweep(startAngle, endAngle, duration, steps)
    // Smoothly move from startAngle to endAngle over duration ms.
    // Any call to write() / center() / min() / max() aborts the sweep.
    // -------------------------------------------------------------------
    async sweep(startAngle = 0, endAngle = 180, duration = 2000, steps = 50) {
        if (!this.isAttached) {
            this._warn('not attached');
            return;
        }

        this._sweepAbort = false;
        steps = Math.max(1, Math.round(steps));

        const stepDelay = duration / steps;
        const angleStep = (endAngle - startAngle) / steps;

        if (this._pendingWrite) {
            clearTimeout(this._pendingWrite);
            this._pendingWrite = null;
        }

        for (let i = 0; i <= steps; i++) {
            if (this._sweepAbort) break;
            this._sendAngle(Math.round(startAngle + angleStep * i));
            await new Promise(r => setTimeout(r, stepDelay));
        }
    }

    // -------------------------------------------------------------------
    // Callback shortcuts
    // -------------------------------------------------------------------
    onWrite(fn)    { return this.on('write',    fn); }
    onChange(fn)   { return this.on('change',   fn); }
    onDone(fn)     { return this.on('done',     fn); }

    // -------------------------------------------------------------------
    // Configuration
    // -------------------------------------------------------------------
    setWriteThrottle(ms) { this.writeThrottle = Math.max(0, ms); return this; }

    // Skip write() calls whose angle changes by less than `degrees` from the
    // last sent angle. Useful for animation loops that produce tiny deltas.
    // Set to 0 to disable. First write after attach is never filtered.
    setWriteThreshold(degrees) { this.writeThreshold = Math.max(0, degrees); return this; }

    // -------------------------------------------------------------------
    // Group member adapter — used by arduino.group(). Returns the frame(s)
    // to write `value` WITHOUT sending, so the group can batch every member
    // into one WebSocket message. Updates local state directly.
    // -------------------------------------------------------------------
    _memberWrite(angle) {
        if (!this.isAttached) { this._warn('not attached (group write)'); return []; }
        this._sweepAbort    = true;
        this._movePromise   = null;   // instant move — nothing to await
        this._moveDuration  = 0;
        angle               = this._clampAngle(angle);
        this.angle          = angle;
        this.micros         = this._angleToMicros(angle);
        this._lastSentAngle = angle;
        this._emit('write', { angle });
        return [encodeFrame(CMD_SERVO_WRITE, DEVICE_SERVO, [this.logicalId, angle])];
    }

    get memberValue() { return this.angle; }

    // -------------------------------------------------------------------
    // Group timed-move hook (used by group.writeTimed()). PWM servos have no
    // speed input, so arrive-together is done by on-board interpolation:
    // all servos in the bucket share one CMD_SERVO_SYNC_TIMED with the same
    // duration and interpolate from their own current angle → they finish
    // together. entries: [[member, targetAngle, current], ...] of one series.
    // -------------------------------------------------------------------
    _memberSyncKey() { return this.isAttached ? 'servo' : null; }

    _memberMoveEncode(entries, durationMs) {
        const bytes = new Uint8Array(entries.length * 2);
        entries.forEach(([m, target], i) => {
            const angle = m._clampAngle(target);
            bytes[i * 2]     = m.logicalId & 0xFF;
            bytes[i * 2 + 1] = angle & 0xFF;
            m.angle          = angle;         // update commanded state
            m.micros         = m._angleToMicros(angle);
            m._lastSentAngle = angle;
            m._sweepAbort    = true;
            m._armDone(durationMs);
            m._emit('write', { angle });
        });
        return [encodeFrame(CMD_SERVO_SYNC_TIMED, DEVICE_SERVO,
            [Math.max(0, Math.round(durationMs))], bytes)];
    }

    // -------------------------------------------------------------------
    // State snapshot
    // -------------------------------------------------------------------
    getState() {
        return {
            logicalId:  this.logicalId,
            pin:        this.pin,
            attached:   this.isAttached,
            angle:      this.angle,
            micros:     this.micros,
            minPulse:   this.minPulse,
            maxPulse:   this.maxPulse,
            limits:     this.limitEnabled ? { min: this.limitMin, max: this.limitMax } : null,
            home:       this.homeAngle,
            throttle:   this.writeThrottle,
            threshold:  this.writeThreshold,
        };
    }

    // -------------------------------------------------------------------
    // Incoming frames from Arduino.
    // CMD_SERVO_ATTACH and CMD_SERVO_WRITE arrive during announce (state
    // sync) — they update local state silently with no event emission.
    // CMD_SERVO_READ and CMD_SERVO_ATTACHED are poll responses — they
    // update state and emit events as normal.
    // -------------------------------------------------------------------
    handleMessage(frame) {
        switch (frame.cmd) {

            case CMD_SERVO_ATTACH:
                // Sync attach state from Arduino announce. The flag tells
                // _reRegister() to skip its replay — Arduino already knows.
                this.pin                 = frame.params[1];
                this.minPulse            = frame.params[2] ?? 544;
                this.maxPulse            = frame.params[3] ?? 2400;
                this.isAttached          = true;
                this._announcedByArduino = true;
                break;

            case CMD_SERVO_WRITE:
                // Sync last known angle from Arduino announce
                this.angle  = frame.params[1];
                this.micros = this._angleToMicros(this.angle);
                break;

            case CMD_SERVO_SET_LIMITS:
                // Sync soft-limit state from Arduino announce — silent.
                this.limitMin     = frame.params[1];
                this.limitMax     = frame.params[2];
                this.limitEnabled = frame.params[3] === 1;
                break;

            case CMD_SERVO_READ:
                this.angle  = frame.params[1];
                this.micros = this._angleToMicros(this.angle);
                this._emit('change', { angle: this.angle });
                break;

            case CMD_SERVO_ATTACHED:
                this.isAttached = frame.params[1] === 1;
                this._resolveAttached(this.isAttached);
                break;

            case CMD_SERVO_DONE:
                this.angle  = frame.params[1];
                this.micros = this._angleToMicros(this.angle);
                this._emit('done', { angle: this.angle });
                this._resolveDone();
                break;
        }
    }

    // Resolves when the servo's timed move completes (CMD_SERVO_DONE).
    _whenDone() { return new Promise(resolve => this._doneResolvers.push(resolve)); }
    _resolveDone() {
        const resolvers = this._doneResolvers;
        this._doneResolvers = [];
        resolvers.forEach(r => r(this.angle));
    }

    // Arm the whenDone() promise for a move that will emit 'done'.
    _armDone(durationMs = 0) {
        this._moveDuration = Math.max(0, durationMs);
        this._movePromise  = this._whenDone();
    }

    // whenDone({ timeout }?) — Promise for the most recent move. Resolves
    // `true` on the servo's 'done' (or immediately if no move is pending /
    // it already finished), `false` on the safety timeout. timeout: ms
    // (default max(duration × 2, 10000); 0 = wait forever). Also accepts a
    // bare number: whenDone(5000).
    //
    //   await servo.writeTimed(90, 1000).whenDone();
    whenDone(opts = {}) {
        const t = (typeof opts === 'number') ? opts : opts.timeout;
        const timeout = t ?? Math.max(this._moveDuration * 2, 10000);
        if (!this._movePromise) return Promise.resolve(true);
        const done = this._movePromise.then(() => true);
        if (!timeout) return done;
        return Promise.race([
            done,
            new Promise(res => setTimeout(() => res(false), timeout)),
        ]);
    }

    // -------------------------------------------------------------------
    // Internal helpers
    // -------------------------------------------------------------------
    _angleToMicros(angle) {
        return this.minPulse + (angle / 180) * (this.maxPulse - this.minPulse);
    }

    _microsToAngle(us) {
        return ((us - this.minPulse) / (this.maxPulse - this.minPulse)) * 180;
    }
}

// Let the core materialise a Servo when the SKETCH creates one
// (PardaloteServo.attach("pan", 9) → CMD_SHARE → arduino.pan).
registerExtensionType(Servo);

// ----- pardalote-bus-servo.js --------------------------------
// ==============================================================
// busServo.js
// Pardalote Serial Bus Servo Extension
// Part of Pardalote — version in package.json
// by Scott Mitchell
// GPL-3.0-or-later License
//
// Serial-bus smart servos on a shared half-duplex UART:
//   - Feetech ST / SMS series (0–4095 counts) — e.g. STS3215, the servo in
//     the LeRobot SO-100/SO-101 arms.
//   - Feetech SC / SCS series (0–1023 counts) — e.g. SCS15.
//
// Unlike PWM servos, every bus servo shares one UART, so the inside/outside
// boundary is per-BUS, not per-servo: a serial bus is either a Pardalote bus
// (every servo on it is Pardalote hardware) or it isn't (private, driven by
// the sketch on a separate UART — Pardalote never touches it). A servo's
// hardware ID (1–253) is its ADDRESS ON THE BUS, passed to attach(); after
// that you drive it through this instance (arduino.<name>), never by raw id.
// Positions are RAW ENCODER COUNTS, not degrees.
//
// Usage:
//   const arduino = new Arduino();
//   arduino.add('shoulder', new BusServo());
//   arduino.add('elbow',    new BusServo());
//   arduino.connect('192.168.1.42');
//
//   arduino.on('ready', () => {
//       arduino.shoulder.attach(1);      // bus id 1 (ST series by default)
//       arduino.elbow.attach(2);
//       arduino.shoulder.center();       // → 2048
//       arduino.elbow.write(3000);       // raw counts
//   });
// ==============================================================

const DEVICE_BUSSERVO = 206;

const CMD_BUSSERVO_BUS_CONFIG  = 0x41;
const CMD_BUSSERVO_ATTACH      = 0x42;
const CMD_BUSSERVO_DETACH      = 0x43;
const CMD_BUSSERVO_WRITE       = 0x44;
const CMD_BUSSERVO_WRITE_SPEED = 0x45;
const CMD_BUSSERVO_SET_MODE    = 0x46;
const CMD_BUSSERVO_TORQUE      = 0x47;
const CMD_BUSSERVO_READ        = 0x48;
const CMD_BUSSERVO_SET_LIMITS  = 0x49;
const CMD_BUSSERVO_CALIBRATE   = 0x4A;
const CMD_BUSSERVO_SET_ID      = 0x4B;
const CMD_BUSSERVO_PING        = 0x4C;
const CMD_BUSSERVO_SCAN        = 0x4D;
const CMD_BUSSERVO_SYNC_WRITE  = 0x4E;
const CMD_BUSSERVO_DONE        = 0x51;
const CMD_BUSSERVO_READ_LIMITS = 0x62;  // read the servo's EEPROM angle-limit registers (firmware limits).
const CMD_BUSSERVO_PRESENT     = 0x63;  // Ar→JS: did the servo answer the attach-time ping?
const CMD_BUSSERVO_GESTURE     = 0x5A;  // global: payload = bus-servo channel blocks (segment schedules).
                                        // See pardalote.js CURVE_IDS / GESTURE_FLAG_* and defs.h.

// Board-side cap (PardaloteBusServo.h MAX_BUS_SERVO_SEGMENTS) — mirrored so
// JS can warn instead of silently overrunning. Extra segments are dropped.
const MAX_BUS_SERVO_SEGMENTS = 12;

const BUSSERVO_SERIES_ST = 0;   // 0–4095
const BUSSERVO_SERIES_SC = 1;   // 0–1023

const BUSSERVO_MODE_POSITION = 0;
const BUSSERVO_MODE_WHEEL    = 1;

class BusServo extends Extension {
    static deviceId = DEVICE_BUSSERVO;

    constructor() {
        super();

        // Binding
        this.servoId    = 0;
        this.series     = BUSSERVO_SERIES_ST;
        this.isAttached = false;

        // Position model — raw counts. ST: 0–4095, SC: 0–1023.
        this.resolution  = 4096;   // counts over the full range
        this.spanDegrees = 360;    // nominal angular span for degree helpers

        // Runtime state
        this.mode        = BUSSERVO_MODE_POSITION;
        this.torqueOn    = true;

        // Default move speed/acc used by group set() and sync-write.
        this.defaultSpeed = 2400;
        this.defaultAcc   = 50;
        this.maxMoveSpeed = 4095;   // speed cap used by group.moveTo() matching

        // Commanded destination (set by write; position is feedback)
        this.target      = 0;
        // Whether `target` is a LIVE goal. A position write/gesture sets it;
        // releasing torque (free mode) or entering wheel mode clears it — a
        // freed servo isn't holding a target. `target` keeps its last number
        // for reference; `hasTarget` says whether it currently means anything.
        this.hasTarget   = false;

        // Feedback (from read polls)
        this.position    = 0;
        this.velocity    = 0;
        this.load        = 0;
        this.voltage     = 0;      // volts
        this.temperature = 0;      // °C
        this.current     = 0;      // raw units (ST only)

        // Soft limits (mirrored into the servo's own registers)
        this.limitMin     = 0;
        this.limitMax     = 0;
        this.limitEnabled = false;

        // The servo's OWN firmware angle limits (read from EEPROM by the board
        // at attach, replayed on reconnect). null = not yet read / servo didn't
        // answer. { min, max, enabled } otherwise — enabled is false when the
        // servo reports min==max==0 (Feetech's "limits off / multi-turn").
        // Read-only mirror of the servo; distinct from the soft limits above.
        this.firmwareLimits = null;

        // Is the servo answering? true = found, false = no response (check
        // wiring / ID / baud), null = not yet attached / unknown. Seeded by the
        // board's attach-time ping (CMD_BUSSERVO_PRESENT), then kept LIVE from
        // read() feedback (position -1 = no answer) — so a servo powered up or
        // unplugged mid-session flips it. Fires the 'presence' event on change.
        this.present = null;

        // Periodic read registration (board-side).
        // _readThreshold is in counts; 0 = board default (2 counts).
        // Survives _reset() — it's user-tuned configuration.
        this._readInterval  = 0;
        this._readThreshold = 0;

        // Pending scan()/ping()/done/firmware-limit promise resolvers
        this._scanResolvers = [];
        this._pingResolvers = [];
        this._doneResolvers = [];
        this._fwLimitResolvers = [];

        // Home position (counts) — where home() goes; null = centre of range.
        this.homePosition = null;

        // Promise for the most recent move, consumed by whenDone(). Armed by
        // every position write (the board polls the Moving flag and emits
        // 'done' when it settles); cleared by runSpeed (wheel mode — no
        // arrival). _moveDuration feeds the default timeout.
        this._movePromise  = null;
        this._moveDuration = 0;

        this._announcedByArduino = false;
    }

    // -------------------------------------------------------------------
    // Board switch / reconnection
    // -------------------------------------------------------------------
    _reset() {
        this._readInterval = 0;  // registration died with the old board — send nothing
        this._drain(this._scanResolvers, []);
        this._drain(this._pingResolvers, null);
        this._drain(this._doneResolvers, this.position);
        this._drain(this._fwLimitResolvers, null);
        this.firmwareLimits = null;   // announce() replays it fresh from the board
        this.present = null;          // announce() replays presence too
        this._movePromise  = null;
        this._moveDuration = 0;
        this.homePosition  = null;
        this.servoId     = 0;
        this.isAttached  = false;
        this.mode        = BUSSERVO_MODE_POSITION;
        this.torqueOn    = true;
        this.target      = 0;
        this.hasTarget   = false;
        this.limitEnabled = false;
        this._announcedByArduino = false;
    }

    _reRegister() {
        if (this.isAttached && !this._announcedByArduino) {
            this._sendAttach();
            this._raw(CMD_BUSSERVO_SET_MODE, [this.logicalId, this.mode]);
            this._raw(CMD_BUSSERVO_TORQUE,   [this.logicalId, this.torqueOn ? 1 : 0]);
            if (this.limitEnabled) {
                this._raw(CMD_BUSSERVO_SET_LIMITS, [this.logicalId, this.limitMin, this.limitMax, 1]);
            }
        }
        // Periodic read registrations are per-WS-client on the Arduino
        // (cleared on disconnect), so always re-register if active.
        if (this.isAttached && this._readInterval > 0) this._sendRead();
        this._announcedByArduino = false;
    }

    // -------------------------------------------------------------------
    // configureBus({ serial, baud, rxPin, txPin }) — one-time bus setup.
    // Affects ALL bus servos (they share the UART). Optional: defaults to
    // Serial1 at 1 Mbps, begun lazily on first attach.
    //   serial : 1 or 2 (ESP32 only for 2)
    //   rxPin/txPin : ESP32 only; -1 = board default
    // -------------------------------------------------------------------
    configureBus({ serial = 1, baud = 1000000, rxPin = -1, txPin = -1 } = {}) {
        this._raw(CMD_BUSSERVO_BUS_CONFIG, [serial, baud, rxPin, txPin]);
        return this;
    }

    // -------------------------------------------------------------------
    // attach(servoId, series?)   series: 'ST' (default) or 'SC'
    // -------------------------------------------------------------------
    attach(servoId, series = 'ST') {
        this.servoId = servoId;
        this.series  = (String(series).toUpperCase() === 'SC')
            ? BUSSERVO_SERIES_SC : BUSSERVO_SERIES_ST;
        this.resolution  = (this.series === BUSSERVO_SERIES_SC) ? 1024 : 4096;
        this.spanDegrees = (this.series === BUSSERVO_SERIES_SC) ? 300 : 360;
        this.maxMoveSpeed = (this.series === BUSSERVO_SERIES_SC) ? 1023 : 4095;
        this.isAttached  = true;
        this._sendAttach();
        return this;
    }

    _sendAttach() {
        this.arduino.send(encodeFrame(CMD_BUSSERVO_ATTACH, DEVICE_BUSSERVO,
            [this.logicalId, this.servoId, this.series]));
    }

    detach() {
        this._stopRead();
        this._raw(CMD_BUSSERVO_DETACH, [this.logicalId]);
        this.isAttached = false;
        return this;
    }

    // -------------------------------------------------------------------
    // Position moves (position mode). Raw counts. Chainable.
    // write(counts, { speed, acc })
    // -------------------------------------------------------------------
    write(position, { speed = 2400, acc = 50 } = {}) {
        if (!this._requireAttached('write')) return this;
        this._armDone();          // the board polls Moving and emits 'done'
        position = this._clampPos(Math.round(position));
        this.target = position;                     // commanded goal; position is feedback
        this.hasTarget = true;                      // now a live goal (until freed)
        this.arduino.send(encodeFrame(CMD_BUSSERVO_WRITE, DEVICE_BUSSERVO,
            [this.logicalId, position, speed, acc]));
        this._emit('write', { position });
        return this;
    }

    // Go to the centre of range (2048 for ST, 512 for SC).
    center(opts) { return this.write(Math.round(this.resolution / 2), opts); }

    // Degree helpers — accurate for ST (4096/360°); nominal for SC.
    writeDegrees(deg, opts) {
        return this.write(deg / this.spanDegrees * this.resolution, opts);
    }
    get positionDegrees() {
        return this.position / this.resolution * this.spanDegrees;
    }

    // -------------------------------------------------------------------
    // writeTimed(position, duration) — reach `position` in about `duration`
    // ms. The servo does its own motion, so we pick the speed from the move
    // distance (measured from the last-read position). This is what group
    // moveTo() does per member; here it's exposed for a single servo.
    // -------------------------------------------------------------------
    writeTimed(position, duration = 1000) {
        if (!this._requireAttached('writeTimed')) return this;
        position = this._clampPos(Math.round(position));   // clamp BEFORE sizing the speed
        const distance = Math.abs(position - this.position);   // last-read position
        const speed = Math.min(this.maxMoveSpeed,
                               Math.max(1, Math.round(distance / Math.max(0.001, duration / 1000))));
        this.write(position, { speed });             // arms whenDone()
        this._moveDuration = Math.max(0, duration);  // better default timeout
        return this;
    }

    // -------------------------------------------------------------------
    // gesture(segments, opts?) — play an authored SEGMENT SCHEDULE on-board.
    //
    // The bus-servo counterpart of servo.gesture() / stepper.gesture(). A bus
    // servo runs its OWN motion, so — unlike the PWM servo — the per-segment
    // `curve` is NOT rendered inside a segment: each segment is one position
    // write at a distance/duration-matched speed, and the board advances to
    // the next when the servo's Moving flag settles (real arrival feedback,
    // not a timer). Expression comes from decomposing the move into segments
    // (and, in a group, lane overlap). Values are in servo COUNTS. Each
    // segment is { dur, curve?, and either `by` (relative) or `to` (absolute) }:
    //
    //   grip.gesture([                       // reach out, ease back, small settle
    //       { by:  600, dur: 400 },
    //       { by: -600, dur: 600 },
    //       { by:   80, dur: 200 },
    //   ]);
    //   await grip.gesture([...]).whenDone();
    //
    // Relative by default (the board captures live start position, then chains
    // from each target); `to`/opts.absolute for absolute targets (soft limits
    // clamp the ends). The authored `dur` sizes each segment's speed; if that
    // exceeds the servo's max the segment simply takes longer and the next
    // still fires on true arrival. Fires one 'done' after the last segment.
    // -------------------------------------------------------------------
    gesture(segments, opts = {}) {
        const blk = this._gestureBlock(segments, opts);
        if (!blk) return this;
        this.arduino.send(encodeFrame(CMD_BUSSERVO_GESTURE, DEVICE_BUSSERVO, [], blk.bytes));
        return this;
    }

    // Encode ONE gesture channel block — shared by gesture() (wrap + send) and
    // the group adapter _memberGestureEncode() (batched, no send). Arms
    // whenDone(), mirrors the commanded target, emits 'write'. Returns
    // { bytes, total } or null when there's nothing to play.
    _gestureBlock(segments, opts = {}) {
        if (!this._requireAttached('gesture')) return null;
        if (!Array.isArray(segments) || segments.length === 0) {
            this._warn('gesture: needs a non-empty array of segments');
            return null;
        }

        const usesTo = segments.some(s => s.to !== undefined);
        const usesBy = segments.some(s => s.by !== undefined || s.value !== undefined);
        const absolute = (opts.absolute !== undefined) ? !!opts.absolute : usesTo;
        if (usesTo && usesBy)
            this._warn(`gesture: mixes 'to' (absolute) and 'by' (relative) — treating whole gesture as ${absolute ? 'absolute' : 'relative'}`);

        if (segments.length > MAX_BUS_SERVO_SEGMENTS)
            this._warn(`gesture: ${segments.length} segments exceeds board max ${MAX_BUS_SERVO_SEGMENTS} — extra segments dropped`);
        const count = Math.min(segments.length, MAX_BUS_SERVO_SEGMENTS);

        const flags = absolute ? GESTURE_FLAG_ABSOLUTE : 0;

        // Encode: [logicalId u8, flags u8, count u8] + count × {curve u8, dur u16, value i32}.
        const bytes = new Uint8Array(3 + count * 7);
        const dv    = new DataView(bytes.buffer);
        dv.setUint8(0, this.logicalId & 0xFF);
        dv.setUint8(1, flags & 0xFF);
        dv.setUint8(2, count & 0xFF);
        let total = 0, rest = this.position;   // predicted end (board uses its live read)
        for (let i = 0; i < count; i++) {
            const s   = segments[i];
            const off = 3 + i * 7;
            const dur = Math.max(1, Math.round(s.dur ?? 0));
            const val = absolute ? this._clampPos(Math.round(s.to ?? rest))
                                 : Math.round(s.by ?? s.value ?? 0);
            dv.setUint8(off, curveId(s.curve));
            dv.setUint16(off + 1, dur & 0xFFFF, false);
            dv.setInt32(off + 3, val, false);
            total += dur;
            rest = absolute ? this._clampPos(Math.round(s.to ?? rest))
                            : this._clampPos(rest + Math.round(s.by ?? s.value ?? 0));
        }

        this._armDone(total);
        this.target = rest;   // mirror commanded target; read polls refine position
        this.hasTarget = true;
        this._emit('write', { position: rest });
        return { bytes, total };
    }

    // Group adapter (group.gesture()). entries: [[member, segments], ...], all
    // BusServos → one CMD_BUSSERVO_GESTURE frame carrying every member's channel
    // block; the board sequences each locally. Returns frame(s) WITHOUT sending,
    // so the group batches all types into one message.
    _memberGestureEncode(entries) {
        const blocks = [];
        for (const [m, segs] of entries) { const b = m._gestureBlock(segs); if (b) blocks.push(b.bytes); }
        if (!blocks.length) return [];
        const payload = new Uint8Array(blocks.reduce((n, b) => n + b.length, 0));
        let off = 0;
        for (const b of blocks) { payload.set(b, off); off += b.length; }
        return [encodeFrame(CMD_BUSSERVO_GESTURE, DEVICE_BUSSERVO, [], payload)];
    }

    // stop() — halt motion: hold the last-read position (or zero speed in
    // wheel mode). Matches servo.stop() / stepper.stop().
    stop() {
        if (!this._requireAttached('stop')) return this;
        if (this.mode === BUSSERVO_MODE_WHEEL) this.runSpeed(0);
        else this.write(this.position);
        return this;
    }

    // -------------------------------------------------------------------
    // Continuous rotation (wheel mode). Sign of speed sets direction.
    // Call setMode('wheel') first, or just call runSpeed — the servo is
    // put in wheel mode on the board when it receives a speed command.
    // Named to match stepper.runSpeed() (the Feetech lib calls it WriteSpe).
    // -------------------------------------------------------------------
    runSpeed(speed, { acc = 50 } = {}) {
        if (!this._requireAttached('runSpeed')) return this;
        this._movePromise  = null;   // continuous — never "arrives"
        this._moveDuration = 0;
        this.hasTarget     = false;  // wheel mode has no position goal
        if (this.mode !== BUSSERVO_MODE_WHEEL) this.setMode('wheel');
        this.arduino.send(encodeFrame(CMD_BUSSERVO_WRITE_SPEED, DEVICE_BUSSERVO,
            [this.logicalId, Math.round(speed), acc]));
        return this;
    }

    setMode(mode) {
        const m = (String(mode).toLowerCase() === 'wheel')
            ? BUSSERVO_MODE_WHEEL : BUSSERVO_MODE_POSITION;
        this.mode = m;
        if (this.isAttached) this._raw(CMD_BUSSERVO_SET_MODE, [this.logicalId, m]);
        return this;
    }

    // -------------------------------------------------------------------
    // Torque — disable to hand-pose a joint then read it back (teaching by
    // demonstration), enable to hold position.
    // -------------------------------------------------------------------
    torque(on)      { this.torqueOn = !!on;
                      if (!this.torqueOn) this.hasTarget = false;   // freed → no live target
                      if (this.isAttached) this._raw(CMD_BUSSERVO_TORQUE, [this.logicalId, on ? 1 : 0]);
                      return this; }
    enableTorque()  { return this.torque(true); }
    disableTorque() { return this.torque(false); }

    // -------------------------------------------------------------------
    // read(interval?, threshold?) — poll present state.
    // read()             — return cached position; no network traffic.
    // read(interval)     — board-side periodic poll (ms): ONE bus
    //                      transaction per tick regardless of how many
    //                      browsers are connected; 'change' fires when the
    //                      position moved by threshold+ counts.
    // read(interval, 10) — only report changes of 10+ counts.
    // read(END)          — stop this browser's periodic read.
    // The board runs the poll and gates per browser ;
    // threshold 0 = board default (2 counts — encoder noise floor).
    // Calling again with the same settings just returns the cached value.
    // -------------------------------------------------------------------
    read(interval, threshold) {
        if (!this.isAttached) { this._warn('not attached'); return this.position; }
        if (interval === END) { this._stopRead(); return this.position; }
        if (this._readInterval > 0
            && (interval  === undefined || interval  === this._readInterval)
            && (threshold === undefined || threshold === this._readThreshold)) {
            return this.position;
        }
        this._readInterval = interval ?? this.arduino.defaultInterval;
        if (threshold !== undefined) this._readThreshold = threshold;
        this._sendRead();
        return this.position;
    }

    // setReadInterval(ms) / setReadThreshold(counts) — set poll settings
    // directly; applied immediately if polling, stored for read() otherwise.
    setReadInterval(ms) {
        this._readInterval = ms;
        if (this.isAttached && ms > 0) this._sendRead();
        return this;
    }

    setReadThreshold(counts) {
        this._readThreshold = counts;
        if (this.isAttached && this._readInterval > 0) this._sendRead();
        return this;
    }

    // Register (or update) this browser's poll with the board.
    _sendRead() {
        this._raw(CMD_BUSSERVO_READ, [this.logicalId, this._readInterval,
            Math.max(0, Math.round(this._readThreshold))]);
    }

    _stopRead() {
        if (this._readInterval > 0) this._raw(CMD_BUSSERVO_READ, [this.logicalId, END]);
        this._readInterval = 0;
    }

    // -------------------------------------------------------------------
    // Soft limits (safety) — same shape as stepper/servo setLimits().
    // Clamped in board RAM on every write path (browser, sketch, group
    // SyncWrite) and mirrored here. Deliberately software-only: does NOT
    // write the servo's EEPROM limit registers (no wear, no unverified
    // unLockEprom path). Limits therefore live on the board, not in the
    // servo — the board re-applies them; a bare servo on another bus won't.
    // -------------------------------------------------------------------
    setLimits(min, max) {
        min = Math.round(min);
        max = Math.round(max);
        this.limitMin = Math.min(min, max);
        this.limitMax = Math.max(min, max);
        this.limitEnabled = true;
        if (this.isAttached) this._raw(CMD_BUSSERVO_SET_LIMITS, [this.logicalId, this.limitMin, this.limitMax, 1]);
        return this;
    }

    clearLimits() {
        this.limitEnabled = false;
        if (this.isAttached) this._raw(CMD_BUSSERVO_SET_LIMITS, [this.logicalId, this.limitMin, this.limitMax, 0]);
        return this;
    }

    // -------------------------------------------------------------------
    // readFirmwareLimits() — force a fresh read of the servo's OWN EEPROM
    // angle-limit registers on the board, and resolve with the result. Also
    // updates the cached `firmwareLimits` property (the board reads these once
    // at attach, so `firmwareLimits` is usually already populated — call this
    // only to re-read after changing them on the servo).
    //
    // Resolves { min, max, enabled } (counts), or null if the servo didn't
    // answer. enabled is false when min==max==0 (Feetech "limits off").
    //   const fw = await arduino.shoulder.readFirmwareLimits();
    // Read the cached value directly (no round-trip) with .firmwareLimits.
    // -------------------------------------------------------------------
    readFirmwareLimits() {
        if (!this._requireAttached('readFirmwareLimits')) return Promise.resolve(null);
        this._raw(CMD_BUSSERVO_READ_LIMITS, [this.logicalId]);
        return new Promise(resolve => this._fwLimitResolvers.push(resolve));
    }

    // Mirror the board's clamp so cached target matches what it applied:
    // physical range always (keeps the needle/timing honest and stops an
    // out-of-range count wrapping mod-resolution), soft limits when set.
    _clampPos(pos) {
        pos = Math.max(0, Math.min(this.resolution - 1, pos));
        if (this.limitEnabled) pos = Math.max(this.limitMin, Math.min(this.limitMax, pos));
        return pos;
    }

    // -------------------------------------------------------------------
    // Home — setHome() declares the home position (no-arg: "here is home",
    // from the last-read position — hand-pose with torque off, read(), then
    // setHome()); home() goes there, home(duration) goes there smoothly.
    // Default home is the centre of range (2048 ST / 512 SC).
    //   arduino.shoulder.setHome(1500);
    //   await arduino.shoulder.home(1000).whenDone();
    // -------------------------------------------------------------------
    setHome(position) {
        this.homePosition = Math.round(position === undefined ? this.position : position);
        return this;
    }

    home(duration) {
        const target = this.homePosition ?? Math.round(this.resolution / 2);
        return (duration > 0) ? this.writeTimed(target, duration)
                              : this.write(target);
    }

    // -------------------------------------------------------------------
    // calibrate() — declare the current physical position as centre.
    // Move the joint to its zero pose by hand (torque off), then call this.
    // -------------------------------------------------------------------
    calibrate() {
        if (this.isAttached) this._raw(CMD_BUSSERVO_CALIBRATE, [this.logicalId]);
        return this;
    }

    // -------------------------------------------------------------------
    // setId(newId) — renumber this servo. ONLY with a single servo on the
    // bus, or every servo will take the new ID. Used during initial setup.
    // -------------------------------------------------------------------
    setId(newServoId) {
        if (this.isAttached) {
            this._raw(CMD_BUSSERVO_SET_ID, [this.logicalId, newServoId]);
            this.servoId = newServoId;
        }
        return this;
    }

    // -------------------------------------------------------------------
    // ping(servoId?) — resolves true/false. Defaults to this servo's ID.
    // scan(first?, last?) — resolves an array of responding servo IDs.
    // -------------------------------------------------------------------
    ping(servoId = this.servoId) {
        this._raw(CMD_BUSSERVO_PING, [this.logicalId, servoId]);
        return new Promise(resolve => this._pingResolvers.push(resolve));
    }

    scan(first = 1, last = 20) {
        this._raw(CMD_BUSSERVO_SCAN, [first, last]);
        return new Promise(resolve => this._scanResolvers.push(resolve));
    }

    // -------------------------------------------------------------------
    // Callback shortcuts
    // -------------------------------------------------------------------
    onChange(fn) { return this.on('change', fn); }
    onWrite(fn) { return this.on('write', fn); }
    onDone(fn)  { return this.on('done',  fn); }
    onPresence(fn) { return this.on('presence', fn); }

    // Resolves when the board reports the servo settled (CMD_BUSSERVO_DONE).
    _whenDone() { return new Promise(resolve => this._doneResolvers.push(resolve)); }

    // Arm the whenDone() promise for a move that will emit 'done'.
    _armDone(durationMs = 0) {
        this._moveDuration = Math.max(0, durationMs);
        this._movePromise  = this._whenDone();
    }

    // whenDone({ timeout }?) — Promise for the most recent move. Resolves
    // `true` on CMD_BUSSERVO_DONE (the servo's own Moving flag settled — real
    // arrival, not a timer; or immediately if no move is pending / it already
    // finished), `false` on the safety timeout. timeout: ms (default
    // max(duration × 2, 10000); 0 = wait forever). Also accepts a bare
    // number: whenDone(5000).
    //
    //   await arduino.j1.writeTimed(2048, 1500).whenDone();
    whenDone(opts = {}) {
        const t = (typeof opts === 'number') ? opts : opts.timeout;
        const timeout = t ?? Math.max(this._moveDuration * 2, 10000);
        if (!this._movePromise) return Promise.resolve(true);
        const done = this._movePromise.then(() => true);
        if (!timeout) return done;
        return Promise.race([
            done,
            new Promise(res => setTimeout(() => res(false), timeout)),
        ]);
    }

    // -------------------------------------------------------------------
    // Incoming frames from Arduino.
    // -------------------------------------------------------------------
    handleMessage(frame) {
        switch (frame.cmd) {

            // ---- announce / state sync (silent) ----
            case CMD_BUSSERVO_ATTACH:
                this.servoId    = frame.params[1];
                this.series     = frame.params[2] ?? BUSSERVO_SERIES_ST;
                this.resolution  = (this.series === BUSSERVO_SERIES_SC) ? 1024 : 4096;
                this.spanDegrees = (this.series === BUSSERVO_SERIES_SC) ? 300 : 360;
                this.maxMoveSpeed = (this.series === BUSSERVO_SERIES_SC) ? 1023 : 4095;
                this.isAttached          = true;
                this._announcedByArduino = true;
                break;

            case CMD_BUSSERVO_BUS_CONFIG: /* global echo — nothing per-instance */ break;
            case CMD_BUSSERVO_SET_MODE:   this.mode     = frame.params[1]; break;
            case CMD_BUSSERVO_TORQUE:
                this.torqueOn = frame.params[1] === 1;
                if (!this.torqueOn) this.hasTarget = false;   // freed elsewhere → drop the target
                break;

            case CMD_BUSSERVO_SET_LIMITS:
                this.limitMin = frame.params[1];
                this.limitMax = frame.params[2];
                this.limitEnabled = (frame.params[3] ?? 1) === 1;
                break;

            case CMD_BUSSERVO_WRITE:
                // Echoed from a sketch-issued write — mirror the commanded goal.
                this.target = frame.params[1];
                this.hasTarget = true;
                break;

            case CMD_BUSSERVO_READ_LIMITS: {
                // The servo's own firmware angle limits: [id, min, max] raw
                // counts (-1 = servo didn't answer). min==max==0 = disabled.
                const min = frame.params[1], max = frame.params[2];
                this.firmwareLimits = (min < 0 || max < 0)
                    ? null
                    : { min, max, enabled: !(min === 0 && max === 0) };
                this._emit('fwlimits', this.firmwareLimits);
                this._drain(this._fwLimitResolvers, this.firmwareLimits);
                break;
            }

            case CMD_BUSSERVO_PRESENT: {
                // Did the servo answer the attach-time ping? [id, servoId, present]
                const p = frame.params[2];
                this.present = (p === 1) ? true : (p === 0) ? false : null;
                this._emit('presence', { servoId: frame.params[1], present: this.present });
                break;
            }

            case CMD_BUSSERVO_DONE:
                // Board polled the Moving flag and the servo has settled.
                this.position = frame.params[1];
                this._emit('done', { position: this.position });
                this._drain(this._doneResolvers, this.position);
                break;

            // ---- live updates ----
            case CMD_BUSSERVO_READ: {
                this.position    = frame.params[1];
                this.velocity    = frame.params[2];
                this.load        = frame.params[3];
                this.voltage     = frame.params[4] / 10;   // decivolts → volts
                this.temperature = frame.params[5];
                this.current     = frame.params[6];
                // Live presence: a valid read means the servo answered; the
                // board sends position -1 when it doesn't. This keeps `present`
                // current between attaches — a servo powered up (or unplugged)
                // mid-session flips it and fires 'presence'. (Positions are
                // 0..resolution-1, so -1 is an unambiguous "no answer".)
                const answering = this.position !== -1;
                if (answering !== this.present) {
                    this.present = answering;
                    this._emit('presence', { servoId: this.servoId, present: this.present });
                }
                this._emit('change', {
                    position: this.position, velocity: this.velocity, load: this.load,
                    voltage: this.voltage, temperature: this.temperature, current: this.current,
                });
                break;
            }

            case CMD_BUSSERVO_PING:
                this._drain(this._pingResolvers, frame.params[2] === 1);
                this._emit('ping', { servoId: frame.params[1], found: frame.params[2] === 1 });
                break;

            case CMD_BUSSERVO_SCAN: {
                const count = frame.params[1];
                const ids = [];
                for (let i = 0; i < count; i++) ids.push(frame.params[2 + i]);
                this._drain(this._scanResolvers, ids);
                this._emit('scan', { ids });
                break;
            }
        }
    }

    // -------------------------------------------------------------------
    // Group member adapter — see arduino.group(). Returns frame(s) WITHOUT
    // sending, so the group can batch all members into one message. Uses
    // default move speed/acc; memberValue reports the last-read position.
    // -------------------------------------------------------------------
    _memberWrite(position) {
        if (!this._requireAttached('group write')) return [];
        this._armDone();
        position = this._clampPos(Math.round(position));
        this.target = position;               // mirror individual write()
        this.hasTarget = true;
        this._emit('write', { position });
        return [encodeFrame(CMD_BUSSERVO_WRITE, DEVICE_BUSSERVO,
            [this.logicalId, position, this.defaultSpeed, this.defaultAcc])];
    }

    get memberValue() { return this.position; }

    // Set the default move speed/acc used by group set() and sync-write.
    setMoveDefaults(speed, acc) {
        if (speed !== undefined) this.defaultSpeed = Math.max(0, Math.round(speed));
        if (acc   !== undefined) this.defaultAcc   = Math.max(0, Math.round(acc));
        return this;
    }

    // -------------------------------------------------------------------
    // Hardware sync-write hooks (used by group.write()). Members sharing a
    // sync key are coalesced into one Feetech SyncWrite packet, so they
    // latch their goals simultaneously — tighter than one-message batching.
    // Only bus servos of the SAME series can share a packet.
    // -------------------------------------------------------------------
    _memberSyncKey() { return this.isAttached ? `busservo:${this.series}` : null; }

    // Immediate coordinated write (group.write()). entries: [[member, position, speed?], ...]
    // — one SyncWrite packet; speed defaults to each member's defaultSpeed.
    _memberSetEncode(entries) {
        const bytes = new Uint8Array(entries.length * 6);
        const dv = new DataView(bytes.buffer);
        entries.forEach(([m, v, speed], i) => {
            const pos = m._clampPos(Math.max(0, Math.round(v)));
            const spd = Math.max(0, Math.round(speed !== undefined ? speed : m.defaultSpeed)) & 0xFFFF;
            const off = i * 6;
            dv.setUint8 (off,     m.servoId & 0xFF);
            dv.setInt16 (off + 1, pos, false);
            dv.setUint16(off + 3, spd, false);
            dv.setUint8 (off + 5, m.defaultAcc & 0xFF);
            m.target = pos;                   // mirror individual write()
            m.hasTarget = true;
            m._armDone();
            m._emit('write', { position: pos });
        });
        return [encodeFrame(CMD_BUSSERVO_SYNC_WRITE, DEVICE_BUSSERVO, [this.series], bytes)];
    }

    // Timed arrive-together (group.writeTimed()). entries: [[member, target, current], ...].
    // Bus servos do their own motion, so we match speeds: speed_i = distance_i /
    // duration, scaled down uniformly if the fastest exceeds the cap (ratios —
    // and thus simultaneous arrival — preserved), floored at 1 to avoid the
    // Feetech "speed 0 = max speed" trap. Then one SyncWrite with per-servo speeds.
    _memberMoveEncode(entries, durationMs) {
        const durSec   = Math.max(0.001, durationMs / 1000);
        const cap      = this.maxMoveSpeed || 4095;
        const minSpeed = 1;
        const items = entries.map(([m, target, current]) => {
            const t = m._clampPos(Math.round(target));   // clamp BEFORE distance/speed matching
            const distance = Math.abs(t - Math.round(current ?? m.memberValue ?? 0));
            return { m, target: t, distance };
        });
        const maxRaw = items.reduce((mx, it) => Math.max(mx, it.distance / durSec), 0);
        const scale  = (maxRaw > cap) ? (cap / maxRaw) : 1;
        const recs = items.map(it => {
            const s = Math.min(cap, Math.max(minSpeed, Math.round((it.distance / durSec) * scale)));
            return [it.m, it.target, s];
        });
        const frames = this._memberSetEncode(recs);   // arms each member's whenDone()
        recs.forEach(([m]) => { m._moveDuration = Math.max(0, durationMs); });
        return frames;
    }

    // -------------------------------------------------------------------
    // State snapshot
    // -------------------------------------------------------------------
    getState() {
        return {
            logicalId:   this.logicalId,
            servoId:     this.servoId,
            series:      this.series === BUSSERVO_SERIES_SC ? 'SC' : 'ST',
            attached:    this.isAttached,
            mode:        this.mode === BUSSERVO_MODE_WHEEL ? 'wheel' : 'position',
            torque:      this.torqueOn,
            resolution:  this.resolution,
            target:      this.target,
            hasTarget:   this.hasTarget,
            position:    this.position,
            velocity:    this.velocity,
            load:        this.load,
            voltage:     this.voltage,
            temperature: this.temperature,
            current:     this.current,
            limits:      this.limitEnabled ? { min: this.limitMin, max: this.limitMax } : null,
            firmwareLimits: this.firmwareLimits,
            present:     this.present,
            home:        this.homePosition ?? Math.round(this.resolution / 2),
            interval:    this._readInterval,
        };
    }

    // -------------------------------------------------------------------
    // Internal helpers
    // -------------------------------------------------------------------
    _raw(cmd, params) { this.arduino.send(encodeFrame(cmd, DEVICE_BUSSERVO, params)); }

    _requireAttached(who) {
        if (!this.isAttached) { this._warn(`not attached (${who})`); return false; }
        return true;
    }

    _drain(list, value) {
        if (!list.length) return;
        const resolvers = list.splice(0, list.length);
        resolvers.forEach(r => r(value));
    }
}

// Let the core materialise a BusServo when the SKETCH creates one
// (PardaloteBusServo.attach("wrist", 5) → CMD_SHARE → arduino.wrist).
registerExtensionType(BusServo);

// ----- pardalote-stepper.js ----------------------------------
// ==============================================================
// stepper.js
// Pardalote Stepper Motor Extension
// Part of Pardalote — version in package.json
// by Scott Mitchell
// GPL-3.0-or-later License
//
// Mirrors the AccelStepper API (non-blocking motion). Targets and motion
// profiles are sent to the Arduino, which generates the step pulses on
// board — you never stream individual steps over WiFi.
//
// Works with STEP/DIR drivers (TMC2208/2209, A4988, EasyDriver) and
// 4-wire coil drivers (28BYJ-48 via ULN2003, bipolar via H-bridge).
//
// Usage:
//   const arduino = new Arduino();
//   arduino.add('x', new Stepper());
//   arduino.connect('192.168.1.42');
//
//   arduino.on('ready', () => {
//       arduino.x.attach(STEP, DIR, EN);   // DRIVER mode (EN optional)
//       arduino.x.setMaxSpeed(1000);       // steps/sec
//       arduino.x.setAcceleration(500);    // steps/sec^2
//       arduino.x.moveTo(2000);            // absolute target
//   });
//
//   arduino.x.on('done', ({ position }) => console.log('arrived at', position));
// ==============================================================

const DEVICE_STEPPER = 205;

const CMD_STEPPER_ATTACH        = 0x33;
const CMD_STEPPER_DETACH        = 0x34;
const CMD_STEPPER_MOVE_TO       = 0x35;
const CMD_STEPPER_MOVE          = 0x36;
const CMD_STEPPER_SET_MAX_SPEED = 0x37;
const CMD_STEPPER_SET_ACCEL     = 0x38;
const CMD_STEPPER_RUN_SPEED     = 0x39;
const CMD_STEPPER_STOP          = 0x3A;
const CMD_STEPPER_SET_POSITION  = 0x3B;
const CMD_STEPPER_ENABLE        = 0x3C;
const CMD_STEPPER_SET_LIMITS    = 0x3D;
const CMD_STEPPER_READ          = 0x3E;
const CMD_STEPPER_DONE          = 0x3F;
const CMD_STEPPER_MOVE_TIMED    = 0x4F;
const CMD_STEPPER_SYNC_MOVE     = 0x50;
const CMD_STEPPER_HOME          = 0x40;  // [id, speed?] — board homing routine (seek switch → back off → travel home)
const CMD_STEPPER_SET_SWITCH    = 0x52;  // [id, which, pin, trigger] — config (0x51 = busservo DONE)
const CMD_STEPPER_LIMIT         = 0x53;  // Ar→JS: [id, which, position] — switch tripped, board hard-stopped
const CMD_STEPPER_SET_SWITCH_POS = 0x54; // [id, which, coord] — coordinate a switch sits at (independent of limits)
const CMD_STEPPER_SET_HOME      = 0x55;  // [id, value?] — re-zero the frame; board echoes shifted pos/limits/switchPos
const CMD_STEPPER_HARD_STOP     = 0x57;  // [id] — instant halt, no decel ramp (0x56 = CMD_SHARE)
const CMD_STEPPER_GESTURE       = 0x59;  // global: payload = stepper channel blocks (segment schedules).
                                         // See pardalote.js CURVE_IDS / GESTURE_FLAG_* and defs.h.

// Board-side cap (PardaloteStepper.h MAX_STEPPER_SEGMENTS) — mirrored so JS
// can warn instead of silently overrunning. Extra segments are dropped.
const MAX_STEPPER_SEGMENTS = 16;

// Interface types — match AccelStepper (and PardaloteStepper.h).
const STEPPER_DRIVER    = 1;   // STEP/DIR
const STEPPER_FULL4WIRE = 4;   // 4 coil pins

class Stepper extends Extension {
    static deviceId = DEVICE_STEPPER;

    constructor() {
        super();

        // Hardware / attach state
        this.interface  = STEPPER_DRIVER;
        this.pins       = [-1, -1, -1, -1];
        this.enPin      = -1;
        this.invertMask = 0x04;          // enable active-LOW by default
        this.isAttached = false;

        // Motion profile
        this.maxSpeed     = 1000;        // steps/sec
        this.acceleration = 500;         // steps/sec^2
        this.stepsPerRev  = 200;         // for degree/revolution helpers

        // Commanded destination (set by moveTo/move; refined from read polls)
        this.target       = 0;

        // Live state (updated by read polls and DONE)
        this.position     = 0;
        this.distanceToGo = 0;
        this.speed        = 0;
        this.isRunning    = false;

        // Hardware limit switches — none/one/two, enforced ON THE BOARD
        // (direction-aware instant stop; the browser just gets told).
        // Entries are null or { pin, trigger }.
        this.switches = { min: null, max: null };
        this.limitHit = null;   // 'min' | 'max' after a trip; cleared by the next move

        // Coordinate each switch physically sits at (steps), independent of the
        // soft limits. Default 0 = the switch is the origin. Homing adopts this
        // value when the switch trips. Board-replayed.
        this.switchPos = { min: 0, max: 0 };

        // Home is always the origin (0) — where home() ends up. setHome()
        // re-zeros the frame so the current spot becomes 0.
        this.homePosition = 0;

        // Soft limits (safety) — enforced on the board.
        this.limitMin     = 0;
        this.limitMax     = 0;
        this.limitEnabled = false;

        // Periodic read registration (board-side).
        // _readThreshold is in steps; 0 = board default (1 step).
        // Survives _reset() — it's user-tuned configuration.
        this._readInterval  = 0;
        this._readThreshold = 0;

        // Pending _whenDone() resolvers, drained on 'done'.
        this._doneResolvers = [];

        // Promise for the most recent move, consumed by whenDone(). Armed by
        // every position move (they all emit 'done' on arrival); cleared by
        // runSpeed (never "arrives"). _moveDuration feeds the default timeout.
        this._movePromise  = null;
        this._moveDuration = 0;

        // Set true when the Arduino announces this stepper's state on connect.
        this._announcedByArduino = false;
    }

    // -------------------------------------------------------------------
    // Board switch — wipe per-board state, keep user-tuned config.
    // -------------------------------------------------------------------
    _reset() {
        this._readInterval = 0;  // registration died with the old board — send nothing
        this._resolveDone();             // don't leave awaiters hanging
        this._movePromise  = null;
        this._moveDuration = 0;
        this.interface   = STEPPER_DRIVER;
        this.pins        = [-1, -1, -1, -1];
        this.enPin       = -1;
        this.invertMask  = 0x04;
        this.isAttached  = false;
        this.target       = 0;
        this.position     = 0;
        this.distanceToGo = 0;
        this.speed        = 0;
        this.isRunning    = false;
        this.limitEnabled = false;
        this.switches     = { min: null, max: null };
        this.limitHit     = null;
        this.switchPos    = { min: 0, max: 0 };
        this.homePosition = 0;
        this._announcedByArduino = false;
    }

    // -------------------------------------------------------------------
    // Reconnection — replay state only if the Arduino reset (didn't announce).
    // -------------------------------------------------------------------
    _reRegister() {
        if (this.isAttached && !this._announcedByArduino) {
            this._sendAttach();
            this._raw(CMD_STEPPER_SET_MAX_SPEED, [this.logicalId, this.maxSpeed]);
            this._raw(CMD_STEPPER_SET_ACCEL,     [this.logicalId, this.acceleration]);
            if (this.limitEnabled) {
                this._raw(CMD_STEPPER_SET_LIMITS,
                    [this.logicalId, this.limitMin, this.limitMax, 1]);
            }
            for (const key of ['min', 'max']) {
                const sw = this.switches[key];
                if (sw) this._raw(CMD_STEPPER_SET_SWITCH,
                    [this.logicalId, key === 'max' ? 1 : 0, sw.pin, sw.trigger]);
            }
            // Switch coordinates — absolute (NOT a SET_HOME re-zero, which would
            // shift them again). Home is always the origin, so nothing to replay.
            for (const key of ['min', 'max']) {
                if (this.switchPos[key] !== 0)
                    this._raw(CMD_STEPPER_SET_SWITCH_POS,
                        [this.logicalId, key === 'max' ? 1 : 0, this.switchPos[key]]);
            }
            this._raw(CMD_STEPPER_SET_POSITION, [this.logicalId, this.position]);
        }
        // Periodic read registrations are per-WS-client on the Arduino
        // (cleared on disconnect), so always re-register if active.
        if (this.isAttached && this._readInterval > 0) this._sendRead();
        this._announcedByArduino = false;
    }

    // -------------------------------------------------------------------
    // attach(stepPin, dirPin, enPin?, options?)   — STEP/DIR drivers
    // options: { invertDir, invertStep, invertEnable }  (invertEnable defaults true)
    // -------------------------------------------------------------------
    attach(stepPin, dirPin, enPin = -1, options = {}) {
        const { invertDir = false, invertStep = false, invertEnable = true } = options;
        this.interface  = STEPPER_DRIVER;
        this.pins       = [this.arduino._resolvePin(stepPin),
                           this.arduino._resolvePin(dirPin), -1, -1];
        this.enPin      = (enPin === -1) ? -1 : this.arduino._resolvePin(enPin);
        this.invertMask = (invertDir ? 0x01 : 0) |
                          (invertStep ? 0x02 : 0) |
                          (invertEnable ? 0x04 : 0);
        this.isAttached = true;
        this._sendAttach();
        return this;
    }

    // -------------------------------------------------------------------
    // attach4wire(p1, p2, p3, p4)   — 28BYJ-48 / bipolar via H-bridge
    // -------------------------------------------------------------------
    attach4wire(p1, p2, p3, p4) {
        this.interface  = STEPPER_FULL4WIRE;
        this.pins       = [this.arduino._resolvePin(p1), this.arduino._resolvePin(p2),
                           this.arduino._resolvePin(p3), this.arduino._resolvePin(p4)];
        this.enPin      = -1;
        this.isAttached = true;
        this._sendAttach();
        return this;
    }

    _sendAttach() {
        const params = (this.interface === STEPPER_FULL4WIRE)
            ? [this.logicalId, this.interface, ...this.pins]
            : [this.logicalId, this.interface, this.pins[0], this.pins[1],
               this.enPin, this.invertMask];
        this.arduino.send(encodeFrame(CMD_STEPPER_ATTACH, DEVICE_STEPPER, params));
        // Push the current profile so the board matches our cached config.
        this._raw(CMD_STEPPER_SET_MAX_SPEED, [this.logicalId, this.maxSpeed]);
        this._raw(CMD_STEPPER_SET_ACCEL,     [this.logicalId, this.acceleration]);
    }

    detach() {
        this._stopRead();
        this.arduino.send(encodeFrame(CMD_STEPPER_DETACH, DEVICE_STEPPER, [this.logicalId]));
        this.isAttached = false;
        return this;
    }

    // -------------------------------------------------------------------
    // Motion profile
    // -------------------------------------------------------------------
    setMaxSpeed(speed) {
        this.maxSpeed = Math.max(0, speed);
        if (this.isAttached) this._raw(CMD_STEPPER_SET_MAX_SPEED, [this.logicalId, this.maxSpeed]);
        return this;
    }

    setAcceleration(accel) {
        this.acceleration = Math.max(0, accel);
        if (this.isAttached) this._raw(CMD_STEPPER_SET_ACCEL, [this.logicalId, this.acceleration]);
        return this;
    }

    // -------------------------------------------------------------------
    // Position moves (accel-limited). Chainable.
    // -------------------------------------------------------------------
    moveTo(absolute) {
        if (!this._requireAttached('moveTo')) return this;
        this._armDone();
        this.target = Math.round(absolute);
        this.arduino.send(encodeFrame(CMD_STEPPER_MOVE_TO, DEVICE_STEPPER,
            [this.logicalId, this.target]));
        this._emit('move', { target: this.target });
        return this;
    }

    move(relative) {
        if (!this._requireAttached('move')) return this;
        this._armDone();
        const rel = Math.round(relative);
        this.target = this.position + rel;   // estimate; refined by the next read poll
        this.arduino.send(encodeFrame(CMD_STEPPER_MOVE, DEVICE_STEPPER,
            [this.logicalId, rel]));
        this._emit('move', { target: this.target });
        return this;
    }

    // moveToTimed(target, duration) — constant-speed move sized to arrive in
    // ~duration ms. The board computes the speed from its own position. Used
    // by group.writeTimed() for arrive-together; fires 'done' on completion.
    moveToTimed(absolute, duration = 1000) {
        if (!this._requireAttached('moveToTimed')) return this;
        this._armDone(duration);
        this.target = Math.round(absolute);
        this.arduino.send(encodeFrame(CMD_STEPPER_MOVE_TIMED, DEVICE_STEPPER,
            [this.logicalId, this.target, Math.max(0, Math.round(duration))]));
        this._emit('move', { target: this.target });
        return this;
    }

    // -------------------------------------------------------------------
    // gesture(segments, opts?) — play an authored SEGMENT SCHEDULE on-board.
    //
    // The stepper counterpart of servo.gesture(): an ordered list of eased
    // segments the board plays back-to-back on its own clock (MODE_EASED —
    // each tick follows the segment's eased position at a curve-derived
    // speed). Values are in STEPS. Each segment is { dur, curve, and either
    // `by` (relative step delta) or `to` (absolute position) }:
    //
    //   lift.gesture([                       // a lead-screw bounce, no homing
    //       { by:  800, dur: 350, curve: 'easeOut'   },
    //       { by: -800, dur: 550, curve: 'easeInOut' },
    //       { by:  120, dur: 200, curve: 'back'      },  // small overshoot settle
    //   ]);
    //   await lift.gesture([...]).whenDone();
    //
    // Relative by default — the portable primitive, honest on an open-loop
    // stepper (the board captures `from` from its live position at each
    // segment, so nothing accumulates and no absolute truth is needed). Use
    // `to`/opts.absolute for absolute targets (soft limits clamp the ends).
    // An eased move's velocity peaks above its average, so the board briefly
    // raises the speed cap to hit the authored duration, then restores it.
    // Fires 'done' (resolves whenDone()) when the last segment lands.
    // -------------------------------------------------------------------
    gesture(segments, opts = {}) {
        const blk = this._gestureBlock(segments, opts);
        if (!blk) return this;
        this.arduino.send(encodeFrame(CMD_STEPPER_GESTURE, DEVICE_STEPPER, [], blk.bytes));
        return this;
    }

    // Encode ONE gesture channel block — shared by gesture() (wrap + send) and
    // the group adapter _memberGestureEncode() (batched, no send). Arms
    // whenDone(), mirrors the commanded target, emits 'move'. Returns
    // { bytes, total } or null when there's nothing to play.
    _gestureBlock(segments, opts = {}) {
        if (!this._requireAttached('gesture')) return null;
        if (!Array.isArray(segments) || segments.length === 0) {
            this._warn('gesture: needs a non-empty array of segments');
            return null;
        }

        const usesTo = segments.some(s => s.to !== undefined);
        const usesBy = segments.some(s => s.by !== undefined || s.value !== undefined);
        const absolute = (opts.absolute !== undefined) ? !!opts.absolute : usesTo;
        if (usesTo && usesBy)
            this._warn(`gesture: mixes 'to' (absolute) and 'by' (relative) — treating whole gesture as ${absolute ? 'absolute' : 'relative'}`);

        if (segments.length > MAX_STEPPER_SEGMENTS)
            this._warn(`gesture: ${segments.length} segments exceeds board max ${MAX_STEPPER_SEGMENTS} — extra segments dropped`);
        const count = Math.min(segments.length, MAX_STEPPER_SEGMENTS);

        const flags = absolute ? GESTURE_FLAG_ABSOLUTE : 0;

        // Encode: [logicalId u8, flags u8, count u8] + count × {curve u8, dur u16, value i32}.
        const bytes = new Uint8Array(3 + count * 7);
        const dv    = new DataView(bytes.buffer);
        dv.setUint8(0, this.logicalId & 0xFF);
        dv.setUint8(1, flags & 0xFF);
        dv.setUint8(2, count & 0xFF);
        let total = 0, rest = this.position;   // predicted end (board uses its true live position)
        for (let i = 0; i < count; i++) {
            const s   = segments[i];
            const off = 3 + i * 7;
            const dur = Math.max(1, Math.round(s.dur ?? 0));
            const val = absolute ? Math.round(s.to ?? rest)
                                 : Math.round(s.by ?? s.value ?? 0);
            dv.setUint8(off, curveId(s.curve));
            dv.setUint16(off + 1, dur & 0xFFFF, false);
            dv.setInt32(off + 3, val, false);
            total += dur;
            rest = absolute ? Math.round(s.to ?? rest) : rest + Math.round(s.by ?? s.value ?? 0);
        }

        this._armDone(total);
        this.target = rest;   // mirror commanded target; read polls refine position
        this._emit('move', { target: rest });
        return { bytes, total };
    }

    // Group adapter (group.gesture()). entries: [[member, segments], ...], all
    // Steppers → one CMD_STEPPER_GESTURE frame carrying every member's channel
    // block; the board plays them phase-locked on its own clock. Returns
    // frame(s) WITHOUT sending, so the group batches all types into one message.
    _memberGestureEncode(entries) {
        const blocks = [];
        for (const [m, segs] of entries) { const b = m._gestureBlock(segs); if (b) blocks.push(b.bytes); }
        if (!blocks.length) return [];
        const payload = new Uint8Array(blocks.reduce((n, b) => n + b.length, 0));
        let off = 0;
        for (const b of blocks) { payload.set(b, off); off += b.length; }
        return [encodeFrame(CMD_STEPPER_GESTURE, DEVICE_STEPPER, [], payload)];
    }

    // -------------------------------------------------------------------
    // Velocity mode — continuous rotation at a constant speed (steps/sec).
    // Sign sets direction. stop() ends it.
    // -------------------------------------------------------------------
    runSpeed(speed) {
        if (!this._requireAttached('runSpeed')) return this;
        this.limitHit      = null;   // new motion
        this._movePromise  = null;   // continuous — never "arrives"
        this._moveDuration = 0;
        this.arduino.send(encodeFrame(CMD_STEPPER_RUN_SPEED, DEVICE_STEPPER,
            [this.logicalId, speed]));
        return this;
    }

    stop() {
        if (!this._requireAttached('stop')) return this;
        this.arduino.send(encodeFrame(CMD_STEPPER_STOP, DEVICE_STEPPER, [this.logicalId]));
        return this;
    }

    // hardStop() — instant halt with NO deceleration ramp (unlike stop(),
    // which decelerates). The board zeroes speed and distanceToGo in one
    // call, keeping the current position; a DONE follows so whenDone()
    // settles. Use for an e-stop, or to end a spin without the decel travel.
    hardStop() {
        if (!this._requireAttached('hardStop')) return this;
        this.arduino.send(encodeFrame(CMD_STEPPER_HARD_STOP, DEVICE_STEPPER, [this.logicalId]));
        return this;
    }

    // -------------------------------------------------------------------
    // Zeroing / manual homing — declare the current physical position.
    // -------------------------------------------------------------------
    setPosition(position = 0) {
        position = Math.round(position);
        this.position = position;
        if (this.isAttached) this._raw(CMD_STEPPER_SET_POSITION, [this.logicalId, position]);
        return this;
    }

    // -------------------------------------------------------------------
    // Enable pin — hold torque (enable) or release the coils (disable).
    // -------------------------------------------------------------------
    enable()  { if (this.isAttached) this._raw(CMD_STEPPER_ENABLE, [this.logicalId, 1]); return this; }
    disable() { if (this.isAttached) this._raw(CMD_STEPPER_ENABLE, [this.logicalId, 0]); return this; }

    // -------------------------------------------------------------------
    // Soft limits (safety) — the board clamps every target to [min, max].
    // -------------------------------------------------------------------
    setLimits(min, max) {
        this.limitMin     = Math.round(min);
        this.limitMax     = Math.round(max);
        this.limitEnabled = true;
        if (this.isAttached) {
            this._raw(CMD_STEPPER_SET_LIMITS, [this.logicalId, this.limitMin, this.limitMax, 1]);
        }
        return this;
    }

    clearLimits() {
        this.limitEnabled = false;
        if (this.isAttached) {
            this._raw(CMD_STEPPER_SET_LIMITS, [this.logicalId, this.limitMin, this.limitMax, 0]);
        }
        return this;
    }

    // -------------------------------------------------------------------
    // Hardware limit switches — none, one, or two, one call per switch:
    //   arduino.x.setLimitSwitch(LIMIT_MIN, 9);          // min end, active LOW (pull-up, switch to GND)
    //   arduino.x.setLimitSwitch(LIMIT_MAX, 10, HIGH);   // max end, active HIGH
    //   arduino.x.clearLimitSwitch(LIMIT_MIN);
    //
    // The trip happens ON THE BOARD (direction-aware instant stop; moving
    // away from a pressed switch is always allowed, so you can back off).
    // The browser gets a 'limit' event ({ which, position }), limitHit is
    // set, and the normal 'done' follows — so whenDone() still settles.
    // -------------------------------------------------------------------
    setLimitSwitch(which, pin, trigger = LOW) {
        const key = this._swKey(which);
        if (!key) { this._warn('setLimitSwitch — which must be LIMIT_MIN or LIMIT_MAX'); return this; }
        if (pin === -1 || pin === undefined || pin === null) return this.clearLimitSwitch(which);
        pin     = this.arduino._resolvePin(pin);
        trigger = trigger ? 1 : 0;
        this.switches[key] = { pin, trigger };
        if (this.isAttached) {
            this._raw(CMD_STEPPER_SET_SWITCH, [this.logicalId, key === 'max' ? 1 : 0, pin, trigger]);
        }
        return this;
    }

    clearLimitSwitch(which) {
        const key = this._swKey(which);
        if (!key) { this._warn('clearLimitSwitch — which must be LIMIT_MIN or LIMIT_MAX'); return this; }
        this.switches[key] = null;
        if (this.limitHit === key) this.limitHit = null;
        if (this.isAttached) {
            this._raw(CMD_STEPPER_SET_SWITCH, [this.logicalId, key === 'max' ? 1 : 0, -1, 0]);
        }
        return this;
    }

    _swKey(which) {
        if (which === 1 || which === 'max') return 'max';
        if (which === 0 || which === 'min') return 'min';
        return null;
    }

    // -------------------------------------------------------------------
    // Switch coordinate — where a limit switch physically sits, independent
    // of the soft limits. Homing adopts this coordinate when the switch trips
    // (default 0 = the switch is the origin). Lets home be the origin (0) with
    // the switch somewhere else:
    //   x.setLimitSwitch(LIMIT_MIN, 9);       // min-end switch on pin 9
    //   x.setSwitchPosition(LIMIT_MIN, -500); // it sits 500 steps below home
    //   await x.home().whenDone();            // seeks it, then travels to 0
    // -------------------------------------------------------------------
    setSwitchPosition(which, coord) {
        const key = this._swKey(which);
        if (!key) { this._warn('setSwitchPosition — which must be LIMIT_MIN or LIMIT_MAX'); return this; }
        this.switchPos[key] = Math.round(coord);
        if (this.isAttached) {
            this._raw(CMD_STEPPER_SET_SWITCH_POS,
                [this.logicalId, key === 'max' ? 1 : 0, this.switchPos[key]]);
        }
        return this;
    }

    // -------------------------------------------------------------------
    // Homing — home is the origin (0). setHome() re-zeros the frame so the
    // current spot becomes 0; home() travels back to it.
    //
    //   x.setHome();       // "here is 0" — re-zero: current position → 0, and
    //                      //  the soft limits + switch positions shift with it
    //   await x.home().whenDone({ timeout: 30000 });
    //
    // With a limit switch configured, home() runs a BOARD-SIDE routine: seek
    // the switch (MIN if configured, else MAX) at a homing speed, set the
    // counter to the switch's coordinate (setSwitchPosition, default 0) when it
    // trips, back off until it releases, then travel to the origin (0). Without
    // a switch it's a plain accel move to 0 (counter trusted).
    //
    // setHome(value) re-zeros to `value` instead of 0 (rarely needed): the
    // current spot becomes `value` and everything shifts by the same offset.
    // The board performs the shift and echoes the new position, limits and
    // switch positions — synced silently in handleMessage.
    // -------------------------------------------------------------------
    setHome(value = 0) {
        if (!this._requireAttached('setHome')) return this;
        value = Math.round(value);
        this.position = value;   // optimistic; the board's echoes confirm
        this._raw(CMD_STEPPER_SET_HOME, [this.logicalId, value]);
        return this;
    }

    // home(opts?) — opts: { speed, timeout }.
    //   speed   — seek speed in steps/sec (default maxSpeed/4, board-side).
    //   timeout — ms cap on the seek/back-off legs (default 30 s, board-side).
    //             If the switch never trips or never releases, the board
    //             hard-stops, fires 'home:fail', then 'done' (motion settled).
    // A bare number is ignored (it's a duration when group.home(duration)
    // fans out — the routine has no duration).
    home(opts = {}) {
        if (!this._requireAttached('home')) return this;
        const speed   = (typeof opts === 'number') ? 0 : Math.max(0, Math.round(opts.speed ?? 0));
        const timeout = (typeof opts === 'number') ? 0 : Math.max(0, Math.round(opts.timeout ?? 0));
        this._armDone();   // resolves on the routine's final DONE
        if (this.switches.min || this.switches.max) {
            this.target = this.homePosition;
            this._raw(CMD_STEPPER_HOME, [this.logicalId, speed, timeout]);
            this._emit('move', { target: this.target });
            return this;
        }
        // No switch — plain accel move (re-arms via moveTo).
        return this.moveTo(this.homePosition);
    }

    // -------------------------------------------------------------------
    // read(interval?, threshold?) — poll live state.
    // read()             — return cached position; no network traffic.
    // read(interval)     — board-side periodic poll (ms); 'change' fires
    //                      when the position moved by threshold+ steps.
    // read(interval, 10) — only report changes of 10+ steps.
    // read(END)          — stop this browser's periodic read.
    // The board runs the poll and gates per browser ;
    // threshold 0 = board default (1 step). Calling again with the same
    // settings just returns the cached value.
    // -------------------------------------------------------------------
    read(interval, threshold) {
        if (!this.isAttached) {
            this._warn('not attached');
            return this.position;
        }
        if (interval === END) { this._stopRead(); return this.position; }
        if (this._readInterval > 0
            && (interval  === undefined || interval  === this._readInterval)
            && (threshold === undefined || threshold === this._readThreshold)) {
            return this.position;
        }
        this._readInterval = interval ?? this.arduino.defaultInterval;
        if (threshold !== undefined) this._readThreshold = threshold;
        this._sendRead();
        return this.position;
    }

    // setReadInterval(ms) / setReadThreshold(steps) — set poll settings
    // directly; applied immediately if polling, stored for read() otherwise.
    setReadInterval(ms) {
        this._readInterval = ms;
        if (this.isAttached && ms > 0) this._sendRead();
        return this;
    }

    setReadThreshold(steps) {
        this._readThreshold = steps;
        if (this.isAttached && this._readInterval > 0) this._sendRead();
        return this;
    }

    // Register (or update) this browser's poll with the board.
    _sendRead() {
        this.arduino.send(encodeFrame(CMD_STEPPER_READ, DEVICE_STEPPER,
            [this.logicalId, this._readInterval,
             Math.max(0, Math.round(this._readThreshold))]));
    }

    _stopRead() {
        if (this._readInterval > 0) {
            this.arduino.send(encodeFrame(CMD_STEPPER_READ, DEVICE_STEPPER,
                [this.logicalId, END]));   // END = unregister
        }
        this._readInterval = 0;
    }

    // -------------------------------------------------------------------
    // Angle helpers — computed JS-side into raw steps, so the protocol
    // stays in pure steps. setStepsPerRev() must reflect your microstepping
    // (e.g. a 1.8° motor at 16 microsteps = 200 * 16 = 3200).
    // -------------------------------------------------------------------
    setStepsPerRev(steps) { this.stepsPerRev = Math.max(1, steps); return this; }

    moveToDegrees(deg)     { return this.moveTo(deg / 360 * this.stepsPerRev); }
    moveDegrees(deg)       { return this.move(deg / 360 * this.stepsPerRev); }
    moveToRevolutions(rev) { return this.moveTo(rev * this.stepsPerRev); }
    moveRevolutions(rev)   { return this.move(rev * this.stepsPerRev); }

    // -------------------------------------------------------------------
    // Callback shortcuts
    // -------------------------------------------------------------------
    onChange(fn)   { return this.on('change',   fn); }
    onDone(fn)     { return this.on('done',     fn); }
    onMove(fn)     { return this.on('move',     fn); }
    onLimit(fn)    { return this.on('limit',    fn); }
    onHomeFail(fn) { return this.on('home:fail', fn); }

    // -------------------------------------------------------------------
    // Incoming frames from Arduino.
    // -------------------------------------------------------------------
    handleMessage(frame) {
        switch (frame.cmd) {

            // ---- announce / state sync (silent — no events) ----
            case CMD_STEPPER_ATTACH:
                this.interface = frame.params[1];
                if (this.interface === STEPPER_FULL4WIRE) {
                    this.pins = [frame.params[2], frame.params[3], frame.params[4], frame.params[5]];
                    this.enPin = -1;
                } else {
                    this.pins = [frame.params[2], frame.params[3], -1, -1];
                    this.enPin      = frame.params[4] ?? -1;
                    this.invertMask = frame.params[5] ?? 0x04;
                }
                this.isAttached          = true;
                this._announcedByArduino = true;
                break;

            case CMD_STEPPER_SET_MAX_SPEED: this.maxSpeed     = frame.params[1]; break;
            case CMD_STEPPER_SET_ACCEL:     this.acceleration = frame.params[1]; break;
            case CMD_STEPPER_SET_POSITION:  this.position     = frame.params[1]; break;
            case CMD_STEPPER_MOVE_TO:       this.target       = frame.params[1]; break;   // reconnect target replay

            case CMD_STEPPER_SET_LIMITS:
                this.limitMin     = frame.params[1];
                this.limitMax     = frame.params[2];
                this.limitEnabled = frame.params[3] === 1;
                break;

            // ---- live updates (emit events) ----
            case CMD_STEPPER_READ:
                this.position     = frame.params[1];
                this.distanceToGo = frame.params[2];
                this.speed        = frame.params[3];
                this.isRunning    = frame.params[4] === 1;
                this.target       = this.position + this.distanceToGo;   // the board's real target
                this._emit('change', {
                    position: this.position, distanceToGo: this.distanceToGo,
                    speed: this.speed, isRunning: this.isRunning,
                });
                break;

            case CMD_STEPPER_DONE:
                this.position     = frame.params[1];
                this.distanceToGo = 0;
                this.isRunning    = false;
                this.target       = this.position;   // arrived
                this._emit('done', { position: this.position });
                this._resolveDone();
                break;

            // ---- limit switches ----
            case CMD_STEPPER_SET_SWITCH: {
                // Announce sync (or sketch-issued config echo) — silent.
                const key = frame.params[1] === 1 ? 'max' : 'min';
                const pin = frame.params[2];
                this.switches[key] = (pin >= 0)
                    ? { pin, trigger: frame.params[3] ? 1 : 0 }
                    : null;
                break;
            }

            case CMD_STEPPER_HOME: {
                // Homing GAVE UP (seek/back-off timeout) — the board hard-
                // stopped where it was. DONE follows, so whenDone() settles;
                // this event is how you learn home was never reached.
                this.position     = frame.params[1];
                this.distanceToGo = 0;
                this.isRunning    = false;
                this.target       = this.position;
                this._emit('home:fail', { position: this.position });
                break;
            }

            case CMD_STEPPER_SET_SWITCH_POS: {
                // Echo / announce sync — silent. The coordinate a switch sits
                // at (also arrives when SET_HOME re-zeros and shifts it).
                const key = frame.params[1] === 1 ? 'max' : 'min';
                this.switchPos[key] = frame.params[2];
                break;
            }

            case CMD_STEPPER_LIMIT: {
                // A switch tripped and the board hard-stopped the motor.
                // CMD_STEPPER_DONE follows (motion ended), so whenDone()
                // still settles; limitHit records that we stopped short.
                const which = frame.params[1] === 1 ? 'max' : 'min';
                this.position     = frame.params[2];
                this.distanceToGo = 0;
                this.isRunning    = false;
                this.target       = this.position;   // the move is over
                this.limitHit     = which;
                this._emit('limit', { which, position: this.position });
                break;
            }
        }
    }

    // -------------------------------------------------------------------
    // Group member adapter — see arduino.group(). Returns frame(s) WITHOUT
    // sending, so the group can batch all members into one message.
    // memberValue reports the last-read position.
    // -------------------------------------------------------------------
    _memberWrite(target) {
        if (!this._requireAttached('group write')) return [];
        this._armDone();
        target = Math.round(target);
        this.target = target;                 // mirror individual moveTo()
        this._emit('move', { target });
        return [encodeFrame(CMD_STEPPER_MOVE_TO, DEVICE_STEPPER, [this.logicalId, target])];
    }

    get memberValue() { return this.position; }

    // -------------------------------------------------------------------
    // Group timed-move hook (group.writeTimed()). Steppers know their own exact
    // position, so the board computes matched speeds from a shared duration —
    // one CMD_STEPPER_SYNC_MOVE with { logicalId, target } records makes the
    // whole bucket arrive together. entries: [[member, target, current], ...].
    // -------------------------------------------------------------------
    _memberSyncKey() { return this.isAttached ? 'stepper' : null; }

    _memberMoveEncode(entries, durationMs) {
        const bytes = new Uint8Array(entries.length * 5);
        const dv = new DataView(bytes.buffer);
        entries.forEach(([m, target], i) => {
            const t = Math.round(target);
            dv.setUint8(i * 5, m.logicalId & 0xFF);
            dv.setInt32(i * 5 + 1, t, false);
            m.target = t;                     // mirror individual moveTo()
            m._armDone(durationMs);
            m._emit('move', { target: t });
        });
        return [encodeFrame(CMD_STEPPER_SYNC_MOVE, DEVICE_STEPPER,
            [Math.max(0, Math.round(durationMs))], bytes)];
    }

    // -------------------------------------------------------------------
    // State snapshot
    // -------------------------------------------------------------------
    getState() {
        return {
            logicalId:     this.logicalId,
            interface:     this.interface,
            pins:          this.pins.slice(),
            enPin:         this.enPin,
            attached:      this.isAttached,
            maxSpeed:      this.maxSpeed,
            acceleration:  this.acceleration,
            stepsPerRev:   this.stepsPerRev,
            target:        this.target,
            position:      this.position,
            distanceToGo:  this.distanceToGo,
            speed:         this.speed,
            isRunning:     this.isRunning,
            limits:        this.limitEnabled ? { min: this.limitMin, max: this.limitMax } : null,
            switches:      { min: this.switches.min, max: this.switches.max },
            switchPos:     { min: this.switchPos.min, max: this.switchPos.max },
            limitHit:      this.limitHit,
            home:          this.homePosition,
            interval:      this._readInterval,
        };
    }

    // -------------------------------------------------------------------
    // Internal helpers
    // -------------------------------------------------------------------
    _raw(cmd, params) { this.arduino.send(encodeFrame(cmd, DEVICE_STEPPER, params)); }

    _requireAttached(who) {
        if (!this.isAttached) { this._warn(`not attached (${who})`); return false; }
        return true;
    }

    _whenDone() {
        return new Promise(resolve => this._doneResolvers.push(resolve));
    }

    _resolveDone() {
        const resolvers = this._doneResolvers;
        this._doneResolvers = [];
        resolvers.forEach(r => r(this.position));
    }

    // Arm the whenDone() promise for a move that will emit 'done'.
    // Every new move also clears limitHit — it records the LAST motion.
    _armDone(durationMs = 0) {
        this.limitHit      = null;
        this._moveDuration = Math.max(0, durationMs);
        this._movePromise  = this._whenDone();
    }

    // whenDone({ timeout }?) — Promise for the most recent move. Resolves
    // `true` on CMD_STEPPER_DONE (or immediately if no move is pending / it
    // already finished), `false` on the safety timeout. timeout: ms (default
    // max(duration × 2, 10000); 0 = wait forever). Also accepts a bare
    // number: whenDone(5000).
    //
    //   await arduino.x.moveTo(2000).whenDone();
    //   await arduino.x.moveTo(0).whenDone();
    whenDone(opts = {}) {
        const t = (typeof opts === 'number') ? opts : opts.timeout;
        const timeout = t ?? Math.max(this._moveDuration * 2, 10000);
        if (!this._movePromise) return Promise.resolve(true);
        const done = this._movePromise.then(() => true);
        if (!timeout) return done;
        return Promise.race([
            done,
            new Promise(res => setTimeout(() => res(false), timeout)),
        ]);
    }
}

// Let the core materialise a Stepper when the SKETCH creates one
// (PardaloteStepper.attach("x", …) → CMD_SHARE → arduino.x).
registerExtensionType(Stepper);

// ----- pardalote-neopixel.js ---------------------------------
// ==============================================================
// neoPixel.js
// Pardalote NeoPixel Extension
// Part of Pardalote — version in package.json
// by Scott Mitchell
// GPL-3.0-or-later License
//
// Mirrors the Adafruit NeoPixel library API where possible.
// Pixel changes are buffered locally and only sent on show(),
// with threshold-based diffing to skip redundant updates.
//
// Usage:
//   const arduino = new Arduino();
//   arduino.add('strip', new NeoPixel());
//   arduino.connect('192.168.1.42');
//
//   arduino.on('ready', () => {
//       arduino.strip.init(D6, 30);
//       arduino.strip.setBrightness(80);
//       arduino.strip.fill(arduino.strip.Color(255, 0, 0));
//       arduino.strip.show();
//   });
// ==============================================================

const DEVICE_NEO_PIXEL = 200;

// 0x5C+ — extension cmds must stay out of the core range 0x00–0x0F
// (CMD_MESSAGE is routed by cmd alone; 0x0B used to swallow SET_PIXEL).
const CMD_NEO_INIT       = 0x5C;
const CMD_NEO_SET_PIXEL  = 0x5D;
const CMD_NEO_FILL       = 0x5E;
const CMD_NEO_CLEAR      = 0x5F;
const CMD_NEO_BRIGHTNESS = 0x60;
const CMD_NEO_SHOW       = 0x61;

// Pixel type flags — match Adafruit_NeoPixel
const NEO_RGB    = 0x06;
const NEO_RBG    = 0x09;
const NEO_GRB    = 0x52;
const NEO_GBR    = 0xA1;
const NEO_BRG    = 0x58;
const NEO_BGR    = 0xA4;
const NEO_KHZ800 = 0x0000;
const NEO_KHZ400 = 0x0100;

class NeoPixel extends Extension {
    static deviceId = DEVICE_NEO_PIXEL;

    constructor() {
        super();

        this._numPixels = 0;
        this.pin        = -1;
        this.pixelType  = NEO_GRB + NEO_KHZ800;
        this.brightness = 255;
        this.threshold  = 5;     // min colour distance to trigger a send

        // Local pixel buffer — Map<index, {r,g,b,w}>
        this._pixelBuffer = new Map();

        // Pending operations stored structurally so we can coalesce. These
        // describe the DESIRED next strip state, not an event log: repeated
        // calls to fill/setPixelColor/setBrightness within one throttle
        // window update them in place. See show() for the throttle logic.
        this._pendingFills      = [];          // [{ color, first, count }] — last fill of each range wins
        this._pendingSets       = new Map();   // index → { r, g, b, w }
        this._pendingClear      = false;
        this._pendingBrightness = null;        // number or null

        // show() throttle — debounce so rapid draw-loop show() calls coalesce
        // into one send. 20 ms ≈ 50 Hz comfortably keeps both ESP32 and UNO R4
        // from drowning in incoming WS frames.
        this.showThrottle      = 20;
        this._lastShowTime     = 0;
        this._pendingShowTimer = null;

        // Set to true when the Arduino announces its strip state on connect.
        // _reRegister() uses this to skip re-INIT (and the flicker it causes)
        // when the Arduino is already running — only INIT when it has reset.
        this._announcedByArduino = false;
    }

    // -------------------------------------------------------------------
    // Board switch — called by Arduino.connect() to wipe per-board state
    // while preserving user-tuned configuration (threshold, showThrottle).
    // -------------------------------------------------------------------
    _reset() {
        this.pin                 = -1;
        this._numPixels          = 0;
        this.pixelType           = NEO_GRB + NEO_KHZ800;
        this.brightness          = 255;
        this._pixelBuffer.clear();
        this._clearPending();
        this._lastShowTime       = 0;
        this._announcedByArduino = false;
    }

    _clearPending() {
        this._pendingFills      = [];
        this._pendingSets.clear();
        this._pendingClear      = false;
        this._pendingBrightness = null;
        if (this._pendingShowTimer !== null) {
            clearTimeout(this._pendingShowTimer);
            this._pendingShowTimer = null;
        }
    }

    _hasPending() {
        return this._pendingFills.length > 0
            || this._pendingSets.size > 0
            || this._pendingClear
            || this._pendingBrightness !== null;
    }

    // -------------------------------------------------------------------
    // Reconnection — restore strip state on the Arduino.
    //
    // Two cases:
    //   Arduino reset  (_announcedByArduino = false):
    //     Strip is uninitialized. Send INIT + brightness + full pixel buffer.
    //   Arduino running (_announcedByArduino = true):
    //     announce() already sent the current state; _pixelBuffer is already
    //     synced from handleMessage(). Skip INIT (avoids flicker). Just flush
    //     any changes queued while we were disconnected.
    // -------------------------------------------------------------------
    _reRegister() {
        if (this.pin === -1) return;

        if (!this._announcedByArduino) {
            // Arduino reset — re-initialize and restore full pixel state.
            // INIT goes directly (one-shot bootstrap); brightness + per-pixel
            // restore go through the pending queue so they benefit from the
            // same coalescence as normal traffic.
            this.arduino.send(encodeFrame(CMD_NEO_INIT, DEVICE_NEO_PIXEL,
                [this.logicalId, this.pin, this._numPixels, this.pixelType]));
            if (this.brightness !== 255) {
                this._pendingBrightness = this.brightness;
            }
            this._pixelBuffer.forEach(({ r, g, b, w }, index) => {
                this._pendingSets.set(index, { r, g, b, w });
            });
            this._actuallyShow();
        } else if (this._hasPending()) {
            // Arduino is running — pixel state is already correct.
            // Flush any changes queued while disconnected.
            this._actuallyShow();
        }

        this._announcedByArduino = false;   // reset for next connection cycle
    }

    // -------------------------------------------------------------------
    // init(pin, numPixels, type?)
    // Initialise the strip on the Arduino. Call once in setup.
    // -------------------------------------------------------------------
    init(pin, numPixels, type = NEO_GRB + NEO_KHZ800) {
        this.pin       = this.arduino._resolvePin(pin);
        this._numPixels = numPixels;
        this.pixelType = type;
        this._pixelBuffer.clear();
        this._clearPending();
        this.arduino.send(encodeFrame(CMD_NEO_INIT, DEVICE_NEO_PIXEL,
            [this.logicalId, this.pin, numPixels, type]));
        return this;
    }

    // -------------------------------------------------------------------
    // Color(r, g, b, w?) — pack into a 32-bit colour value
    // -------------------------------------------------------------------
    Color(r, g, b, w = 0) {
        return ((w & 0xFF) << 24) | ((r & 0xFF) << 16) | ((g & 0xFF) << 8) | (b & 0xFF);
    }

    // -------------------------------------------------------------------
    // setPixelColor(index, r, g, b, w?) or setPixelColor(index, color)
    // Buffers the change; call show() to push to LEDs.
    // -------------------------------------------------------------------
    setPixelColor(index, r_or_color, g, b, w = 0) {
        let r, gv, bv, wv;

        if (arguments.length === 2) {
            const c = r_or_color >>> 0;
            wv = (c >> 24) & 0xFF;
            r  = (c >> 16) & 0xFF;
            gv = (c >>  8) & 0xFF;
            bv =  c        & 0xFF;
        } else {
            r  = r_or_color; gv = g; bv = b; wv = w;
        }

        r = Math.round(r); gv = Math.round(gv);
        bv = Math.round(bv); wv = Math.round(wv);

        // Threshold only applies when we have a known previous colour for
        // this pixel. The first write to an untouched pixel always reaches
        // the strip — otherwise barely-visible first colours would be lost.
        const last = this._pixelBuffer.get(index);
        if (last !== undefined) {
            const dr = r-last.r, dg = gv-last.g, db = bv-last.b, dw = wv-last.w;
            const dist = Math.sqrt(dr*dr + dg*dg + db*db + dw*dw);
            if (dist <= this.threshold) return this;
        }

        this._pixelBuffer.set(index, { r, g:gv, b:bv, w:wv });
        // Coalesce: a later set for the same index replaces an earlier one.
        this._pendingSets.set(index, { r, g:gv, b:bv, w:wv });
        return this;
    }

    // -------------------------------------------------------------------
    // fill(color, first?, count?)
    // Fill a range with a colour. count=0 fills to end of strip.
    // -------------------------------------------------------------------
    fill(color, first = 0, count = 0) {
        const wv = (color >> 24) & 0xFF;
        const r  = (color >> 16) & 0xFF;
        const gv = (color >>  8) & 0xFF;
        const bv =  color        & 0xFF;

        const end = count > 0 ? first + count : this._numPixels;

        // Decide whether any pixel in the range justifies a send.
        // A never-set pixel always counts as a change (matches the
        // first-write-always-sends rule in setPixelColor).
        let changed = false;
        for (let i = first; i < end && i < this._numPixels; i++) {
            const last = this._pixelBuffer.get(i);
            if (last === undefined) { changed = true; break; }
            const dr = r-last.r, dg = gv-last.g, db = bv-last.b, dw = wv-last.w;
            const dist = Math.sqrt(dr*dr + dg*dg + db*db + dw*dw);
            if (dist > this.threshold) { changed = true; break; }
        }

        if (changed) {
            // The Arduino will paint the entire range — sync every entry,
            // not just the ones that triggered the send, so future threshold
            // checks compare against the actual strip state.
            for (let i = first; i < end && i < this._numPixels; i++) {
                this._pixelBuffer.set(i, { r, g:gv, b:bv, w:wv });
            }

            // Coalesce: a fill of the same range replaces an earlier one.
            // A fill also supersedes any per-pixel sets in its range — those
            // would be overwritten on the wire anyway.
            const existing = this._pendingFills.findIndex(
                f => f.first === first && f.count === count);
            const entry = { color: color | 0, first, count };
            if (existing >= 0) this._pendingFills[existing] = entry;
            else               this._pendingFills.push(entry);

            for (const idx of [...this._pendingSets.keys()]) {
                if (idx >= first && idx < end) this._pendingSets.delete(idx);
            }
        }
        return this;
    }

    // -------------------------------------------------------------------
    // clear() — set all pixels off
    // -------------------------------------------------------------------
    clear() {
        this._pixelBuffer.clear();
        for (let i = 0; i < this._numPixels; i++) {
            this._pixelBuffer.set(i, { r:0, g:0, b:0, w:0 });
        }
        // clear supersedes any pending fills and per-pixel sets.
        this._pendingClear = true;
        this._pendingFills = [];
        this._pendingSets.clear();
        return this;
    }

    // -------------------------------------------------------------------
    // setBrightness(value) — 0–255
    // -------------------------------------------------------------------
    setBrightness(value) {
        value = Math.max(0, Math.min(255, Math.round(value)));
        if (Math.abs(value - this.brightness) < this.threshold) return this;
        this.brightness = value;
        this._pendingBrightness = value;   // coalesces — last value wins
        return this;
    }

    // -------------------------------------------------------------------
    // show() — request a flush of buffered changes to the Arduino.
    //
    // Debounced by showThrottle (default 20 ms). Repeated show() calls
    // within the throttle window collapse into a single send that uses
    // whatever the latest pending state was at the moment of flush.
    // That's what protects a 60 fps draw loop from overwhelming the WS
    // link and producing visible "catch-up" lag.
    // -------------------------------------------------------------------
    show() {
        if (!this._hasPending()) return this;

        const now  = Date.now();
        const wait = this.showThrottle - (now - this._lastShowTime);

        if (wait > 0) {
            // Defer. Any further show() calls during this window are no-ops;
            // they'll see this._pendingShowTimer is already set.
            if (this._pendingShowTimer === null) {
                this._pendingShowTimer = setTimeout(() => {
                    this._pendingShowTimer = null;
                    this._actuallyShow();
                }, wait);
            }
        } else {
            this._actuallyShow();
        }
        return this;
    }

    // Serialise the pending state to frames and send as one batched message.
    // Order on the wire mirrors the semantic order operations take effect:
    //   BRIGHTNESS → CLEAR → FILLs → per-pixel SETs → SHOW
    _actuallyShow() {
        if (!this._hasPending()) return;
        this._lastShowTime = Date.now();

        const frames = [];

        if (this._pendingBrightness !== null) {
            frames.push(encodeFrame(CMD_NEO_BRIGHTNESS, DEVICE_NEO_PIXEL,
                [this.logicalId, this._pendingBrightness]));
            this._pendingBrightness = null;
        }

        if (this._pendingClear) {
            frames.push(encodeFrame(CMD_NEO_CLEAR, DEVICE_NEO_PIXEL,
                [this.logicalId]));
            this._pendingClear = false;
        }

        for (const f of this._pendingFills) {
            frames.push(encodeFrame(CMD_NEO_FILL, DEVICE_NEO_PIXEL,
                [this.logicalId, f.color, f.first, f.count]));
        }
        this._pendingFills = [];

        for (const [index, p] of this._pendingSets) {
            const params = p.w > 0
                ? [this.logicalId, index, p.r, p.g, p.b, p.w]
                : [this.logicalId, index, p.r, p.g, p.b];
            frames.push(encodeFrame(CMD_NEO_SET_PIXEL, DEVICE_NEO_PIXEL, params));
        }
        this._pendingSets.clear();

        frames.push(encodeFrame(CMD_NEO_SHOW, DEVICE_NEO_PIXEL, [this.logicalId]));
        this.arduino.send(frames);
    }

    // -------------------------------------------------------------------
    // Helpers
    // -------------------------------------------------------------------
    getPixelColor(index) {
        const p = this._pixelBuffer.get(index) || { r:0, g:0, b:0, w:0 };
        return this.Color(p.r, p.g, p.b, p.w);
    }

    numPixels() { return this._numPixels; }

    // Minimum colour distance to trigger a send. Higher values send less,
    // at the cost of visible quantisation during smooth fades.
    setWriteThreshold(t) { this.threshold = Math.max(0, t); return this; }

    // Minimum ms between show() flushes — debounces rapid draw-loop calls.
    // Default 20 ms. Lower for snappier response on healthy networks;
    // raise to 50 ms+ if you still see queue-buildup lag on slow links.
    // Set to 0 to disable debouncing entirely (every show() flushes).
    // (Matches the Servo extension's setWriteThrottle() naming convention.)
    setWriteThrottle(ms) { this.showThrottle = Math.max(0, ms); return this; }

    // -------------------------------------------------------------------
    // State snapshot — returns the cached JS-side state synchronously.
    // No round-trip to the Arduino; everything here is what JS already
    // tracks. Mirrors getState() on Servo, IMU, Ultrasonic, and Camera.
    // -------------------------------------------------------------------
    getState() {
        return {
            logicalId:    this.logicalId,
            pin:          this.pin,
            numPixels:    this._numPixels,
            pixelType:    this.pixelType,
            brightness:   this.brightness,
            threshold:    this.threshold,
            throttle:     this.showThrottle,
            pendingFlush: this._pendingShowTimer !== null,
        };
    }

    // -------------------------------------------------------------------
    // Incoming frames from Arduino — either announce (state sync) or
    // future read-back extensions. No events are emitted here; these
    // are silent buffer updates that keep the JS state authoritative.
    // -------------------------------------------------------------------
    handleMessage(frame) {
        switch (frame.cmd) {

            case CMD_NEO_INIT:
                // Arduino is announcing an initialized strip — sync config.
                // Set flag so _reRegister() knows not to re-INIT.
                this._announcedByArduino = true;
                this.pin       = frame.params[1];
                this._numPixels = frame.params[2];
                this.pixelType = frame.params[3];
                this._pixelBuffer.clear();
                break;

            case CMD_NEO_BRIGHTNESS:
                this.brightness = frame.params[1];
                break;

            case CMD_NEO_SET_PIXEL: {
                // Sync individual pixel into buffer from announce.
                const index = frame.params[1];
                const r     = frame.params[2];
                const g     = frame.params[3];
                const b     = frame.params[4];
                const w     = frame.params[5] ?? 0;
                this._pixelBuffer.set(index, { r, g, b, w });
                break;
            }
        }
    }
}

// Let the core materialise a NeoPixel when the SKETCH creates one
// (PardaloteNeoPixel.attach("ring", 6, 24) → CMD_SHARE → arduino.ring).
registerExtensionType(NeoPixel);

// ----- pardalote-ultrasonic.js -------------------------------
// ==============================================================
// ultrasonic.js
// Pardalote Ultrasonic Sensor Extension
// Part of Pardalote — version in package.json
// by Scott Mitchell
// GPL-3.0-or-later License
//
// Supports 3-wire and 4-wire sensors (HC-SR04, JSN-SR04T, etc.)
//
// Usage:
//   const arduino = new Arduino();
//   arduino.add('sonar', new Ultrasonic());
//   arduino.connect('192.168.1.42');
//
//   arduino.on('ready', () => {
//       arduino.sonar.attach(TRIG, ECHO);
//       arduino.sonar.read(100);            // poll every 100 ms
//       arduino.sonar.read(100, CM, 0.5);   // …reporting changes of 0.5+ cm
//   });
//
//   arduino.sonar.on('change', ({ distance, unit }) => {
//       console.log(distance, unit === CM ? 'cm' : 'in');
//   });
//
// The BOARD runs the poll: one measurement per interval
// regardless of how many browsers are connected, and each browser only
// receives readings that changed by at least its threshold (default
// 0.3 units — the HC-SR04's noise floor).
//
// Distance values travel as tenths of the requested unit on the wire;
// the extension converts to a decimal before emitting.
// A value of -1 means the echo timed out (nothing in range).
// ==============================================================

const DEVICE_ULTRASONIC = 202;

const CMD_ULTRASONIC_ATTACH      = 0x1E;
const CMD_ULTRASONIC_DETACH      = 0x1F;
const CMD_ULTRASONIC_READ        = 0x20;
const CMD_ULTRASONIC_SET_TIMEOUT = 0x21;

const CM   = 0;
const INCH = 1;

class Ultrasonic extends Extension {
    static deviceId = DEVICE_ULTRASONIC;

    constructor() {
        super();

        // Hardware state
        this.trigPin    = -1;
        this.echoPin    = -1;   // -1 = 3-wire (echo on trig pin)
        this.isAttached = false;
        this.timeoutMs  = 30;

        // Reading state
        this.distance   = -1;   // last reading in user units (decimal)
        this.unit       = CM;

        // Periodic read registration (board-side).
        // _readThreshold is in user units (decimal); 0 = board default
        // (0.3 units). Survives _reset() — it's user-tuned configuration.
        this._readInterval  = 0;
        this._readThreshold = 0;

        // Set true when Arduino announces this sensor's attach state on connect.
        // _reRegister() uses this to skip re-sending CMD_ULTRASONIC_ATTACH when
        // the Arduino is already in sync — only replay when it has reset.
        this._announcedByArduino = false;
    }

    // -------------------------------------------------------------------
    // Board switch — called by Arduino.connect() to wipe per-board state.
    // -------------------------------------------------------------------
    _reset() {
        this._readInterval       = 0;   // registration died with the old board — send nothing
        this.trigPin             = -1;
        this.echoPin             = -1;
        this.isAttached          = false;
        this.timeoutMs           = 30;
        this.distance            = -1;
        this.unit                = CM;
        this._announcedByArduino = false;
    }

    // -------------------------------------------------------------------
    // Reconnection — restore attach state on HELLO
    // -------------------------------------------------------------------
    _reRegister() {
        if (this.isAttached) {
            // Only replay attach if the Arduino didn't announce us (it reset).
            // If announce did sync us, skip — avoids duplicate Serial output
            // and redundant pin reconfiguration.
            if (!this._announcedByArduino) {
                this._sendAttach();
            }
            // Periodic read registrations are per-WS-client on the Arduino
            // (cleared on disconnect), so always re-register if active.
            if (this._readInterval > 0) this._sendRead();
        }
        this._announcedByArduino = false;  // reset for next reconnect cycle
    }

    // -------------------------------------------------------------------
    // attach(trigPin, echoPin?)
    // 4-wire: attach(trig, echo)
    // 3-wire: attach(trig)   — echo on same pin as trig
    // -------------------------------------------------------------------
    attach(trigPin, echoPin) {
        this.trigPin    = this.arduino._resolvePin(trigPin);
        this.echoPin    = (echoPin !== undefined) ? this.arduino._resolvePin(echoPin) : -1;
        this.isAttached = true;
        this._sendAttach();
        return this;
    }

    _sendAttach() {
        const params = (this.echoPin === -1)
            ? [this.logicalId, this.trigPin]
            : [this.logicalId, this.trigPin, this.echoPin];
        this.arduino.send(encodeFrame(CMD_ULTRASONIC_ATTACH, DEVICE_ULTRASONIC, params));
    }

    // -------------------------------------------------------------------
    // detach()
    // -------------------------------------------------------------------
    detach() {
        this._stopRead();
        this.arduino.send(encodeFrame(CMD_ULTRASONIC_DETACH, DEVICE_ULTRASONIC,
            [this.logicalId]));
        this.isAttached = false;
        this.trigPin    = -1;
        this.echoPin    = -1;
        return this;
    }

    // -------------------------------------------------------------------
    // read(interval?, unit?, threshold?)
    // read()                    — return cached distance; start default poll if none running.
    // read(interval)            — start/update a board-side periodic poll (ms).
    // read(interval, unit)      — periodic in CM (default) or INCH.
    // read(interval, CM, 0.5)   — only report changes of 0.5+ units.
    // read(END)                 — stop this browser's periodic read.
    // The board runs the poll and only transmits meaningful changes;
    // threshold is in the sensor's units (decimal; 0 = board default,
    // 0.3 units). Per-browser: other pages keep their own settings.
    // Calling again with the same settings just returns the cached value.
    // -------------------------------------------------------------------
    read(interval, unit = this.unit, threshold) {
        if (!this.isAttached) {
            this._warn('not attached');
            return this.distance;
        }

        if (interval === END) {
            this._stopRead();
            return this.distance;
        }

        // Poll already running with the requested settings — return cached
        if (this._readInterval > 0 && unit === this.unit
            && (interval  === undefined || interval  === this._readInterval)
            && (threshold === undefined || threshold === this._readThreshold)) {
            return this.distance;
        }

        this.unit = unit;
        this._readInterval  = interval ?? this.arduino.defaultInterval;
        if (threshold !== undefined) this._readThreshold = threshold;
        this._sendRead();
        return this.distance;
    }

    // setReadInterval(ms) / setReadThreshold(units) — set poll settings
    // directly; applied immediately if polling, stored for read() otherwise.
    setReadInterval(ms) {
        this._readInterval = ms;
        if (this.isAttached && ms > 0) this._sendRead();
        return this;
    }

    setReadThreshold(units) {
        this._readThreshold = units;
        if (this.isAttached && this._readInterval > 0) this._sendRead();
        return this;
    }

    // Register (or update) this browser's poll with the board.
    // Wire threshold is in tenths of a unit; 0 = board default.
    _sendRead() {
        this.arduino.send(encodeFrame(CMD_ULTRASONIC_READ, DEVICE_ULTRASONIC,
            [this.logicalId, this.unit, this._readInterval,
             Math.max(0, Math.round(this._readThreshold * 10))]));
    }

    _stopRead() {
        if (this._readInterval > 0) {
            this.arduino.send(encodeFrame(CMD_ULTRASONIC_READ, DEVICE_ULTRASONIC,
                [this.logicalId, this.unit, END]));   // END = unregister
        }
        this._readInterval = 0;
    }

    // -------------------------------------------------------------------
    // setTimeout(ms)
    // Sets the echo timeout on the Arduino (1–1000 ms).
    // Increase for longer range; decrease to speed up failed reads.
    // -------------------------------------------------------------------
    setTimeout(ms) {
        ms = Math.max(1, Math.min(1000, Math.round(ms)));
        this.timeoutMs = ms;
        this.arduino.send(encodeFrame(CMD_ULTRASONIC_SET_TIMEOUT, DEVICE_ULTRASONIC,
            [this.logicalId, ms]));
        return this;
    }

    // -------------------------------------------------------------------
    // Incoming frames from Arduino.
    // CMD_ULTRASONIC_ATTACH and CMD_ULTRASONIC_SET_TIMEOUT arrive during
    // announce (state sync) — silent updates, no event emission.
    // CMD_ULTRASONIC_READ is a poll response — updates state and emits.
    // -------------------------------------------------------------------
    handleMessage(frame) {
        switch (frame.cmd) {

            case CMD_ULTRASONIC_ATTACH:
                // Sync attach state from Arduino announce. The flag tells
                // _reRegister() to skip its replay — Arduino already knows.
                this.trigPin             = frame.params[1];
                this.echoPin             = frame.params[2] ?? -1;
                this.isAttached          = true;
                this._announcedByArduino = true;
                break;

            case CMD_ULTRASONIC_SET_TIMEOUT:
                // Sync timeout from Arduino announce
                this.timeoutMs = frame.params[1];
                break;

            case CMD_ULTRASONIC_READ: {
                const raw = frame.params[1];   // tenths of unit, or -1
                this.distance = (raw === -1) ? -1 : raw / 10;
                this._emit('change', { distance: this.distance, unit: this.unit });
                break;
            }
        }
    }

    // -------------------------------------------------------------------
    // Callback shortcut — the board only transmits meaningful changes
    // (>= threshold), so the event is 'change'.
    // -------------------------------------------------------------------
    onChange(fn) { return this.on('change', fn); }

    // -------------------------------------------------------------------
    // State snapshot
    // -------------------------------------------------------------------
    getState() {
        return {
            logicalId:  this.logicalId,
            trigPin:    this.trigPin,
            echoPin:    this.echoPin,
            attached:   this.isAttached,
            timeoutMs:  this.timeoutMs,
            distance:   this.distance,
            unit:       this.unit,
            interval:   this._readInterval,
            threshold:  this._readThreshold,
        };
    }
}

// Let the core materialise an Ultrasonic when the SKETCH creates one
// (PardaloteUltrasonic.attach("front", 7, 8) → CMD_SHARE → arduino.front).
registerExtensionType(Ultrasonic);

// ----- pardalote-imu.js --------------------------------------
// ==============================================================
// imu.js
// Pardalote Generic IMU Extension
// Part of Pardalote — version in package.json
// by Scott Mitchell
// GPL-3.0-or-later License
//
// Supports MPU-6050, MPU-6500, MPU-9250, MPU-9255,
//          LSM6DS3, LSM6DSOX (and future sensors added to
//          the SENSORS[] table in PardaloteIMU.h).
//
// Usage:
//   const arduino = new Arduino();
//   arduino.add('imu', new IMU('6050'));     // MPU-6050
//   arduino.add('imu', new IMU('LSM6DS3')); // STMicro LSM6DS3
//   arduino.connect('192.168.1.42');
//
//   arduino.on('ready', () => {
//       arduino.imu.attach();               // uses model default address
//       arduino.imu.attach(0x69);           // override I2C address
//       arduino.imu.attach(0x68, 21, 22);   // ESP32 custom SDA/SCL pins
//
//       arduino.imu.onChange(({ accel, gyro, temp }) => {
//           console.log('accel:', accel);  // { x, y, z } in g
//           console.log('gyro:',  gyro);   // { x, y, z } in °/s
//           console.log('temp:',  temp);   // °C
//       });
//       arduino.imu.read(20);              // poll every 20 ms (50 Hz)
//   });
//
// The model name string is sent in the payload of CMD_IMU_ATTACH and
// matched against SENSORS[i].name on the firmware side. Row order in
// SENSORS[] does not affect anything — the two tables are coupled only
// by the name string, so adding or reordering sensors on either side
// is safe.
// ==============================================================

const DEVICE_IMU = 203;

const CMD_IMU_ATTACH          = 0x28;
const CMD_IMU_DETACH          = 0x29;
const CMD_IMU_READ            = 0x2A;
const CMD_IMU_SET_ACCEL_RANGE = 0x2B;
const CMD_IMU_SET_GYRO_RANGE  = 0x2C;
const CMD_IMU_CALIBRATE       = 0x2D;

// Human-readable range labels indexed by range setting (0–3)
const IMU_ACCEL_RANGES = [2, 4, 8, 16];          // ± g
const IMU_GYRO_RANGES  = [250, 500, 1000, 2000];  // ± °/s

// -------------------------------------------------------------------
// IMU_MODELS — maps model name string to its DOF and default I2C address.
//
// The key is the wire identifier sent in the payload of CMD_IMU_ATTACH.
// It must match a SENSORS[i].name on the firmware side.
//
// dof  — degrees of freedom (6 or 9), for display only.
// addr — default I2C address used when attach() is called without
//         an address argument.
// -------------------------------------------------------------------
const IMU_MODELS = {
    // InvenSense / TDK MPU family
    '6050':     { dof: 6, addr: 0x68 },
    '6500':     { dof: 6, addr: 0x68 },
    '9250':     { dof: 9, addr: 0x68 },
    '9255':     { dof: 9, addr: 0x68 },
    // STMicroelectronics LSM6 family
    'LSM6DS3':  { dof: 6, addr: 0x6A },
    'LSM6DSOX': { dof: 6, addr: 0x6A },
};

class IMU extends Extension {
    static deviceId = DEVICE_IMU;

    // -------------------------------------------------------------------
    // constructor(model?)
    //
    // model — model number or string key from IMU_MODELS.
    //         Default: 6050
    //
    // Examples:
    //   new IMU()            → MPU-6050  (default)
    //   new IMU('6050')      → MPU-6050
    //   new IMU('9250')      → MPU-9250  (9-DOF)
    //   new IMU('LSM6DS3')   → LSM6DS3
    //   new IMU('LSM6DSOX')  → LSM6DSOX
    // -------------------------------------------------------------------
    constructor(model = '6050') {
        super();

        const def = IMU_MODELS[model];
        if (!def) {
            throw new Error(
                `IMU: unknown model "${model}". ` +
                `Valid options: ${Object.keys(IMU_MODELS).join(', ')}`
            );
        }

        this.model    = model;
        this.dof      = def.dof;
        this._defAddr = def.addr;

        // Hardware state
        this.isAttached = false;
        this.address    = def.addr;
        this.accelRange = 0;  // 0=±2g,   1=±4g,   2=±8g,   3=±16g
        this.gyroRange  = 0;  // 0=±250°/s 1=±500°/s 2=±1000°/s 3=±2000°/s

        // Latest sensor reading
        this.accel = { x: 0, y: 0, z: 0 };  // g
        this.gyro  = { x: 0, y: 0, z: 0 };  // °/s
        this.temp  = 0;                       // °C

        // Calibration offsets (received from Arduino after calibrate())
        this.calibration  = { ax: 0, ay: 0, az: 0, gx: 0, gy: 0, gz: 0 };
        this.isCalibrated = false;

        // Periodic read registration (board-side)
        this._readInterval = 0;

        // Set true when Arduino announces this IMU's attach state on connect.
        // _reRegister() uses this to skip re-sending CMD_IMU_ATTACH when the
        // Arduino is already in sync — only replay when it has reset.
        this._announcedByArduino = false;
    }

    // -------------------------------------------------------------------
    // attach(address?, sda?, scl?)
    //
    // address  — I2C address. Defaults to the model's standard address.
    //             MPU family: 0x68 (AD0 LOW) or 0x69 (AD0 HIGH)
    //             LSM6 family: 0x6A (SA0 LOW) or 0x6B (SA0 HIGH)
    // sda, scl — custom I2C pins for ESP32 (-1 = use board default).
    //             Only sent when both are ≥ 0.
    // -------------------------------------------------------------------
    attach(address, sda = -1, scl = -1) {
        address       = address ?? this._defAddr;
        this.address  = address;
        this.isAttached = true;

        // Model name travels in the payload; SDA/SCL (ESP32 only) are params 2/3.
        const params = [this.logicalId, address];
        if (sda >= 0 && scl >= 0) params.push(sda, scl);
        this.arduino.send(encodeFrame(CMD_IMU_ATTACH, DEVICE_IMU, params, this.model));
        return this;
    }

    // -------------------------------------------------------------------
    // detach()
    // -------------------------------------------------------------------
    detach() {
        this._stopRead();
        this.arduino.send(encodeFrame(CMD_IMU_DETACH, DEVICE_IMU, [this.logicalId]));
        this.isAttached = false;
        return this;
    }

    // -------------------------------------------------------------------
    // read(interval?)
    //
    // read()          — request one reading; 'change' event fires on response.
    // read(interval)  — board-side poll every interval ms; 'change' fires
    //                   each sample. No threshold: IMU streams are usually
    //                   integrated/smoothed in JS, where dropped samples
    //                   cause drift — every registered browser receives
    //                   every sample at its own rate, from ONE I2C
    //                   transaction per poll tick.
    // read(END)       — stop this browser's periodic poll.
    //
    // Keep the interval ≥ 10 ms for stable results; 20–50 ms is typical.
    // -------------------------------------------------------------------
    read(interval) {
        if (interval === END) {
            this._stopRead();
            return this;
        }
        if (this._readInterval > 0 &&
            (interval === undefined || interval === this._readInterval)) {
            return this;
        }
        if (interval !== undefined) {
            this._readInterval = interval;
            this._sendRead();
        } else {
            this._sendReadRequest();   // one-shot
        }
        return this;
    }

    // setReadInterval(ms) — set the poll rate directly; applied immediately
    // if polling, stored for read() otherwise.
    setReadInterval(ms) {
        this._readInterval = ms;
        if (this.isAttached && ms > 0) this._sendRead();
        return this;
    }

    // Register (or update) this browser's board-side poll.
    _sendRead() {
        if (!this.isAttached) return;
        this.arduino.send(encodeFrame(CMD_IMU_READ, DEVICE_IMU,
            [this.logicalId, this._readInterval]));
    }

    _sendReadRequest() {
        if (!this.isAttached) return;
        this.arduino.send(encodeFrame(CMD_IMU_READ, DEVICE_IMU, [this.logicalId]));
    }

    _stopRead() {
        if (this._readInterval > 0 && this.isAttached) {
            this.arduino.send(encodeFrame(CMD_IMU_READ, DEVICE_IMU,
                [this.logicalId, END]));   // END = unregister
        }
        this._readInterval = 0;
    }

    // -------------------------------------------------------------------
    // setAccelRange(g)
    //
    // g — one of 2, 4, 8, 16. Sets the accelerometer ±g range.
    //
    // Higher range → less sensitivity but handles larger accelerations.
    // Default ±2g gives the finest resolution for gentle motion.
    // Unknown values are rejected with a console warning; the current
    // range is left unchanged.
    // -------------------------------------------------------------------
    setAccelRange(g) {
        const idx = IMU_ACCEL_RANGES.indexOf(g);
        if (idx === -1) {
            this._warn(`invalid accel range ±${g}g — valid values: ${IMU_ACCEL_RANGES.join(', ')}`);
            return this;
        }
        this.accelRange = idx;
        this.arduino.send(encodeFrame(CMD_IMU_SET_ACCEL_RANGE, DEVICE_IMU,
            [this.logicalId, idx]));
        return this;
    }

    // -------------------------------------------------------------------
    // setGyroRange(dps)
    //
    // dps — one of 250, 500, 1000, 2000. Sets the gyroscope ±°/s range.
    //
    // Default ±250°/s gives the finest resolution for slow rotation.
    // Use ±2000°/s for fast spins (e.g. RC vehicles, drones).
    // Unknown values are rejected with a console warning; the current
    // range is left unchanged.
    // -------------------------------------------------------------------
    setGyroRange(dps) {
        const idx = IMU_GYRO_RANGES.indexOf(dps);
        if (idx === -1) {
            this._warn(`invalid gyro range ±${dps}°/s — valid values: ${IMU_GYRO_RANGES.join(', ')}`);
            return this;
        }
        this.gyroRange = idx;
        this.arduino.send(encodeFrame(CMD_IMU_SET_GYRO_RANGE, DEVICE_IMU,
            [this.logicalId, idx]));
        return this;
    }

    // -------------------------------------------------------------------
    // calibrate(samples?)
    //
    // Place the sensor flat with Z pointing UP and call this once.
    // The Arduino collects `samples` readings (default 200) and computes
    // offset corrections applied to all subsequent reads.
    //
    // After calibration:
    //   accel: x ≈ 0g, y ≈ 0g, z ≈ +1g  (gravity preserved on Z axis)
    //   gyro:  x ≈ 0,  y ≈ 0,  z ≈ 0
    //
    // The 'calibrate' event fires when the Arduino finishes (~400 ms at
    // 200 samples). The WebSocket will be unresponsive during this time.
    //
    // Calibration offsets are re-sent during announce so a reconnecting
    // browser receives the current offsets without re-running the process.
    // -------------------------------------------------------------------
    calibrate(samples = 200) {
        if (!this.isAttached) {
            this._warn('not attached');
            return this;
        }
        this.arduino.send(encodeFrame(CMD_IMU_CALIBRATE, DEVICE_IMU,
            [this.logicalId, samples]));
        return this;
    }

    // -------------------------------------------------------------------
    // Callback shortcuts
    // -------------------------------------------------------------------
    onChange(fn)    { return this.on('change',    fn); }
    onCalibrate(fn) { return this.on('calibrate', fn); }

    // -------------------------------------------------------------------
    // Convenience getters
    // -------------------------------------------------------------------
    get accelRangeG()  { return IMU_ACCEL_RANGES[this.accelRange]; }
    get gyroRangeDps() { return IMU_GYRO_RANGES[this.gyroRange]; }

    // -------------------------------------------------------------------
    // Board switch — called by Arduino.connect() to wipe per-board state.
    // Identity fields (model, _defAddr, dof) are constructor-set
    // and preserved; the announce-drift handler in handleMessage refreshes
    // them if the new board reports a different sensor.
    // -------------------------------------------------------------------
    _reset() {
        this._readInterval       = 0;   // registration died with the old board — send nothing
        this.isAttached          = false;
        this.address             = this._defAddr;
        this.accelRange          = 0;
        this.gyroRange           = 0;
        this.accel               = { x: 0, y: 0, z: 0 };
        this.gyro                = { x: 0, y: 0, z: 0 };
        this.temp                = 0;
        this.calibration         = { ax: 0, ay: 0, az: 0, gx: 0, gy: 0, gz: 0 };
        this.isCalibrated        = false;
        this._announcedByArduino = false;
    }

    // -------------------------------------------------------------------
    // Reconnect — restores attach and range state on Arduino reset.
    // Calibration offsets are stored on the Arduino and re-sent during
    // announce — they do not need to be replayed from JS.
    // -------------------------------------------------------------------
    _reRegister() {
        if (!this.isAttached) {
            this._announcedByArduino = false;
            return;
        }

        // Only replay attach/ranges if the Arduino didn't announce us — i.e.
        // it has reset and lost state. If announce did sync us, skip the
        // replay (avoids duplicate Serial output and redundant I2C init).
        if (!this._announcedByArduino) {
            // Model name in payload so the firmware re-initialises the correct sensor.
            this.arduino.send(encodeFrame(CMD_IMU_ATTACH, DEVICE_IMU,
                [this.logicalId, this.address], this.model));
            if (this.accelRange !== 0)
                this.arduino.send(encodeFrame(CMD_IMU_SET_ACCEL_RANGE, DEVICE_IMU,
                    [this.logicalId, this.accelRange]));
            if (this.gyroRange !== 0)
                this.arduino.send(encodeFrame(CMD_IMU_SET_GYRO_RANGE, DEVICE_IMU,
                    [this.logicalId, this.gyroRange]));
        }

        // Periodic read registrations are per-WS-client on the Arduino
        // (cleared on disconnect), so always re-register if active.
        if (this._readInterval > 0) this._sendRead();

        this._announcedByArduino = false;  // reset for next reconnect cycle
    }

    // -------------------------------------------------------------------
    // Incoming frames from Arduino
    // -------------------------------------------------------------------
    handleMessage(frame) {
        switch (frame.cmd) {

            // State sync during announce — update local state silently.
            // Params: [id, addr], payload: model name string.
            case CMD_IMU_ATTACH:
                this.address             = frame.params[1];
                this.isAttached          = true;
                this._announcedByArduino = true;
                // If the firmware reports a different model than this instance
                // was constructed with (different firmware build, board swap,
                // multi-client race), refresh model/dof to match. Range and
                // calibration settings are intentionally preserved.
                if (frame.payload) {
                    const newModel = new TextDecoder().decode(frame.payload);
                    if (newModel !== this.model) {
                        const entry = IMU_MODELS[newModel];
                        if (entry) {
                            this.model = newModel;
                            this.dof   = entry.dof;
                        } else {
                            this._warn(`firmware reports unknown model "${newModel}" — add it to IMU_MODELS in imu.js`);
                            this.model = newModel;
                            this.dof   = 0;
                        }
                    }
                }
                break;

            case CMD_IMU_SET_ACCEL_RANGE:
                this.accelRange = frame.params[1];
                break;

            case CMD_IMU_SET_GYRO_RANGE:
                this.gyroRange = frame.params[1];
                break;

            // Poll response — update readings and fire 'change' event.
            // Params: [id, ax, ay, az, gx, gy, gz, temp]  (floats)
            case CMD_IMU_READ:
                this.accel.x = frame.params[1];
                this.accel.y = frame.params[2];
                this.accel.z = frame.params[3];
                this.gyro.x  = frame.params[4];
                this.gyro.y  = frame.params[5];
                this.gyro.z  = frame.params[6];
                this.temp    = frame.params[7];
                this._emit('change', {
                    accel: { ...this.accel },
                    gyro:  { ...this.gyro },
                    temp:  this.temp,
                });
                break;

            // Calibration complete (or announce sync of existing offsets).
            // Params: [id, ax, ay, az, gx, gy, gz]  (floats)
            case CMD_IMU_CALIBRATE:
                this.calibration = {
                    ax: frame.params[1], ay: frame.params[2], az: frame.params[3],
                    gx: frame.params[4], gy: frame.params[5], gz: frame.params[6],
                };
                this.isCalibrated = true;
                this._emit('calibrate', { ...this.calibration });
                break;
        }
    }

    // -------------------------------------------------------------------
    // State snapshot
    // -------------------------------------------------------------------
    getState() {
        const modelName = this.model;
        return {
            logicalId:    this.logicalId,
            model:        modelName,
            dof:          this.dof,
            address:      `0x${this.address.toString(16).toUpperCase()}`,
            attached:     this.isAttached,
            accelRange:   `±${this.accelRangeG}g`,
            gyroRange:    `±${this.gyroRangeDps}°/s`,
            accel:        { ...this.accel },
            gyro:         { ...this.gyro },
            temp:         this.temp,
            calibrated:   this.isCalibrated,
            calibration:  { ...this.calibration },
        };
    }
}

// Let the core materialise an IMU when the SKETCH creates one
// (PardaloteIMU.attach("imu", "6050") → CMD_SHARE → arduino.imu).
registerExtensionType(IMU);

// ----- pardalote-encoder.js ----------------------------------
// ==============================================================
// encoder.js
// Pardalote Rotary Encoder Extension (quadrature)
// Part of Pardalote — version in package.json
// by Scott Mitchell
// GPL-3.0-or-later License
//
// Quadrature encoders: KY-040 style knobs, optical/magnetic motor
// shaft encoders. The BOARD counts edges in interrupt handlers (a 4x
// state-table decoder — immune to contact bounce and to edge rates
// far beyond what polling could see); the browser receives the
// absolute position, rate-limited per browser.
//
// Usage:
//   const arduino = new Arduino();
//   arduino.add('knob', new Encoder());
//   arduino.connect('192.168.1.42');
//
//   arduino.on('ready', () => {
//       arduino.knob.attach(D2, D3);        // pinA, pinB
//       arduino.knob.read(50);              // updates at most every 50 ms
//   });
//
//   arduino.knob.on('change', ({ position, delta, detents }) => {
//       volume += delta;
//   });
//
// Position is in RAW QUADRATURE STEPS (a KY-040 detent = 4 steps);
// setStepsPerDetent() scales the `detents` convenience property.
// The KY-040's push button is just a switch — wire it to any pin and
// use arduino.pin(SW).on('change', …), which delivers debounced
// edges instantly.
//
// Encoders created BY THE SKETCH (PardaloteEncoder.attach("knob", 2, 3))
// appear automatically as arduino.knob — no arduino.add() needed.
// ==============================================================

const DEVICE_ENCODER = 207;

const CMD_ENCODER_ATTACH       = 0x58;
const CMD_ENCODER_DETACH       = 0x59;
const CMD_ENCODER_READ         = 0x5A;
const CMD_ENCODER_SET_POSITION = 0x5B;

class Encoder extends Extension {
    static deviceId = DEVICE_ENCODER;

    constructor() {
        super();

        // Hardware state
        this.pinA       = -1;
        this.pinB       = -1;
        this.isAttached = false;

        // Position — raw quadrature steps, absolute. null until the first
        // value arrives (announce seed or read response); the mirror seeds
        // silently, so 'change' never fires with a phantom delta.
        this.position = null;

        // Detent scaling for the `detents` convenience (KY-040: 4).
        this.stepsPerDetent = 4;

        // Periodic read registration (board-side). _readThreshold is in
        // raw steps; 0 = board default (1 — every step). Survives _reset().
        this._readInterval  = 0;
        this._readThreshold = 0;

        // Set true when the Arduino announces this encoder's attach state
        // on connect — _reRegister() then skips the replay.
        this._announcedByArduino = false;
    }

    // Position scaled to detents (rounded).
    get detents() {
        return Math.round((this.position ?? 0) / this.stepsPerDetent);
    }

    setStepsPerDetent(n) { this.stepsPerDetent = Math.max(1, n); return this; }

    // -------------------------------------------------------------------
    // Board switch — wipe per-board state, keep user-tuned config.
    // -------------------------------------------------------------------
    _reset() {
        this._readInterval = 0;   // registration died with the old board — send nothing
        this.pinA          = -1;
        this.pinB          = -1;
        this.isAttached    = false;
        this.position      = null;
        this._announcedByArduino = false;
    }

    // -------------------------------------------------------------------
    // Reconnection — replay attach only if the Arduino reset; always
    // re-register the read stream (per-client state died with the socket).
    // -------------------------------------------------------------------
    _reRegister() {
        if (this.isAttached) {
            if (!this._announcedByArduino) this._sendAttach();
            if (this._readInterval > 0) this._sendRead();
        }
        this._announcedByArduino = false;
    }

    // -------------------------------------------------------------------
    // attach(pinA, pinB) — the two quadrature signal pins. The board
    // enables pullups and attaches CHANGE interrupts on both.
    // -------------------------------------------------------------------
    attach(pinA, pinB) {
        this.pinA       = this.arduino._resolvePin(pinA);
        this.pinB       = this.arduino._resolvePin(pinB);
        this.isAttached = true;
        this.position   = null;   // seeded by the board's response
        this._sendAttach();
        return this;
    }

    _sendAttach() {
        this.arduino.send(encodeFrame(CMD_ENCODER_ATTACH, DEVICE_ENCODER,
            [this.logicalId, this.pinA, this.pinB]));
    }

    detach() {
        this._stopRead();
        this.arduino.send(encodeFrame(CMD_ENCODER_DETACH, DEVICE_ENCODER,
            [this.logicalId]));
        this.isAttached = false;
        this.pinA = this.pinB = -1;
        return this;
    }

    // -------------------------------------------------------------------
    // read(interval?, threshold?)
    // read()             — return cached position; no network traffic.
    // read(interval)     — stream position changes, at most one update
    //                      per `interval` ms to THIS browser.
    // read(interval, 4)  — only changes of 4+ steps (one KY-040 detent).
    // read(END)          — stop this browser's stream.
    // The board counts continuously either way (interrupts) — the
    // interval is purely a rate limit, and because position is absolute
    // the latest value always carries the full state.
    // -------------------------------------------------------------------
    read(interval, threshold) {
        if (!this.isAttached) {
            this._warn('not attached');
            return this.position ?? 0;
        }
        if (interval === END) { this._stopRead(); return this.position ?? 0; }
        if (this._readInterval > 0
            && (interval  === undefined || interval  === this._readInterval)
            && (threshold === undefined || threshold === this._readThreshold)) {
            return this.position ?? 0;
        }
        this._readInterval = interval ?? this.arduino.defaultInterval;
        if (threshold !== undefined) this._readThreshold = threshold;
        this._sendRead();
        return this.position ?? 0;
    }

    // setReadInterval(ms) / setReadThreshold(steps) — set stream settings
    // directly; applied immediately if streaming, stored for read() otherwise.
    setReadInterval(ms) {
        this._readInterval = ms;
        if (this.isAttached && ms > 0) this._sendRead();
        return this;
    }

    setReadThreshold(steps) {
        this._readThreshold = steps;
        if (this.isAttached && this._readInterval > 0) this._sendRead();
        return this;
    }

    _sendRead() {
        this.arduino.send(encodeFrame(CMD_ENCODER_READ, DEVICE_ENCODER,
            [this.logicalId, this._readInterval,
             Math.max(0, Math.round(this._readThreshold))]));
    }

    _stopRead() {
        if (this._readInterval > 0) {
            this.arduino.send(encodeFrame(CMD_ENCODER_READ, DEVICE_ENCODER,
                [this.logicalId, END]));   // END = unregister
        }
        this._readInterval = 0;
    }

    // -------------------------------------------------------------------
    // setPosition(value) / zero() — re-declare the current physical
    // position. The board sets its counter and echoes the new position
    // to every browser, so all mirrors adopt the new frame together.
    // -------------------------------------------------------------------
    setPosition(value) {
        if (!this.isAttached) { this._warn('not attached'); return this; }
        this.arduino.send(encodeFrame(CMD_ENCODER_SET_POSITION, DEVICE_ENCODER,
            [this.logicalId, Math.round(value)]));
        return this;
    }

    zero() { return this.setPosition(0); }

    // -------------------------------------------------------------------
    // Incoming frames
    // -------------------------------------------------------------------
    handleMessage(frame) {
        switch (frame.cmd) {

            case CMD_ENCODER_ATTACH:
                // Announce sync — the board already has this encoder.
                this.pinA = frame.params[1];
                this.pinB = frame.params[2];
                this.isAttached          = true;
                this._announcedByArduino = true;
                break;

            case CMD_ENCODER_READ: {
                const pos  = frame.params[1];
                const prev = this.position;
                this.position = pos;
                // First value (announce/attach seed) fills the mirror
                // silently; after that, any movement fires 'change'.
                if (prev !== null && pos !== prev) {
                    this._emit('change', {
                        position: pos,
                        delta:    pos - prev,
                        detents:  this.detents,
                    });
                }
                break;
            }
        }
    }

    // -------------------------------------------------------------------
    // Callback shortcut
    // -------------------------------------------------------------------
    onChange(fn) { return this.on('change', fn); }

    // -------------------------------------------------------------------
    // State snapshot
    // -------------------------------------------------------------------
    getState() {
        return {
            logicalId:      this.logicalId,
            pinA:           this.pinA,
            pinB:           this.pinB,
            attached:       this.isAttached,
            position:       this.position ?? 0,
            detents:        this.detents,
            stepsPerDetent: this.stepsPerDetent,
            interval:       this._readInterval,
            threshold:      this._readThreshold,
        };
    }
}

// Let the core materialise an Encoder when the SKETCH creates one
// (PardaloteEncoder.attach("knob", 2, 3) → CMD_SHARE → arduino.knob).
registerExtensionType(Encoder);

// ----- pardalote-camera.js -----------------------------------
// ==============================================================
// camera.js
// Pardalote Camera Extension
// Part of Pardalote — version in package.json
// by Scott Mitchell
// GPL-3.0-or-later License
//
// Streams MJPEG video and fetches JPEG snapshots from an
// ESP32-S3 camera module via HTTP. Video never flows over the
// WebSocket — the browser connects to the Arduino's HTTP server
// directly, so MJPEG frames don't compete with control messages.
//
// Usage:
//   const arduino = new Arduino();
//   arduino.add('cam', new Camera());
//   arduino.connect('192.168.1.42');
//
//   arduino.on('ready', () => {
//       arduino.cam.attach(82);   // start camera HTTP server on port 82
//   });
//
//   arduino.cam.on('stream', ({ url, element }) => {
//       // element is a ready <img> — pass it to p5.js image() or
//       // append it to the DOM directly.
//       document.body.appendChild(element);
//   });
//
// p5.js integration:
//   let camEl;
//   arduino.cam.on('stream', ({ element }) => { camEl = element; });
//
//   function draw() {
//       if (camEl) image(camEl, 0, 0);
//       loadPixels();  // pixels[] now contains the camera frame
//   }
//
// Note: loadPixels() requires the ESP32 to send CORS headers, which
// PardaloteCamera.h sets automatically on both HTTP endpoints.
// ==============================================================

const DEVICE_CAMERA = 204;

const CMD_CAMERA_INIT        = 0x30;
const CMD_CAMERA_SET_RES     = 0x31;
const CMD_CAMERA_SET_QUALITY = 0x32;

// -------------------------------------------------------------------
// Framesize constants — mirror ESP32 camera framesize_t enum values.
// Pass one of these to setResolution().
// -------------------------------------------------------------------
const FRAMESIZE_96X96   = 0;
const FRAMESIZE_QQVGA   = 1;   // 160×120
const FRAMESIZE_QCIF    = 2;   // 176×144
const FRAMESIZE_HQVGA   = 3;   // 240×176
const FRAMESIZE_240X240 = 4;
const FRAMESIZE_QVGA    = 5;   // 320×240  ← default
const FRAMESIZE_CIF     = 6;   // 400×296
const FRAMESIZE_HVGA    = 7;   // 480×320
const FRAMESIZE_VGA     = 8;   // 640×480
const FRAMESIZE_SVGA    = 9;   // 800×600
const FRAMESIZE_XGA     = 10;  // 1024×768
const FRAMESIZE_HD      = 11;  // 1280×720

class Camera extends Extension {
    static deviceId = DEVICE_CAMERA;

    constructor() {
        super();

        this._port        = null;    // null until attach() is called
        this._streamUrl   = null;
        this._snapshotUrl = null;
        this._el          = null;    // <img> element pointing at the stream
        this._pendingInit = false;   // true when we sent CMD_CAMERA_INIT and await confirmation

        this.framesize = FRAMESIZE_QVGA;
        this.quality   = 12;         // 0 = best, 63 = worst (ESP32 convention)
    }

    // -------------------------------------------------------------------
    // Board switch — called by Arduino.connect() to wipe per-board state
    // while preserving user-tuned configuration (framesize, quality).
    // -------------------------------------------------------------------
    _reset() {
        if (this._el) {
            this._el.src = '';
            this._el     = null;
        }
        this._port        = null;
        this._streamUrl   = null;
        this._snapshotUrl = null;
        this._pendingInit = false;
    }

    // -------------------------------------------------------------------
    // Reconnection — called by Arduino core after every reconnect.
    // Re-sends CMD_CAMERA_INIT so the Arduino reconfirms the stream port.
    // -------------------------------------------------------------------
    _reRegister() {
        if (this._port !== null) this._sendInit();
    }

    // -------------------------------------------------------------------
    // attach(port?)
    // Start the camera HTTP server on the Arduino.
    // Emits 'stream' when the Arduino confirms. Default port is 82.
    // -------------------------------------------------------------------
    attach(port = 82) {
        this._port = port;
        this._sendInit();
        return this;
    }

    _sendInit() {
        this._pendingInit = true;
        this.arduino.send(encodeFrame(
            CMD_CAMERA_INIT, DEVICE_CAMERA,
            [this.logicalId, this._port]
        ));
        // Replay our desired framesize + quality right after init. The board
        // always inits at its own defaults, and the reliable way to change the
        // frame size is the post-init set_framesize() path — so we push our
        // state here. This makes setResolution()/setQuality() work when called
        // BEFORE attach(), and keeps resolution/quality in sync across a
        // reconnect (which re-inits the board back to defaults).
        this.arduino.send(encodeFrame(
            CMD_CAMERA_SET_RES, DEVICE_CAMERA,
            [this.logicalId, this.framesize]
        ));
        this.arduino.send(encodeFrame(
            CMD_CAMERA_SET_QUALITY, DEVICE_CAMERA,
            [this.logicalId, this.quality]
        ));
    }

    // -------------------------------------------------------------------
    // detach()
    // Clear the local stream reference and stop pointing the img element
    // at the stream. The HTTP server keeps running on the Arduino.
    // -------------------------------------------------------------------
    detach() {
        if (this._el) {
            this._el.src = '';
            this._el     = null;
        }
        this._port        = null;
        this._streamUrl   = null;
        this._snapshotUrl = null;
        this._pendingInit = false;
        return this;
    }

    // -------------------------------------------------------------------
    // setResolution(framesize)
    // Change the camera frame size. Use the FRAMESIZE_* constants above.
    // Takes effect on the next captured frame.
    // -------------------------------------------------------------------
    setResolution(framesize) {
        this.framesize = framesize;
        this.arduino.send(encodeFrame(
            CMD_CAMERA_SET_RES, DEVICE_CAMERA,
            [this.logicalId, framesize]
        ));
        return this;
    }

    // -------------------------------------------------------------------
    // setQuality(q)
    // JPEG quality: 0 = best image, highest bandwidth.
    //               63 = worst image, lowest bandwidth.
    // Lower values (better quality) increase frame size and reduce fps.
    // -------------------------------------------------------------------
    setQuality(quality) {
        this.quality = Math.max(0, Math.min(63, Math.round(quality)));
        this.arduino.send(encodeFrame(
            CMD_CAMERA_SET_QUALITY, DEVICE_CAMERA,
            [this.logicalId, this.quality]
        ));
        return this;
    }

    // -------------------------------------------------------------------
    // getElement()
    // Returns the <img> DOM element pointed at the live MJPEG stream.
    // Pass directly to p5's image(), or append to the DOM.
    // Returns null if attach() has not been called yet.
    // -------------------------------------------------------------------
    getElement() {
        if (!this._streamUrl) return null;
        if (!this._el) {
            this._el = document.createElement('img');
            this._el.src = this._streamUrl;
        }
        return this._el;
    }

    // -------------------------------------------------------------------
    // snapshot()
    // Fetch a single JPEG still from the Arduino over HTTP.
    // Returns a Promise that resolves to a blob: URL, or null on error.
    // The 'snapshot' event fires with { url, blob } when the image arrives.
    //
    // Revoke the returned URL when you're done with it:
    //   URL.revokeObjectURL(url);
    // -------------------------------------------------------------------
    async snapshot() {
        if (!this._snapshotUrl) {
            this._warn('call attach() before snapshot()');
            return null;
        }
        try {
            const res = await fetch(this._snapshotUrl);
            if (!res.ok) throw new Error(`HTTP ${res.status}`);
            const blob = await res.blob();
            const url  = URL.createObjectURL(blob);
            this._emit('snapshot', { url, blob });
            return url;
        } catch (e) {
            this._error(`snapshot failed — ${e.message}`);
            return null;
        }
    }

    // -------------------------------------------------------------------
    // Callback shortcuts
    // -------------------------------------------------------------------
    onStream(fn)   { return this.on('stream',   fn); }
    onSnapshot(fn) { return this.on('snapshot', fn); }
    onError(fn)    { return this.on('error',    fn); }

    // -------------------------------------------------------------------
    // State snapshot
    // -------------------------------------------------------------------
    getState() {
        return {
            logicalId:   this.logicalId,
            port:        this._port,
            streamUrl:   this._streamUrl,
            snapshotUrl: this._snapshotUrl,
            framesize:   this.framesize,
            quality:     this.quality,
        };
    }

    // -------------------------------------------------------------------
    // Incoming frames from Arduino.
    // CMD_CAMERA_INIT arrives when the HTTP server is confirmed live.
    // -------------------------------------------------------------------
    handleMessage(frame) {
        if (frame.cmd !== CMD_CAMERA_INIT) return;

        // The Arduino broadcasts CMD_CAMERA_INIT to every connected client
        // whenever any client calls attach(). _pendingInit lets us rebuild
        // the URL only in response to OUR own attach() — without it, a
        // second client joining would tear down and recreate this client's
        // already-working <img> element (the cache-buster changes the URL).
        if (!this._pendingInit) return;
        this._pendingInit = false;

        const port = frame.params[1];
        const ip   = this._extractIp();
        if (!ip) return;

        // Append a cache-buster so the browser opens a fresh TCP connection
        // on every reconnect, even when the Arduino's IP:port is unchanged.
        // The Arduino's wildcard URI handler strips the query string before routing.
        const t = Date.now();
        this._streamUrl   = `http://${ip}:${port}/stream?_t=${t}`;
        this._snapshotUrl = `http://${ip}:${port}/snapshot`;

        // Abort any old lazy element before the stream event fires so the
        // browser closes the previous MJPEG connection immediately.
        if (this._el) {
            this._el.src = '';
            this._el = null;
        }

        this._emit('stream', {
            url:     this._streamUrl,
            element: null,
        });
    }

    // -------------------------------------------------------------------
    // Internal helpers
    // -------------------------------------------------------------------

    // Extract the bare IP from arduino.deviceIP ("ws://ip:port/").
    _extractIp() {
        const m = this.arduino.deviceIP && this.arduino.deviceIP.match(/ws:\/\/([^:/]+)/);
        if (!m) { this._error('cannot parse Arduino IP'); return null; }
        return m[1];
    }
}

